/* GCHE2 · Temas de estudio armados: resumen, 30 preguntas tipo ENARM, repaso en audio y fuentes. Redactados con palabras propias a partir de la bibliografía citada en cada tema. Solo enlaces a sitios .gob.mx. */
window.SXTEMAS={"cardiologia-14":{"titulo":"Hipertensión arterial en la consulta","enfoque":"Enfoque de consulta de primer nivel: medición correcta, confirmación del diagnóstico, metas, tratamiento escalonado y manejo de la crisis hipertensiva.","resumen":[{"h":"Lo esencial en 30 segundos","li":["Hipertensión: presión en consultorio de **140/90 mmHg o más**, confirmada en al menos dos visitas o con mediciones fuera del consultorio.","Es el principal factor de riesgo de **evento vascular cerebral** y de enfermedad cardiovascular; casi siempre es asintomática.","La causa más frecuente es la **esencial**; entre las secundarias, las **renales**, y entre las endocrinas, el **hiperaldosteronismo primario**.","Todos reciben medidas de estilo de vida; la mayoría inicia con **doble terapia**, de preferencia en una sola tableta.","Meta: **menor de 130/80 mmHg** si se tolera; en adultos mayores frágiles, presión sistólica de 140 a 150 mmHg."]},{"h":"Clasificación en consultorio","li":["Óptima: menor de 120/80. Normal: 120 a 129 y/o 80 a 84. Normal alta: 130 a 139 y/o 85 a 89.","**Grado 1**: 140 a 159 y/o 90 a 99. **Grado 2**: 160 a 179 y/o 100 a 109. **Grado 3**: 180 o más y/o 110 o más.","Sistólica aislada: 140 o más con diastólica menor de 90; típica del adulto mayor por rigidez arterial.","Fuera del consultorio: con medición en casa, **135/85** o más; con monitoreo de 24 horas, 135/85 de día y **120/70 de noche**."]},{"h":"Cómo medir bien","li":["Paciente sentado **5 minutos** en reposo, espalda apoyada, piernas sin cruzar, brazo descubierto y apoyado a la altura del corazón.","Sin café, tabaco ni ejercicio en los 30 minutos previos; vejiga vacía; sin hablar.","Brazalete del tamaño correcto: uno pequeño da cifras falsamente altas.","La primera vez, medir **ambos brazos** y usar el más alto. Tomar 2 o 3 lecturas separadas 1 a 2 minutos y promediar.","El protocolo del Instituto Mexicano del Seguro Social confirma con monitoreo en casa: **dos mediciones al día por 10 días**."]},{"h":"Fenómenos que se preguntan","li":["**Bata blanca**: alta en consultorio, normal fuera. **Enmascarada**: normal en consultorio, alta fuera; se trata como hipertensión.","**Patrón non-dipper**: la presión no baja de noche; obliga a buscar **apnea obstructiva del sueño**.","**Seudohipertensión** del anciano por arterias rígidas: signo de Osler (la radial se sigue palpando con el brazalete inflado)."]},{"h":"Evaluación inicial","li":["Laboratorio: glucosa, creatinina con filtración glomerular, sodio y potasio, perfil de lípidos, ácido úrico, biometría hemática y examen general de orina con albuminuria.","Electrocardiograma (busca **hipertrofia ventricular izquierda**) y fondo de ojo.","Estimar el riesgo cardiovascular global y buscar daño a órgano blanco: corazón, riñón, cerebro, retina y arterias periféricas."]},{"h":"Cuándo sospechar hipertensión secundaria","li":["Inicio **antes de los 30 años** o descontrol súbito en un hipertenso antes controlado.","Hipertensión resistente o grado 3, o daño a órgano blanco desproporcionado.","**Hipopotasemia** espontánea con alcalosis metabólica: hiperaldosteronismo primario.","Crisis de cefalea, sudoración y palpitaciones: feocromocitoma.","Elevación de creatinina más de 30% al iniciar un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina: estenosis de arteria renal.","Ronquido, somnolencia diurna y obesidad: apnea obstructiva del sueño.","Fármacos: **antiinflamatorios no esteroideos**, anticonceptivos orales, corticoides, descongestionantes, alcohol."]},{"h":"Estilo de vida para todos","li":["Sal **menor de 5 g al día** (una cucharadita).","Ejercicio aeróbico **30 minutos al día**, 5 a 7 días por semana.","Bajar de peso: por cada 5 kg perdidos baja la presión sistólica unos 5 mmHg y la diastólica unos 3 mmHg.","Alcohol: menos de 20 g al día en hombres y menos de 10 g en mujeres; dejar de fumar.","Dieta rica en frutas y verduras (dieta DASH, siglas en inglés de enfoques dietéticos para detener la hipertensión)."]},{"h":"Cuándo iniciar fármacos","li":["**Grados 2 y 3**: fármaco desde el inicio, junto con estilo de vida.","**Grado 1 con alto riesgo** (diabetes, enfermedad renal, enfermedad cardiovascular o daño a órgano blanco): fármaco desde el inicio.","Grado 1 de bajo riesgo: 3 a 6 meses de estilo de vida y, si no se controla, fármaco.","Presión normal alta: no se dan fármacos."]},{"h":"Esquema farmacológico por pasos","li":["**Paso 1, doble terapia**: inhibidor de la enzima convertidora de angiotensina o antagonista del receptor de angiotensina II **más** calcioantagonista o diurético tiazídico. Monoterapia solo en grado 1 de bajo riesgo o en adultos mayores frágiles.","**Paso 2, triple terapia**: los tres grupos juntos.","**Paso 3**: agregar **espironolactona** (revisar antes potasio y función renal).","Los betabloqueadores se usan en cualquier paso si hay indicación: cardiopatía isquémica, insuficiencia cardiaca, control de frecuencia en fibrilación auricular.","**Nunca** combinar un inhibidor de la enzima convertidora con un antagonista del receptor de angiotensina II.","El protocolo del Instituto Mexicano del Seguro Social inicia con inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más indapamida o hidroclorotiazida, y agrega calcioantagonista si no hay meta en 2 semanas."]},{"h":"Dosis habituales en adultos","li":["Losartán: **50 mg una vez al día**; rango de 25 a 100 mg al día.","Enalapril: inicio **5 mg al día** (2.5 mg si toma diurético); mantenimiento de 10 a 40 mg al día en 1 o 2 tomas.","Amlodipino: **5 mg una vez al día**, máximo 10 mg; 2.5 mg en adultos mayores frágiles.","Hidroclorotiazida o clortalidona: 12.5 a 25 mg una vez al día.","Vigilar creatinina y potasio a las 1 a 2 semanas de iniciar o subir un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina."]},{"h":"Qué fármaco según el paciente","li":["Diabetes, albuminuria o enfermedad renal crónica: **inhibidor de la enzima convertidora o antagonista del receptor de angiotensina II**.","Adulto mayor con sistólica aislada: **calcioantagonista** o tiazida.","Embarazo: **alfametildopa**, labetalol o nifedipino. **Contraindicados** inhibidores de la enzima convertidora y antagonistas del receptor de angiotensina.","Hiperplasia prostática: alfabloqueador como fármaco agregado.","Asma: **evitar betabloqueadores**.","Gota: evitar tiazidas. Tos seca con enalapril: cambiar a un antagonista del receptor de angiotensina II.","Edema de tobillos con amlodipino: efecto de clase de las dihidropiridinas, no es insuficiencia cardiaca."]},{"h":"Hipertensión resistente","li":["Presión fuera de meta con **tres fármacos a dosis óptimas, uno de ellos diurético**.","Primero descartar seudorresistencia: **falta de apego** (la causa más frecuente), mala técnica, bata blanca (confirmar con monitoreo de 24 horas), sal y antiinflamatorios.","Cuarto fármaco de elección: **espironolactona**.","Buscar causa secundaria y referir a cardiología o medicina interna."]},{"h":"Crisis hipertensiva","li":["Presión sistólica de **180 o más** y/o diastólica de **120 o más**.","**Urgencia hipertensiva**: sin daño agudo de órgano blanco. Se maneja con fármacos **orales**, bajando la presión de forma gradual en **24 a 48 horas**; revisar el apego y citar pronto.","**Emergencia hipertensiva**: con daño agudo (encefalopatía, evento vascular cerebral, síndrome coronario agudo, edema pulmonar, disección aórtica, lesión renal aguda o eclampsia). **Referencia inmediata** para tratamiento intravenoso.","No usar nifedipino sublingual: la caída brusca puede causar isquemia cerebral o coronaria."]},{"h":"Seguimiento y referencia","li":["Tras iniciar o ajustar: revalorar en **2 a 4 semanas**; la meta debe alcanzarse en unos **3 meses**.","Ya controlado: cada 3 a 6 meses.","Referir: emergencia hipertensiva, sospecha de hipertensión secundaria, hipertensión resistente, embarazo con hipertensión o daño renal que progresa."]}],"perlas":["Diagnóstico: **dos visitas** o confirmación fuera del consultorio; bata blanca se descarta con monitoreo de 24 horas.","Inicio con **doble terapia** casi siempre; monoterapia solo en grado 1 de bajo riesgo o anciano frágil.","Cuarto fármaco en la resistente: **espironolactona**.","Embarazo: **alfametildopa**; nunca inhibidores de la enzima convertidora ni antagonistas del receptor de angiotensina.","Hipopotasemia más hipertensión: piensa en **hiperaldosteronismo primario**.","Urgencia sin daño de órgano: **orales y bajar gradual**; emergencia con daño: **intravenoso y referencia**."],"mexico":["El Manual CTO sigue las guías europeas. En México rigen la Guía de Práctica Clínica de hipertensión en el primer nivel de atención del Centro Nacional de Excelencia Tecnológica en Salud (2021) y el Protocolo de Atención Integral de hipertensión del Instituto Mexicano del Seguro Social (2022).","El protocolo mexicano fija la meta general en **menor de 130/80 sin bajar de 110/70**, y **menor de 140/90 en el adulto mayor**.","En el Instituto Mexicano del Seguro Social la doble terapia inicial es inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más indapamida o hidroclorotiazida; el calcioantagonista se agrega como segundo paso o se prefiere desde el inicio si hay riesgo cardiometabólico o diabetes.","La guía de Estados Unidos define hipertensión desde 130/80; en el ENARM se usa el corte de 140/90."],"preguntas":[{"c":"Hombre de 46 años con presión de 152/96 mmHg en una sola consulta. Asintomático, sin otros factores de riesgo.","p":"¿Cuál es la conducta correcta?","o":["Diagnosticar hipertensión e iniciar doble terapia","Confirmar con otra visita o con mediciones fuera del consultorio","Iniciar betabloqueador","Solicitar ecocardiograma de inmediato"],"r":1,"e":"El diagnóstico exige elevación confirmada en al menos dos visitas o fuera del consultorio con medición en casa o monitoreo de 24 horas, salvo crisis o daño a órgano blanco.","f":"Manual CTO, Cardiología, capítulo 14, medida de la presión arterial."},{"c":"Paciente con presión de 166/104 mmHg confirmada en dos visitas.","p":"¿En qué grado se clasifica?","o":["Grado 1","Grado 2","Grado 3","Normal alta"],"r":1,"e":"Grado 2: sistólica de 160 a 179 y/o diastólica de 100 a 109. Si la sistólica y la diastólica caen en grados distintos, se clasifica por el más alto.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.1."},{"c":"Mujer de 74 años con presiones de 158/78 mmHg repetidas.","p":"¿Qué tipo de hipertensión presenta?","o":["Hipertensión diastólica","Hipertensión sistólica aislada","Presión normal para la edad","Seudohipertensión confirmada"],"r":1,"e":"Sistólica de 140 o más con diastólica menor de 90 es hipertensión sistólica aislada, típica del adulto mayor por rigidez arterial; aumenta el riesgo de eventos y se trata.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Mujer de 40 años con presiones de 150/95 en consultorio, pero su registro en casa promedia 122/76 y el monitoreo de 24 horas es normal con descenso nocturno.","p":"¿Cuál es el diagnóstico?","o":["Hipertensión enmascarada","Hipertensión de bata blanca","Hipertensión grado 1","Hipertensión resistente"],"r":1,"e":"Cifras altas solo en consultorio con mediciones normales fuera son hipertensión de bata blanca. La enmascarada es lo contrario.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.1."},{"c":"Hombre de 52 años con obesidad, ronquidos y somnolencia diurna. El monitoreo de 24 horas muestra que su presión no baja durante la noche.","p":"¿Qué causa debes descartar?","o":["Feocromocitoma","Apnea obstructiva del sueño","Coartación aórtica","Hipotiroidismo"],"r":1,"e":"El patrón non-dipper obliga a descartar apnea obstructiva del sueño, causa frecuente de hipertensión secundaria y resistente; se confirma con polisomnografía y mejora con presión positiva continua.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Al medir la presión de un paciente, el médico usa un brazalete estándar en un brazo muy grueso.","p":"¿Qué error de medición se produce?","o":["Cifras falsamente bajas","Cifras falsamente altas","No cambia el resultado","Solo cambia la diastólica"],"r":1,"e":"Un brazalete pequeño para el brazo sobrestima la presión; uno grande la subestima. Por eso se usa el brazalete adecuado al perímetro del brazo.","f":"Harrison, 21.ª edición, capítulo 277."},{"c":"Mujer de 28 años con hipertensión de reciente inicio, debilidad muscular y potasio de 2.9 mEq/L sin uso de diuréticos.","p":"¿Cuál es la sospecha principal?","o":["Hipertensión esencial","Hiperaldosteronismo primario","Síndrome de Cushing","Feocromocitoma"],"r":1,"e":"Hipertensión con hipopotasemia espontánea y alcalosis metabólica orienta a hiperaldosteronismo primario, la causa endocrina más frecuente de hipertensión secundaria. Se estudia con el cociente aldosterona/renina.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Hipertenso de 68 años con aterosclerosis. Dos semanas después de iniciar enalapril su creatinina subió de 1.0 a 1.6 mg/dL.","p":"¿Qué debes sospechar?","o":["Nefropatía por enalapril","Estenosis de arteria renal","Deshidratación leve sin importancia","Efecto esperado sin consecuencias"],"r":1,"e":"Un aumento de creatinina mayor de 30% al iniciar un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina sugiere estenosis de arteria renal, sobre todo en ancianos con aterosclerosis.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Paciente con hipertensión de difícil control que toma diclofenaco diario por dolor de rodilla.","p":"¿Qué recomiendas primero?","o":["Agregar un cuarto antihipertensivo","Suspender o sustituir el antiinflamatorio no esteroideo","Aumentar la dosis del diurético","Referir a cardiología"],"r":1,"e":"Los antiinflamatorios no esteroideos retienen sodio, suben la presión y reducen el efecto de los antihipertensivos. Es una causa de seudorresistencia que se corrige antes de agregar fármacos.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 50 años con hipertensión grado 1, sin diabetes, sin daño a órgano blanco y riesgo cardiovascular bajo.","p":"¿Cuál es la conducta inicial?","o":["Doble terapia inmediata","Medidas de estilo de vida por 3 a 6 meses y revalorar","No hacer nada","Betabloqueador como primera línea"],"r":1,"e":"En grado 1 de bajo riesgo se intenta primero el manejo no farmacológico; si no se controla en 3 a 6 meses, se inicia fármaco.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.4."},{"c":"Paciente de 55 años con presión de 168/102 mmHg confirmada, sin otras enfermedades.","p":"¿Cuál es el tratamiento inicial recomendado?","o":["Monoterapia con hidroclorotiazida","Doble terapia, de preferencia en una sola tableta","Solo cambios de estilo de vida por 6 meses","Espironolactona"],"r":1,"e":"En grados 2 y 3 se inicia de entrada doble terapia (inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más calcioantagonista o tiazida) junto con el estilo de vida.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.4."},{"c":"Paciente hipertenso con losartán, amlodipino e hidroclorotiazida a dosis óptimas, con buen apego confirmado y monitoreo de 24 horas en 148/92.","p":"¿Cuál es el siguiente fármaco de elección?","o":["Enalapril","Espironolactona","Atenolol","Clonidina"],"r":1,"e":"Es hipertensión resistente verdadera. El cuarto fármaco de elección es la espironolactona; revisar antes potasio y función renal, y buscar causa secundaria.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente hipertenso con enalapril y presión aún elevada. Se plantea agregar losartán.","p":"¿Es correcta esta combinación?","o":["Sí, potencia el bloqueo del sistema renina-angiotensina","No, combinarlos aumenta hiperpotasemia y lesión renal sin beneficio","Sí, pero solo en diabéticos","Sí, si la creatinina es normal"],"r":1,"e":"El doble bloqueo con inhibidor de la enzima convertidora y antagonista del receptor de angiotensina II no reduce eventos y aumenta hiperpotasemia y daño renal. Se agrega calcioantagonista o tiazida.","f":"Guía de hipertensión de la Sociedad Europea de Cardiología; Harrison, 21.ª edición, capítulo 277."},{"c":"Mujer de 45 años, hipertensa, con enalapril, que refiere tos seca persistente desde que lo inició.","p":"¿Qué haces?","o":["Agregar un antitusivo","Cambiar a un antagonista del receptor de angiotensina II","Suspender todo tratamiento","Cambiar a betabloqueador"],"r":1,"e":"La tos seca por acumulación de bradicinina es efecto de clase de los inhibidores de la enzima convertidora. Los antagonistas del receptor de angiotensina II no la producen.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con hipertensión y asma bronquial.","p":"¿Qué grupo de antihipertensivos está contraindicado?","o":["Calcioantagonistas","Betabloqueadores","Tiazidas","Antagonistas del receptor de angiotensina II"],"r":1,"e":"Los betabloqueadores pueden causar broncoespasmo y están contraindicados en asma.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Hombre de 58 años hipertenso con gota de repetición.","p":"¿Qué fármaco conviene evitar?","o":["Losartán","Hidroclorotiazida","Amlodipino","Enalapril"],"r":1,"e":"Las tiazidas elevan el ácido úrico y desencadenan crisis de gota. El losartán, en cambio, tiene un leve efecto uricosúrico.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Mujer de 32 años con 14 semanas de embarazo e hipertensión crónica. Tomaba losartán.","p":"¿Qué cambio realizas?","o":["Mantener losartán","Cambiar a alfametildopa","Cambiar a enalapril","Suspender todo antihipertensivo"],"r":1,"e":"Los inhibidores de la enzima convertidora y los antagonistas del receptor de angiotensina son teratógenos y están contraindicados. Opciones en embarazo: alfametildopa, labetalol o nifedipino.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 70 años con hipertensión y crecimiento prostático con síntomas urinarios. Presión aún elevada con dos fármacos.","p":"¿Qué fármaco agregado aprovecha ambas condiciones?","o":["Betabloqueador","Alfabloqueador como la doxazosina","Diurético de asa","Clonidina"],"r":1,"e":"Los alfabloqueadores mejoran los síntomas de la hiperplasia prostática y bajan la presión. Se usan como fármaco agregado y causan hipotensión ortostática.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con diabetes tipo 2, hipertensión y albuminuria de 120 mg/g.","p":"¿Qué grupo debe formar parte de su tratamiento?","o":["Betabloqueador","Inhibidor de la enzima convertidora o antagonista del receptor de angiotensina II","Calcioantagonista no dihidropiridínico solo","Alfametildopa"],"r":1,"e":"En diabetes con albuminuria, los bloqueadores del sistema renina-angiotensina reducen la proteinuria y retrasan la progresión renal.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente que inicia amlodipino 10 mg y al mes refiere edema en ambos tobillos, sin disnea.","p":"¿Cuál es la causa más probable?","o":["Insuficiencia cardiaca","Efecto adverso de las dihidropiridinas por vasodilatación arteriolar","Trombosis venosa bilateral","Síndrome nefrótico"],"r":1,"e":"El edema de tobillos es dosis dependiente con las dihidropiridinas. Se puede bajar la dosis o combinarlo con un inhibidor de la enzima convertidora o un antagonista del receptor de angiotensina, que lo reduce.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente de 60 años, hipertensa, con presión de 186/112 mmHg. Asintomática, sin dolor torácico, sin déficit neurológico; electrocardiograma y examen de orina sin cambios agudos. Dejó sus fármacos hace una semana.","p":"¿Cuál es la conducta adecuada?","o":["Nifedipino sublingual para bajarla rápido","Reiniciar o ajustar fármacos orales y bajar la presión de forma gradual en 24 a 48 horas","Nitroprusiato intravenoso en el consultorio","Referir a terapia intensiva"],"r":1,"e":"Es una urgencia hipertensiva: no hay daño agudo de órgano blanco. Se maneja con fármacos orales, descenso gradual y revaloración cercana. El nifedipino sublingual está proscrito.","f":"Manual CTO, Cardiología, capítulo 14, crisis hipertensivas."},{"c":"Hombre de 58 años con presión de 210/128 mmHg, cefalea intensa, confusión y vómito.","p":"¿Cómo se clasifica y qué haces?","o":["Urgencia hipertensiva; captopril oral y alta","Emergencia hipertensiva; referencia inmediata para tratamiento intravenoso","Hipertensión grado 3 estable; doble terapia oral","Crisis de ansiedad; benzodiacepina"],"r":1,"e":"Hay daño agudo de órgano blanco (encefalopatía hipertensiva), por lo que es emergencia. Requiere fármacos intravenosos con monitoreo y reducción controlada de la presión.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente que pregunta cuánta sal puede comer al día.","p":"¿Cuál es la recomendación?","o":["Menos de 10 g al día","Menos de 5 g al día","No hay límite si toma fármacos","Eliminar por completo el sodio"],"r":1,"e":"Se recomienda restringir la sal a menos de 3 a 5 g diarios, equivalentes a una cucharadita.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.4."},{"c":"Paciente hipertenso con obesidad que pierde 10 kg.","p":"¿Cuánto se espera que baje su presión sistólica?","o":["2 mmHg","Unos 10 mmHg","30 mmHg","No cambia"],"r":1,"e":"Por cada 5 kg perdidos la presión sistólica baja unos 5 mmHg y la diastólica unos 3 mmHg; con 10 kg, alrededor de 10 mmHg de sistólica.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hipertenso de 50 años, sin comorbilidades, con buena tolerancia al tratamiento.","p":"¿Cuál es la meta de presión recomendada?","o":["Menor de 150/90 mmHg","Menor de 130/80 mmHg","Menor de 110/60 mmHg","Menor de 160/100 mmHg"],"r":1,"e":"Si se tolera, la meta en menores de 65 años es menor de 130/80 mmHg; el protocolo mexicano agrega no bajar de 110/70.","f":"Manual CTO, Cardiología, capítulo 14; Protocolo de Atención Integral de hipertensión, Instituto Mexicano del Seguro Social."},{"c":"Mujer de 84 años, frágil, con caídas por mareo al levantarse. Presión sentada de 128/70 con tres antihipertensivos.","p":"¿Qué haces?","o":["Agregar un cuarto fármaco para llegar a 120/70","Reducir el tratamiento; en adultos mayores frágiles se aceptan metas más laxas","Mantener todo igual","Iniciar fludrocortisona"],"r":1,"e":"En el anciano frágil, cifras bajas favorecen la hipotensión ortostática y las caídas sin mejorar la supervivencia; se aceptan metas de sistólica de 140 a 150 mmHg.","f":"Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 22 años con hipertensión grado 2, pulsos femorales débiles y presión menor en las piernas que en los brazos.","p":"¿Cuál es el diagnóstico más probable?","o":["Hipertensión esencial","Coartación aórtica","Feocromocitoma","Estenosis de arteria renal por aterosclerosis"],"r":1,"e":"Hipertensión en brazos con presión baja y pulsos débiles en piernas sugiere coartación aórtica. Toda hipertensión antes de los 30 años obliga a buscar causa secundaria.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.2."},{"c":"Electrocardiograma de un hipertenso de larga evolución con ondas R altas en V5, V6, DI y aVL, y descenso del segmento ST con ondas T negativas asimétricas en esas derivaciones.","p":"¿Qué muestra?","o":["Isquemia subepicárdica","Hipertrofia ventricular izquierda con sobrecarga","Bloqueo de rama derecha","Pericarditis"],"r":1,"e":"Los voltajes altos en derivaciones laterales con alteraciones del ST-T asimétricas indican hipertrofia ventricular izquierda, el daño cardiaco típico de la hipertensión y un factor de riesgo independiente.","f":"Manual CTO, Cardiología, capítulo 14, figura 14.3."},{"c":"Paciente que inicia losartán por hipertensión y enfermedad renal crónica leve.","p":"¿Qué debes vigilar en 1 a 2 semanas?","o":["Glucosa y hemoglobina glucosilada","Creatinina y potasio","Transaminasas","Ácido úrico y calcio"],"r":1,"e":"Los bloqueadores del sistema renina-angiotensina pueden elevar el potasio y la creatinina; se miden al inicio y tras cada aumento de dosis.","f":"Ficha de losartán de GCHE2 (etiqueta oficial); Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente con hipertensión, al que se le inicia doble terapia.","p":"¿Cuándo debes revalorarlo?","o":["En 6 meses","En 2 a 4 semanas","Solo si presenta síntomas","En un año"],"r":1,"e":"Tras iniciar o ajustar el tratamiento se revalora en 2 a 4 semanas, con meta de control en unos 3 meses; el protocolo mexicano escala a triple terapia si no hay meta en 2 semanas.","f":"Protocolo de Atención Integral de hipertensión, Instituto Mexicano del Seguro Social, 2022."}],"audio":[["¿Desde qué cifra hay hipertensión en consultorio?","Desde 140 de sistólica o 90 de diastólica, confirmada en dos visitas o con mediciones fuera del consultorio."],["¿Cuáles son los grados?","Grado 1, de 140 a 159 sobre 90 a 99; grado 2, de 160 a 179 sobre 100 a 109; grado 3, de 180 sobre 110 o más."],["¿Cuál es el corte fuera del consultorio?","135 sobre 85 en casa o de día; 120 sobre 70 de noche en el monitoreo de 24 horas."],["¿Qué es la hipertensión de bata blanca?","Presión alta solo en consultorio y normal fuera. La enmascarada es al revés y se trata."],["¿Con qué se inicia el tratamiento?","Estilo de vida para todos y, en la mayoría, doble terapia: inhibidor de la enzima convertidora o antagonista del receptor de angiotensina más calcioantagonista o tiazida."],["¿Cuándo se permite monoterapia?","En grado 1 de bajo riesgo y en adultos mayores frágiles."],["¿Cuál es la meta?","Menor de 130 sobre 80 si se tolera; en ancianos frágiles, sistólica de 140 a 150."],["¿Qué es hipertensión resistente y qué se agrega?","Falta de control con tres fármacos a dosis óptimas, uno diurético. Se confirma apego y monitoreo de 24 horas, y se agrega espironolactona."],["¿Qué antihipertensivo se usa en el embarazo?","Alfametildopa, labetalol o nifedipino. Nunca inhibidores de la enzima convertidora ni antagonistas del receptor de angiotensina."],["¿Qué sugiere hipertensión con potasio bajo?","Hiperaldosteronismo primario."],["¿Cómo distingo urgencia de emergencia?","Ambas con 180 sobre 120 o más. La emergencia tiene daño agudo de órgano y requiere tratamiento intravenoso; la urgencia se baja con orales en 24 a 48 horas."],["¿Cuánta sal se permite?","Menos de 5 gramos al día, una cucharadita."]],"profundizar":{"harrison":[[277,"Hipertensión"]],"guias":[["Promoción, prevención, diagnóstico y tratamiento de la hipertensión arterial en el primer nivel de atención, GPC-IMSS-076-21, 2021 (sin enlace oficial por ahora; abajo la versión 2014)",""],["Diagnóstico y tratamiento de las crisis hipertensivas en adultos en los tres niveles de atención, GPC-SS-155-20, 2020 (sin enlace oficial por ahora)",""],["Diagnóstico y tratamiento de la hipertensión arterial en el primer nivel de atención, IMSS-076-08, actualización 2014","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/076GRR.pdf"],["Protocolo de Atención Integral: hipertensión arterial sistémica, Instituto Mexicano del Seguro Social, 2022","https://revistamedica.imss.gob.mx/index.php/revista_medica/article/download/4424/4319"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Cardiología, capítulo 14, páginas 140 a 147 del archivo.","Protocolo de Atención Integral: hipertensión arterial sistémica, Instituto Mexicano del Seguro Social, Revista Médica del IMSS 2022;60 Supl 1:S34-46.","Guía de Práctica Clínica de hipertensión arterial en el primer nivel de atención, Centro Nacional de Excelencia Tecnológica en Salud, 2021.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 277.","Fichas verificadas de losartán, enalapril y amlodipino en GCHE2 (etiquetas oficiales)."]},"cardiologia-4":{"titulo":"Insuficiencia cardiaca: crónica, aguda y en niños","enfoque":"Enfoque completo: clasificación, diagnóstico con péptidos natriuréticos y ecocardiograma, los cuatro fármacos que salvan vidas con sus dosis, dispositivos, descompensación, edema agudo de pulmón, choque cardiogénico, insuficiencia cardiaca en niños y las cardiopatías congénitas que más se preguntan.","resumen":[{"h":"Lo esencial en 30 segundos","li":["Síndrome con **síntomas** (disnea, fatiga) y **signos** (ingurgitación yugular, crepitantes, edema) por una alteración estructural o funcional del corazón.","Se clasifica por la **fracción de eyección del ventrículo izquierdo**: **reducida 40% o menos**, ligeramente reducida 41 a 49% y **preservada 50% o más**.","Diagnóstico: síntomas y signos, **péptidos natriuréticos** (un valor normal casi la descarta) y **ecocardiograma** en todos.","Fracción reducida: **cuatro pilares** que bajan la mortalidad: inhibidor de la enzima convertidora o sacubitrilo con valsartán, **betabloqueador**, **antagonista de mineralocorticoides** e **inhibidor del cotransportador sodio-glucosa tipo 2**.","Los **diuréticos** quitan la congestión y los síntomas, pero **no** alargan la vida.","Fracción preservada: **dapagliflozina o empagliflozina**, diurético si hay congestión y control de presión, frecuencia y fibrilación auricular.","Edema agudo de pulmón: **sentar, oxígeno si la saturación es menor de 90%, furosemida intravenosa y nitroglicerina** si la presión lo permite.","En el lactante: **taquipnea, sudor al comer, poca ganancia de peso y hepatomegalia**; casi siempre por un **cortocircuito de izquierda a derecha**."]},{"h":"Cómo se produce","li":["Cae el gasto cardiaco o suben las presiones de llenado y el cuerpo compensa: **sistema renina-angiotensina-aldosterona**, **sistema simpático** y hormona antidiurética.","A corto plazo mantienen la presión; a largo plazo retienen sal y agua, aumentan la poscarga y causan **remodelado**: por eso los fármacos que **bloquean** estos sistemas mejoran la supervivencia.","Los **péptidos natriuréticos** se liberan por el estiramiento del ventrículo; son la contrarregulación y el marcador diagnóstico.","**Gasto alto**: anemia, hipertiroidismo, fístulas arteriovenosas, beriberi (deficiencia de tiamina), enfermedad de Paget, embarazo y sepsis."]},{"h":"Clasificaciones","li":["**Por fracción de eyección**: reducida (40% o menos; ventrículo dilatado, causas isquémica y miocardiopatía dilatada), ligeramente reducida (41 a 49%) y **preservada** (50% o más; ancianos, mujeres, obesos, hipertensión y fibrilación auricular; requiere péptidos elevados y alteración diastólica).","**Clase funcional de la Asociación del Corazón de Nueva York**: I sin limitación; II síntomas con actividad ordinaria; III con menos que la actividad ordinaria; **IV en reposo**.","**Estadios del Colegio Americano de Cardiología y la Asociación Americana del Corazón**: A riesgo sin daño estructural (hipertensión, diabetes); B daño estructural sin síntomas; C daño con síntomas; D avanzada y refractaria.","**Izquierda** (congestión pulmonar) frente a **derecha** (congestión sistémica); **aguda** frente a **crónica**."]},{"h":"Causas y desencadenantes","li":["Causas: **cardiopatía isquémica** (la más frecuente), **hipertensión**, valvulopatías, miocardiopatías (dilatada, alcohólica, por quimioterapia), **enfermedad de Chagas** (importante en México y Latinoamérica), miocarditis y arritmias.","Desencadenantes de descompensación: **mal apego** al tratamiento o a la dieta con sal (lo más frecuente), **infección**, **fibrilación auricular** u otra arritmia, isquemia, hipertensión descontrolada, **antiinflamatorios no esteroideos**, anemia, falla renal, tiroides, embolia pulmonar y embarazo."]},{"h":"Cómo se ve","li":["Izquierda: **disnea** de esfuerzo progresiva, **ortopnea**, **disnea paroxística nocturna**, tos nocturna, crepitantes, **tercer ruido** (galope), sibilancias (asma cardiaca) y derrame pleural (más frecuente derecho).","Derecha: **ingurgitación yugular**, **reflujo hepatoyugular**, hepatomegalia dolorosa, **edema con fóvea** en piernas, ascitis, nicturia y saciedad temprana.","Bajo gasto: fatiga, frialdad, oliguria, confusión; presión de pulso estrecha y pulso alternante en fases avanzadas.","Respiración de **Cheyne-Stokes** y caquexia cardiaca son de mal pronóstico. La principal causa de muerte, junto con la progresión, es la **muerte súbita arrítmica**.","**Criterios de Framingham**: 2 mayores, o 1 mayor y 2 menores. Mayores: disnea paroxística nocturna, ingurgitación yugular, estertores, cardiomegalia, edema agudo de pulmón, tercer ruido, reflujo hepatoyugular, presión venosa elevada, baja de más de 4.5 kg en 5 días con tratamiento. Menores: edema de tobillos, tos nocturna, disnea de esfuerzo, hepatomegalia, derrame pleural, taquicardia de más de 120."]},{"h":"Diagnóstico","li":["**Péptidos natriuréticos**: con valor normal la insuficiencia cardiaca es muy improbable (alto valor predictivo negativo). Paciente estable: péptido natriurético tipo B menor de 35 pg/mL o su fracción aminoterminal (NT-proBNP) menor de 125. **Cuadro agudo: menor de 100 o NT-proBNP menor de 300**.","Falsos altos: edad avanzada, insuficiencia renal, fibrilación auricular, embolia pulmonar, enfermedad pulmonar obstructiva y sexo femenino. Falsos bajos: **obesidad**. Con sacubitrilo, el péptido tipo B sube por el fármaco: usa NT-proBNP.","**Electrocardiograma**: casi nunca es normal en la insuficiencia cardiaca (bloqueos de rama, hipertrofia, ondas Q, fibrilación auricular).","**Radiografía de tórax**: cardiomegalia, redistribución vascular a vértices, **líneas B de Kerley**, derrame pleural; en el edema agudo de pulmón, infiltrado alveolar en **alas de mariposa**.","**Ecocardiograma en todos**: mide la fracción de eyección, busca valvulopatías y alteraciones de la contracción, estima presiones. La **resonancia cardiaca** es la referencia para medir la fracción y ver fibrosis.","Laboratorio: biometría, creatinina, sodio y potasio, glucosa, perfil de lípidos, función tiroidea, **ferritina y saturación de transferrina** (deficiencia de hierro: ferritina menor de 100, o 100 a 299 con saturación menor de 20%).","Mal pronóstico: **hiponatremia**, hipotensión, falla renal, anemia, péptidos muy elevados, clase funcional avanzada y hospitalizaciones repetidas."]},{"h":"Fracción reducida: los cuatro pilares","li":["**Inhibidor de la enzima convertidora de angiotensina** (enalapril 2.5 mg cada 12 horas hasta 10 a 20 mg cada 12 horas) o, si no lo tolera por tos o angioedema, **antagonista del receptor de angiotensina** (losartán 50 hasta 150 mg al día; valsartán 40 hasta 160 mg cada 12 horas; candesartán 4 a 8 hasta 32 mg).","**Sacubitrilo con valsartán** (de primera línea o en lugar del inhibidor si sigue sintomático): 49/51 mg cada 12 horas hasta 97/103 mg cada 12 horas. **Deja 36 horas sin inhibidor de la enzima convertidora** antes de iniciarlo (angioedema).","**Betabloqueador**: carvedilol 3.125 mg cada 12 horas hasta 25 mg cada 12 horas (50 si pesa más de 85 kg), bisoprolol 1.25 hasta 10 mg al día, succinato de metoprolol 12.5 a 25 hasta 200 mg al día, o nebivolol. Se inicia con el paciente **estable y sin congestión** y se sube cada 2 semanas.","**Antagonista de mineralocorticoides**: espironolactona 12.5 a 25 hasta 50 mg al día o eplerenona 25 hasta 50 mg. No darlo con potasio mayor de 5.0 o creatinina mayor de 2.5 mg/dL. La espironolactona da **ginecomastia** (la eplerenona no).","**Inhibidor del cotransportador sodio-glucosa tipo 2**: **dapagliflozina 10 mg o empagliflozina 10 mg al día**, con o sin diabetes, sin titular.","Inicia los cuatro **lo antes posible**, a dosis bajas, y súbelos hasta la dosis objetivo o la máxima tolerada. Revisa **potasio y creatinina 1 a 2 semanas** después de iniciar o subir."]},{"h":"Fracción reducida: lo que se agrega","li":["**Diurético de asa** (furosemida 20 a 40 mg, ajustando) para la congestión, a la dosis mínima que mantenga al paciente sin edema.","**Hidralazina con dinitrato de isosorbida** (37.5/20 mg cada 8 horas hasta 75/40 mg): en pacientes de raza negra en clase III a IV o si no tolera bloquear el sistema renina-angiotensina.","**Ivabradina** (5 hasta 7.5 mg cada 12 horas): ritmo sinusal con frecuencia de **70 o más** pese a la dosis máxima tolerada de betabloqueador y fracción de 35% o menos.","**Digoxina**: alivia síntomas y reduce hospitalizaciones, sobre todo con fibrilación auricular; **no** alarga la vida. Rango estrecho (0.5 a 1 ng/mL).","**Hierro intravenoso** si hay deficiencia de hierro, aun sin anemia.","**Vericiguat**: tras una hospitalización reciente, como último escalón.","**Desfibrilador automático implantable**: fracción de **35% o menos** en clase II a III tras 3 meses de tratamiento óptimo, con expectativa de vida mayor de 1 año; no en los primeros 40 días después de un infarto. Disminuye la muerte súbita.","**Terapia de resincronización**: fracción de 35% o menos, síntomas y **QRS ancho**, sobre todo con **bloqueo de rama izquierda y QRS de 150 ms o más**."]},{"h":"Fármacos que debes evitar","li":["**Verapamilo y diltiazem** en fracción reducida (inotrópicos negativos). El amlodipino sí puede usarse para la presión.","**Antiinflamatorios no esteroideos**, **pioglitazona**, antiarrítmicos del grupo Ic (flecainida, propafenona), dronedarona, antidepresivos tricíclicos y litio.","**Nunca** combinar inhibidor de la enzima convertidora con antagonista del receptor de angiotensina y antagonista de mineralocorticoides (los tres): hiperpotasemia grave."]},{"h":"Fracción ligeramente reducida y preservada","li":["**Dapagliflozina o empagliflozina**: único grupo con beneficio demostrado en fracción preservada (reducen hospitalizaciones).","Diurético a dosis bajas si hay congestión; cuidado con la precarga (son ventrículos rígidos).","Controla la **presión**, la **frecuencia cardiaca** (aquí sí se pueden usar verapamilo y diltiazem), la isquemia y la **fibrilación auricular**; trata obesidad, diabetes y apnea del sueño.","En la ligeramente reducida pueden considerarse también los fármacos de la reducida."]},{"h":"Medidas generales y seguimiento","li":["**Pesarse diario**: si sube más de 2 kg en 3 días, avisar o ajustar el diurético.","Sal moderada (evitar más de 5 g al día). Restringir líquidos a 1.5 a 2 litros solo en casos graves o con hiponatremia.","Ejercicio aeróbico regular y rehabilitación cardiaca; **vacunas** contra influenza, neumococo y COVID-19; no fumar; alcohol limitado (nada si la causa es alcohólica).","Tratar apnea del sueño, depresión, anemia y deficiencia de hierro.","Con los fármacos: acepta una subida de creatinina de hasta 50% y potasio de hasta 5.5 mEq/L; con potasio mayor de 6.0 o creatinina que sube más, reduce o suspende y revisa.","Intoxicación por **digoxina**: náusea, vómito, **visión amarilla**, confusión; extrasístoles ventriculares, bloqueos, taquicardia auricular con bloqueo y **taquicardia ventricular bidireccional**. Favorecen: **falla renal**, **hipopotasemia**, edad avanzada, amiodarona, verapamilo y macrólidos. Tratamiento: suspender, corregir potasio y anticuerpos antidigoxina si es grave."]},{"h":"Insuficiencia cardiaca aguda","li":["Busca el desencadenante: síndrome coronario agudo, **hipertensión**, arritmia, causa mecánica (rotura valvular o septal), embolia pulmonar, **infección** y taponamiento.","Perfiles clínicos (Stevenson): **caliente y húmedo** (congestión con buena perfusión, el más frecuente): diurético y vasodilatador. **Frío y húmedo**: inotrópico más diurético. **Frío y seco**: valorar líquidos con cuidado. **Caliente y seco**: compensado.","**Edema agudo de pulmón**: **sentar** con piernas colgando; **oxígeno** si saturación menor de 90% o presión de oxígeno menor de 60 mmHg; **ventilación no invasiva** si hay dificultad respiratoria; **furosemida intravenosa** (20 a 40 mg si no la tomaba, o 1 a 2.5 veces su dosis oral diaria); **nitroglicerina intravenosa** si la presión sistólica es mayor de 90 a 110 mmHg; morfina **no de rutina** (depresión respiratoria).","No suspendas el betabloqueador en una descompensación leve; sí en choque o bajo gasto.","**Infarto del ventrículo derecho**: hipotensión, ingurgitación yugular y pulmones limpios; **líquidos intravenosos** y **evitar nitratos y diuréticos**."]},{"h":"Choque cardiogénico","li":["Presión sistólica **menor de 90 mmHg** con datos de **hipoperfusión** (oliguria, frialdad, lactato alto, confusión) pese a volumen adecuado.","Causa más frecuente: **infarto agudo de miocardio** extenso; requiere **revascularización urgente**.","**Norepinefrina** como vasopresor y **dobutamina** como inotrópico; ventilación según necesidad; unidad de cuidados intensivos.","Soporte mecánico: **balón de contrapulsación intraaórtico** (se infla en diástole y se desinfla en sístole; contraindicado en insuficiencia aórtica grave y disección aórtica), oxigenación por membrana extracorpórea y asistencias ventriculares como puente al trasplante."]},{"h":"Insuficiencia cardiaca en niños","li":["**Recién nacido en los primeros días a 2 semanas**: lesiones obstructivas izquierdas **dependientes del conducto** (síndrome de corazón izquierdo hipoplásico, coartación crítica, estenosis aórtica crítica): choque al cerrarse el conducto, pulsos débiles.","**Lactante de 4 a 8 semanas**: **cortocircuitos de izquierda a derecha** (comunicación interventricular grande, conducto arterioso, canal auriculoventricular) cuando bajan las resistencias pulmonares.","Niño mayor: **miocarditis viral**, miocardiopatía dilatada, fiebre reumática, arritmias, hipertensión, anemia grave.","Cómo se ve en el lactante: **taquipnea**, **sudoración durante la toma**, toma poco y se cansa, **falla de medro**, taquicardia, **hepatomegalia** (el signo de congestión más fiable a esta edad), cardiomegalia. El edema periférico y la ingurgitación yugular son raros.","Tratamiento: **furosemida** (alrededor de 1 mg por kilo por dosis), inhibidor de la enzima convertidora, espironolactona, digoxina en casos seleccionados, **fórmula hipercalórica** y corrección de la causa (cateterismo o cirugía).","Cardiopatía dependiente del conducto: **prostaglandina E1** (alprostadil) en infusión para mantenerlo abierto; vigila **apnea**, su efecto adverso más importante."]},{"h":"Cardiopatías congénitas: lo que se pregunta","li":["Afectan a alrededor de **1%** de los recién nacidos. La más frecuente en el mundo es la **comunicación interventricular**; en México la guía señala la **persistencia del conducto arterioso**. Cianótica más frecuente al nacer: **transposición de grandes arterias**; después del año: **tetralogía de Fallot**.","**Comunicación interventricular**: soplo **holosistólico rudo** en borde esternal izquierdo bajo; las pequeñas suelen **cerrar solas**; las grandes dan insuficiencia cardiaca a las semanas.","**Comunicación interauricular** tipo ostium secundum: **desdoblamiento amplio y fijo del segundo ruido**, bloqueo de rama derecha; mujeres jóvenes con disnea; cierre percutáneo.","**Persistencia del conducto arterioso**: **soplo continuo en maquinaria** infraclavicular izquierdo, **pulsos amplios**; prematuros y **rubéola congénita**. En el prematuro se cierra con **ibuprofeno o indometacina** (o paracetamol); si no, cierre percutáneo o quirúrgico.","**Coartación de aorta**: **síndrome de Turner**; hipertensión en brazos con **pulsos femorales débiles y retrasados**; en mayores, muescas costales y signo del 3 en la radiografía.","**Tetralogía de Fallot**: comunicación interventricular, cabalgamiento aórtico, **obstrucción de la salida del ventrículo derecho** e hipertrofia del ventrículo derecho; **corazón en bota**. **Crisis hipoxémicas**: posición **rodillas al pecho**, oxígeno, morfina, líquidos, **propranolol** y fenilefrina.","**Transposición de grandes arterias**: cianosis intensa al nacer que no mejora con oxígeno; **huevo en cuerda**; prostaglandina E1, **atrioseptostomía** y **cirugía de switch arterial**.","**Síndrome de Eisenmenger**: el cortocircuito se invierte por hipertensión pulmonar y aparece cianosis; **contraindica el cierre** del defecto.","Síndromes: **Down → canal auriculoventricular**; **Turner → coartación**; **DiGeorge → tronco arterioso y Fallot**; Noonan → estenosis pulmonar; **Williams → estenosis aórtica supravalvular**; rubéola → conducto arterioso."]},{"h":"Tamiz cardiaco neonatal con oximetría","li":["Después de las 24 horas de vida, saturación en **mano derecha** y en un **pie**.","**Pasa**: 95% o más en cualquiera y diferencia de 3 puntos o menos.","**Falla**: menos de 90% en cualquiera: ecocardiograma y valoración urgente.","Entre 90 y 94% o diferencia mayor de 3: repetir en una hora (hasta 2 veces)."]},{"h":"Cuándo referir","li":["**Urgencias**: edema agudo de pulmón, choque, síncope o arritmia, insuficiencia cardiaca de reciente inicio con datos de gravedad, recién nacido con cianosis o pulsos débiles.","**Cardiología**: todo diagnóstico nuevo para ecocardiograma y causa; fracción de 35% o menos para valorar dispositivos; falta de respuesta al tratamiento; candidatos a trasplante.","**Cardiología pediátrica**: todo soplo patológico, cianosis, falla de medro con taquipnea o sospecha de cardiopatía congénita."]}],"perlas":["Péptido natriurético **normal**: la insuficiencia cardiaca es muy improbable.","Bajan la mortalidad en fracción reducida: **inhibidor de la enzima convertidora o sacubitrilo con valsartán, betabloqueador, antagonista de mineralocorticoides e inhibidor del cotransportador sodio-glucosa tipo 2**.","Los diuréticos **no** alargan la vida.","Betabloqueador: iniciar **sin congestión** y a dosis baja.","Sacubitrilo con valsartán: **36 horas** sin inhibidor de la enzima convertidora antes.","Verapamilo y diltiazem: **contraindicados** en fracción reducida.","Infarto de ventrículo derecho: **líquidos**, sin nitratos.","Lactante con taquipnea, sudor al comer y hepatomegalia: **cortocircuito de izquierda a derecha**.","Soplo continuo en maquinaria: **persistencia del conducto arterioso**.","Desdoblamiento fijo del segundo ruido: **comunicación interauricular**."],"mexico":["La Guía de Práctica Clínica ISSSTE-722-15 (insuficiencia cardiaca crónica en el adulto, 2015) es anterior a sacubitrilo con valsartán y a los inhibidores del cotransportador sodio-glucosa tipo 2. Las **Recomendaciones mexicanas para el diagnóstico y tratamiento de la insuficiencia cardiaca (2024)**, publicadas en Archivos de Cardiología de México, ya usan los **cuatro pilares**, igual que el CTO y el Harrison.","En México y Latinoamérica la **enfermedad de Chagas** es causa importante de miocardiopatía dilatada: pregúntala en pacientes de zonas rurales.","La Guía de Práctica Clínica IMSS-380-10 define la persistencia del conducto arterioso como la permeabilidad **después de la sexta semana de vida** y la señala como la cardiopatía congénita más frecuente en México; el CTO, con datos internacionales, pone primero a la comunicación interventricular.","La Guía IMSS-054-08 orienta la detección de cardiopatías congénitas en niños mayores de 5 años, adolescentes y adultos: busca soplos, cianosis, intolerancia al ejercicio e hipertensión en brazos."],"preguntas":[{"c":"Hombre de 64 años con disnea de esfuerzo progresiva y edema de tobillos. Electrocardiograma con bloqueo de rama izquierda.","p":"¿Qué estudio confirma el diagnóstico y define el tratamiento?","o":["Prueba de esfuerzo","Ecocardiograma","Holter de 24 horas","Tomografía de tórax"],"r":1,"e":"El ecocardiograma se hace a todos: mide la fracción de eyección, que define el tipo de insuficiencia cardiaca y su tratamiento.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Mujer de 70 años en urgencias con disnea. NT-proBNP de 150 pg/mL.","p":"¿Cómo se interpreta?","o":["Confirma insuficiencia cardiaca","Hace muy improbable la insuficiencia cardiaca como causa","Indica choque cardiogénico","Debe repetirse en 6 meses"],"r":1,"e":"En el contexto agudo, NT-proBNP menor de 300 pg/mL tiene un alto valor predictivo negativo: busca otra causa de la disnea.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"¿Qué condición da péptidos natriuréticos falsamente bajos?","p":"Elige la opción correcta.","o":["Insuficiencia renal","Fibrilación auricular","Obesidad","Edad avanzada"],"r":2,"e":"La obesidad disminuye los péptidos natriuréticos; la falla renal, la fibrilación auricular y la edad los elevan.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca que se cansa al caminar una cuadra en plano y al vestirse, pero está bien en reposo.","p":"¿Qué clase funcional tiene?","o":["I","II","III","IV"],"r":2,"e":"Clase III: síntomas con actividad menor que la ordinaria; la IV tiene síntomas en reposo.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Hombre de 50 años, hipertenso y diabético, con hipertrofia ventricular izquierda en el ecocardiograma y sin síntomas.","p":"¿En qué estadio está?","o":["A","B","C","D"],"r":1,"e":"Estadio B: daño estructural sin síntomas. El A es solo riesgo, sin daño estructural.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca y fracción de eyección de 30%.","p":"¿Qué grupo de fármacos NO ha demostrado reducir la mortalidad?","o":["Betabloqueadores","Antagonistas de mineralocorticoides","Diuréticos de asa","Inhibidores del cotransportador sodio-glucosa tipo 2"],"r":2,"e":"Los diuréticos de asa alivian la congestión pero no mejoran la supervivencia.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con fracción reducida que inicia tratamiento.","p":"¿Cuáles son los cuatro pilares que bajan la mortalidad?","o":["Diurético, digoxina, nitrato e ivabradina","Inhibidor de la enzima convertidora o sacubitrilo con valsartán, betabloqueador, antagonista de mineralocorticoides e inhibidor del cotransportador sodio-glucosa tipo 2","Amiodarona, digoxina, furosemida y espironolactona","Verapamilo, enalapril, furosemida y aspirina"],"r":1,"e":"Los cuatro grupos tienen beneficio en mortalidad y deben iniciarse pronto y titularse.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca descompensado, con crepitantes y edema importante.","p":"¿Cuándo inicias el betabloqueador?","o":["De inmediato a dosis alta","Cuando esté estable y sin congestión, a dosis baja","Nunca","Solo si tiene fibrilación auricular"],"r":1,"e":"El betabloqueador se inicia en el paciente estable y euvolémico, a dosis baja, subiendo cada 2 semanas.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"¿Qué betabloqueadores tienen beneficio demostrado en insuficiencia cardiaca con fracción reducida?","p":"Elige la opción correcta.","o":["Atenolol y propranolol","Carvedilol, bisoprolol, succinato de metoprolol y nebivolol","Sotalol y labetalol","Esmolol y nadolol"],"r":1,"e":"Solo carvedilol, bisoprolol, succinato de metoprolol y nebivolol tienen evidencia en insuficiencia cardiaca.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente que toma enalapril y vas a cambiar a sacubitrilo con valsartán.","p":"¿Qué precaución tomas?","o":["Darlos juntos un mes","Suspender el enalapril 36 horas antes","Agregar losartán","Suspender el betabloqueador"],"r":1,"e":"La combinación con un inhibidor de la enzima convertidora causa angioedema: se separan al menos 36 horas.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con sacubitrilo con valsartán al que le pides péptido natriurético tipo B para seguimiento.","p":"¿Qué problema hay?","o":["Ninguno","El sacubitrilo eleva el péptido tipo B; usa NT-proBNP","El fármaco lo vuelve negativo","Solo sirve en niños"],"r":1,"e":"El sacubitrilo inhibe la neprilisina que degrada el péptido tipo B; el NT-proBNP no se afecta.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Hombre con insuficiencia cardiaca que toma espironolactona y refiere crecimiento doloroso de las mamas.","p":"¿Qué cambio haces?","o":["Suspender todo","Cambiar a eplerenona","Agregar tamoxifeno","Duplicar la dosis"],"r":1,"e":"La ginecomastia es efecto antiandrogénico de la espironolactona; la eplerenona es más selectiva y no la produce.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca con potasio de 5.8 mEq/L y creatinina de 2.8 mg/dL.","p":"¿Qué fármaco no inicias?","o":["Furosemida","Antagonista de mineralocorticoides","Hidralazina con nitrato","Digoxina a dosis baja"],"r":1,"e":"Los antagonistas de mineralocorticoides no se inician con potasio alto o creatinina mayor de 2.5 mg/dL por riesgo de hiperpotasemia.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con fracción de 32% sin diabetes.","p":"¿Puede recibir dapagliflozina?","o":["No, solo es para diabéticos","Sí, 10 mg al día, con o sin diabetes","Solo si la creatinina es normal y es diabético","Solo en fracción preservada"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 reducen muerte cardiovascular y hospitalizaciones con o sin diabetes.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con fracción reducida y fibrilación auricular rápida.","p":"¿Qué fármaco está contraindicado para controlar la frecuencia?","o":["Betabloqueador","Digoxina","Diltiazem","Amiodarona"],"r":2,"e":"Verapamilo y diltiazem son inotrópicos negativos y están contraindicados en fracción reducida.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca y gonartrosis que pide naproxeno diario.","p":"¿Qué le respondes?","o":["Está bien","Evitarlo: retiene sal y agua y descompensa","Solo con omeprazol","Mejor indometacina"],"r":1,"e":"Los antiinflamatorios no esteroideos retienen sodio, empeoran la función renal y precipitan descompensaciones.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con fracción de 30%, en ritmo sinusal a 82 latidos por minuto, con betabloqueador a dosis máxima tolerada y los otros pilares.","p":"¿Qué puedes agregar?","o":["Ivabradina","Verapamilo","Más betabloqueador","Nifedipino"],"r":0,"e":"La ivabradina reduce la frecuencia en ritmo sinusal con 70 o más latidos por minuto pese al betabloqueador.","f":"Harrison, capítulos 257 y 258"},{"c":"Paciente afrodescendiente en clase III con fracción reducida y síntomas pese al tratamiento óptimo.","p":"¿Qué combinación tiene beneficio adicional?","o":["Hidralazina con dinitrato de isosorbida","Nifedipino con nitrato","Amiodarona con digoxina","Diltiazem con furosemida"],"r":0,"e":"Hidralazina con dinitrato de isosorbida reduce la mortalidad en pacientes de raza negra y es alternativa si no se toleran los bloqueadores del sistema renina-angiotensina.","f":"Harrison, capítulos 257 y 258"},{"c":"Paciente con fracción de 30%, clase II, después de 3 meses de tratamiento óptimo, con expectativa de vida de años.","p":"¿Qué dispositivo está indicado?","o":["Marcapasos unicameral","Desfibrilador automático implantable","Balón de contrapulsación","Ninguno"],"r":1,"e":"Fracción de 35% o menos en clase II a III pese a tratamiento óptimo: desfibrilador para prevenir muerte súbita.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con fracción de 28%, clase III, ritmo sinusal y bloqueo de rama izquierda con QRS de 160 ms pese a tratamiento óptimo.","p":"¿Qué terapia mejora síntomas y supervivencia?","o":["Ablación","Terapia de resincronización cardiaca","Solo diurético","Digoxina a dosis alta"],"r":1,"e":"La resincronización está indicada con fracción de 35% o menos, síntomas y QRS ancho, sobre todo con bloqueo de rama izquierda y QRS de 150 o más.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con infarto hace 3 semanas y fracción de 30%.","p":"¿Colocas desfibrilador ya?","o":["Sí, de inmediato","No: se espera más de 40 días y se reevalúa con tratamiento óptimo","Nunca","Solo si tiene diabetes"],"r":1,"e":"El desfibrilador no se coloca en los primeros 40 días tras un infarto porque la fracción puede recuperarse.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Mujer de 78 años, hipertensa y obesa, con disnea y edema. Ecocardiograma: fracción de 60%, hipertrofia y llenado alterado; NT-proBNP elevado.","p":"¿Qué fármaco tiene beneficio demostrado?","o":["Sacubitrilo con valsartán a todos","Empagliflozina o dapagliflozina","Ivabradina","Digoxina"],"r":1,"e":"En fracción preservada, los inhibidores del cotransportador sodio-glucosa tipo 2 son el único grupo con beneficio demostrado (menos hospitalizaciones).","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"En insuficiencia cardiaca con fracción preservada y fibrilación auricular rápida.","p":"¿Puedes usar diltiazem?","o":["No, nunca","Sí: no está contraindicado en fracción preservada","Solo intravenoso","Solo con digoxina"],"r":1,"e":"A diferencia de la fracción reducida, en la preservada se pueden usar verapamilo y diltiazem para la frecuencia.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca que toma digoxina, inicia amiodarona y presenta náusea, visión amarilla y taquicardia ventricular bidireccional.","p":"¿Qué presenta?","o":["Hipertiroidismo","Intoxicación por digoxina","Infarto","Hipercalcemia"],"r":1,"e":"La amiodarona eleva la digoxina; la visión amarilla y la taquicardia bidireccional son típicas de la intoxicación.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"¿Qué alteración electrolítica favorece la intoxicación por digoxina?","p":"Elige la opción correcta.","o":["Hiperpotasemia","Hipopotasemia","Hipernatremia","Hipocalcemia"],"r":1,"e":"La hipopotasemia, la hipomagnesemia, la hipercalcemia y la falla renal favorecen la toxicidad digitálica.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca que sube 3 kg en 3 días y tiene más edema.","p":"¿Qué medida de autocuidado falló o qué haces?","o":["Nada, es normal","Ajustar el diurético y buscar el desencadenante","Suspender el betabloqueador siempre","Restringir líquidos a 500 mL"],"r":1,"e":"El peso diario detecta la congestión antes que los síntomas: aumento de más de 2 kg en 3 días obliga a ajustar el diurético y buscar la causa.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"¿Cuál es el desencadenante más frecuente de una descompensación?","p":"Elige la opción correcta.","o":["Embolia pulmonar","Mal apego al tratamiento o a la dieta","Taponamiento","Hipotiroidismo"],"r":1,"e":"La falta de apego al fármaco o la dieta con sal es la causa más frecuente; después, infección y arritmias.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con disnea súbita, ortopnea, estertores en ambos campos, presión de 170/100 y saturación de 86%.","p":"¿Cuál es el manejo inicial?","o":["Acostar y dar líquidos","Sentar, oxígeno, furosemida intravenosa y nitroglicerina","Betabloqueador intravenoso","Dobutamina"],"r":1,"e":"Edema agudo de pulmón hipertensivo: sentado, oxígeno, diurético de asa intravenoso y vasodilatador.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"En el edema agudo de pulmón, ¿cuándo usas nitroglicerina?","p":"Elige la opción correcta.","o":["Con presión sistólica menor de 80","Si la presión sistólica es mayor de 90 a 110 mmHg","Nunca","Solo con infarto del ventrículo derecho"],"r":1,"e":"Los vasodilatadores se dan cuando la presión lo permite; con hipotensión se evitan.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Radiografía de tórax con infiltrado alveolar bilateral perihiliar.","p":"¿Cómo se describe y qué sugiere?","o":["Patrón en vidrio deslustrado; neumonía viral","Alas de mariposa; edema agudo de pulmón","Corazón en bota; Fallot","Huevo en cuerda; transposición"],"r":1,"e":"El patrón en alas de mariposa es típico del edema pulmonar cardiogénico.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con infarto inferior, hipotensión, ingurgitación yugular y pulmones limpios.","p":"¿Qué haces?","o":["Nitroglicerina y furosemida","Líquidos intravenosos","Morfina a dosis alta","Diurético de asa en bolo"],"r":1,"e":"Infarto del ventrículo derecho: depende de la precarga; se dan líquidos y se evitan nitratos y diuréticos.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Paciente con insuficiencia cardiaca descompensada, extremidades frías, oliguria, presión de 85/50 y estertores.","p":"¿Qué perfil tiene y qué necesita?","o":["Caliente y seco; nada","Frío y húmedo; inotrópico y diurético","Caliente y húmedo; solo nitrato","Frío y seco; solo diurético"],"r":1,"e":"Hipoperfusión (frío) con congestión (húmedo): necesita inotrópico como dobutamina, además de manejar la congestión.","f":"Harrison, capítulo 305"},{"c":"Paciente con infarto extenso, presión de 78/40, confusión, oliguria y lactato elevado.","p":"¿Cuál es la medida que más cambia el pronóstico?","o":["Furosemida","Revascularización coronaria urgente","Digoxina","Betabloqueador"],"r":1,"e":"En el choque cardiogénico por infarto, la revascularización urgente es la medida clave, junto con vasopresores e inotrópicos.","f":"Harrison, capítulo 305"},{"c":"¿Cuándo está contraindicado el balón de contrapulsación intraaórtico?","p":"Elige la opción correcta.","o":["Choque cardiogénico","Insuficiencia aórtica grave o disección aórtica","Comunicación interventricular posinfarto","Angina refractaria"],"r":1,"e":"El balón se infla en diástole; con insuficiencia aórtica grave aumenta la regurgitación y en la disección empeora el daño.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"¿Qué enfermedad causa insuficiencia cardiaca de gasto alto?","p":"Elige la opción correcta.","o":["Estenosis aórtica","Hipertiroidismo","Infarto","Miocardiopatía hipertrófica"],"r":1,"e":"Hipertiroidismo, anemia, fístulas, beriberi, Paget, embarazo y sepsis causan insuficiencia de gasto alto.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Hombre de 45 años de una zona rural de Oaxaca con miocardiopatía dilatada, bloqueo de rama derecha y aneurisma apical.","p":"¿Qué causa sospechas?","o":["Alcohol","Enfermedad de Chagas","Sarcoidosis","Amiloidosis"],"r":1,"e":"La miocardiopatía chagásica es frecuente en Latinoamérica; típicos el bloqueo de rama derecha, el hemibloqueo anterior y el aneurisma apical.","f":"Harrison, capítulos 257 y 258"},{"c":"¿Cuál es la causa más frecuente de insuficiencia cardiaca con fracción reducida?","p":"Elige la opción correcta.","o":["Valvulopatía","Cardiopatía isquémica","Miocarditis","Tirotoxicosis"],"r":1,"e":"La cardiopatía isquémica es la causa más frecuente; después, miocardiopatía dilatada e hipertensión.","f":"Manual CTO, Cardiología, capítulo 4"},{"c":"Lactante de 6 semanas con taquipnea, sudoración al comer, se cansa al tomar el biberón y poca ganancia de peso. Hígado a 4 cm del reborde.","p":"¿Qué sospechas?","o":["Reflujo gastroesofágico","Insuficiencia cardiaca por cortocircuito de izquierda a derecha","Neumonía","Estenosis pilórica"],"r":1,"e":"A las 4 a 8 semanas bajan las resistencias pulmonares y los cortocircuitos grandes dan insuficiencia cardiaca; la hepatomegalia es el signo de congestión más fiable en lactantes.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"En el lactante con insuficiencia cardiaca, ¿qué signo de congestión es más útil?","p":"Elige la opción correcta.","o":["Ingurgitación yugular","Hepatomegalia","Edema de tobillos","Ascitis"],"r":1,"e":"En lactantes la ingurgitación yugular y el edema periférico son difíciles de ver; la hepatomegalia es el signo más fiable.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Recién nacido de 5 días que llega en choque con pulsos femorales casi ausentes y acidosis.","p":"¿Qué das primero para estabilizar?","o":["Indometacina","Prostaglandina E1","Digoxina","Propranolol"],"r":1,"e":"Lesión obstructiva izquierda dependiente del conducto (coartación crítica o corazón izquierdo hipoplásico): prostaglandina E1 para reabrir el conducto.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Recién nacido que recibe prostaglandina E1.","p":"¿Qué efecto adverso vigilas?","o":["Hipertensión","Apnea","Hiperglucemia","Bradicardia por bloqueo"],"r":1,"e":"La apnea es el efecto adverso más importante de la prostaglandina E1; también fiebre e hipotensión.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Prematuro de 28 semanas con soplo continuo, pulsos saltones y dificultad respiratoria. Ecocardiograma: conducto arterioso grande.","p":"¿Cuál es el tratamiento farmacológico?","o":["Prostaglandina E1","Ibuprofeno o indometacina","Digoxina sola","Adenosina"],"r":1,"e":"Los antiinflamatorios inhiben las prostaglandinas y cierran el conducto en el prematuro; el paracetamol es alternativa.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Niño con soplo continuo en maquinaria infraclavicular izquierdo y pulsos amplios.","p":"¿Qué cardiopatía tiene?","o":["Comunicación interauricular","Persistencia del conducto arterioso","Estenosis pulmonar","Tetralogía de Fallot"],"r":1,"e":"El soplo continuo en maquinaria (de Gibson) es típico del conducto arterioso persistente.","f":"Guía de Práctica Clínica IMSS-380-10"},{"c":"Según la guía mexicana, ¿desde cuándo se considera persistente el conducto arterioso?","p":"Elige la opción correcta.","o":["Después de 24 horas","Después de la sexta semana de vida","Después del año","Después de los 5 años"],"r":1,"e":"La guía IMSS-380-10 la define como la permeabilidad después de la sexta semana de vida extrauterina.","f":"Guía de Práctica Clínica IMSS-380-10"},{"c":"Niño de 3 años con soplo holosistólico rudo en el borde esternal izquierdo bajo, asintomático y con buen crecimiento.","p":"¿Qué cardiopatía es y qué evolución esperas?","o":["Comunicación interventricular pequeña; puede cerrar sola","Tetralogía de Fallot; cirugía urgente","Coartación; stent","Estenosis aórtica; cirugía"],"r":0,"e":"La comunicación interventricular es la más frecuente; las pequeñas muchas veces se cierran solas.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Mujer de 28 años con disnea de esfuerzo, desdoblamiento amplio y fijo del segundo ruido y bloqueo de rama derecha.","p":"¿Qué cardiopatía sospechas?","o":["Comunicación interventricular","Comunicación interauricular tipo ostium secundum","Conducto arterioso","Coartación"],"r":1,"e":"El desdoblamiento amplio y fijo del segundo ruido con bloqueo de rama derecha es clásico de la comunicación interauricular.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Adolescente con síndrome de Turner, hipertensión en brazos y pulsos femorales débiles y retrasados.","p":"¿Qué cardiopatía tiene?","o":["Coartación de aorta","Comunicación interauricular","Tetralogía de Fallot","Estenosis pulmonar"],"r":0,"e":"La coartación se asocia al síndrome de Turner; la diferencia de pulsos entre brazos y piernas es la clave.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Niño de 2 años con cianosis que al llorar se pone más morado, se pone irritable y luego letárgico. Radiografía con corazón en bota.","p":"¿Qué haces durante la crisis?","o":["Acostarlo boca arriba y dar digoxina","Posición rodillas al pecho, oxígeno, morfina y líquidos; propranolol","Prostaglandina E1 sola","Furosemida intravenosa"],"r":1,"e":"Crisis hipoxémica de Fallot: la posición genupectoral aumenta las resistencias sistémicas; se suman oxígeno, morfina, líquidos, propranolol y fenilefrina.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Recién nacido con cianosis intensa desde el nacimiento que no mejora con oxígeno, sin soplo importante. Radiografía con imagen de huevo en cuerda.","p":"¿Qué cardiopatía es?","o":["Tetralogía de Fallot","Transposición de grandes arterias","Comunicación interauricular","Conducto arterioso"],"r":1,"e":"La transposición es la cardiopatía cianótica más frecuente al nacer; se mantiene con prostaglandina E1 y atrioseptostomía hasta el switch arterial.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Paciente con comunicación interventricular grande no operada que ahora tiene cianosis e hipertensión pulmonar grave.","p":"¿Qué presenta y qué implica?","o":["Endocarditis; antibiótico","Síndrome de Eisenmenger; contraindica cerrar el defecto","Insuficiencia mitral; cirugía","Tetralogía de Fallot adquirida"],"r":1,"e":"En el Eisenmenger el cortocircuito se invierte por hipertensión pulmonar irreversible; cerrar el defecto está contraindicado.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Recién nacido con síndrome de Down.","p":"¿Qué cardiopatía buscas especialmente?","o":["Coartación de aorta","Canal auriculoventricular","Transposición","Estenosis aórtica supravalvular"],"r":1,"e":"El canal auriculoventricular es la cardiopatía típica del síndrome de Down.","f":"Manual CTO, Cardiología, capítulo 8"},{"c":"Tamiz cardiaco neonatal a las 30 horas: mano derecha 98%, pie 93%.","p":"¿Qué haces?","o":["Alta, es normal","Repetir: la diferencia es mayor de 3 puntos","Ecocardiograma urgente porque está debajo de 90%","Prostaglandina E1"],"r":1,"e":"Diferencia mayor de 3 puntos o saturación de 90 a 94% obliga a repetir; menos de 90% en cualquiera es falla y requiere ecocardiograma.","f":"Manual CTO, Cardiología, capítulo 8"}],"audio":[["¿Cómo se clasifica por fracción de eyección?","Reducida, 40% o menos; ligeramente reducida, 41 a 49%; preservada, 50% o más."],["¿Para qué sirve un péptido natriurético normal?","Para descartar insuficiencia cardiaca: tiene alto valor predictivo negativo."],["¿Qué estudio se le hace a todos?","Ecocardiograma."],["¿Cuáles son los cuatro pilares?","Inhibidor de la enzima convertidora o sacubitrilo con valsartán, betabloqueador, antagonista de mineralocorticoides e inhibidor del cotransportador sodio-glucosa tipo 2."],["¿Los diuréticos alargan la vida?","No. Solo quitan la congestión y los síntomas."],["¿Cuándo inicias el betabloqueador?","Con el paciente estable y sin congestión, a dosis baja, subiendo cada 2 semanas."],["¿Qué precaución con sacubitrilo con valsartán?","Dejar 36 horas sin inhibidor de la enzima convertidora por riesgo de angioedema."],["¿Qué fármacos evitas en fracción reducida?","Verapamilo, diltiazem, antiinflamatorios, pioglitazona y antiarrítmicos del grupo Ic."],["¿Cuándo pones desfibrilador?","Fracción de 35% o menos en clase II a III tras 3 meses de tratamiento óptimo; no en los primeros 40 días tras un infarto."],["¿Cuándo resincronización?","Fracción de 35% o menos, síntomas y QRS ancho, sobre todo bloqueo de rama izquierda de 150 milisegundos o más."],["¿Qué sirve en fracción preservada?","Dapagliflozina o empagliflozina, diurético si hay congestión y control de presión y fibrilación auricular."],["Dime el manejo del edema agudo de pulmón.","Sentar, oxígeno si satura menos de 90, furosemida intravenosa y nitroglicerina si la presión lo permite."],["¿Qué haces en el infarto del ventrículo derecho?","Líquidos. Sin nitratos ni diuréticos."],["¿Signos de intoxicación por digoxina?","Náusea, visión amarilla, extrasístoles, bloqueos y taquicardia ventricular bidireccional."],["¿Cómo se ve la insuficiencia cardiaca en un lactante?","Taquipnea, sudor al comer, poca ganancia de peso y hepatomegalia."],["¿Qué das a un recién nacido con cardiopatía dependiente del conducto?","Prostaglandina E1. Vigila apnea."],["¿Cómo cierras un conducto arterioso en un prematuro?","Ibuprofeno o indometacina; paracetamol como alternativa."],["Soplo continuo en maquinaria: ¿qué es?","Persistencia del conducto arterioso."],["Desdoblamiento fijo del segundo ruido: ¿qué es?","Comunicación interauricular."],["¿Qué haces en una crisis hipoxémica de Fallot?","Rodillas al pecho, oxígeno, morfina, líquidos y propranolol."],["¿Cardiopatía del síndrome de Down?","Canal auriculoventricular."],["¿Cardiopatía del síndrome de Turner?","Coartación de aorta."]],"profundizar":{"harrison":[[257,"Insuficiencia cardiaca: fisiopatología y diagnóstico"],[258,"Insuficiencia cardiaca: tratamiento"],[305,"Choque cardiógeno y edema pulmonar"],[269,"Cardiopatías congénitas en el adulto"]],"guias":[["Diagnóstico y tratamiento de la persistencia del conducto arterioso en niños, adolescentes y adultos, IMSS-380-10 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/380GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/380GRR.pdf"],["Detección de cardiopatías congénitas en niños mayores de 5 años, adolescentes y adultos, IMSS-054-08 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/054GER.pdf"],["Prevención, diagnóstico y tratamiento de la insuficiencia cardiaca crónica en el adulto, ISSSTE-722-15 (sin enlace oficial por ahora)",""],["Recomendaciones mexicanas para el diagnóstico y tratamiento de la insuficiencia cardiaca, Archivos de Cardiología de México 2024 (no es sitio de gobierno)",""]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Cardiología, capítulo 4 (páginas 24 a 35 del archivo) y capítulo 8 (páginas 72 a 83).","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 257, 258, 269 y 305.","Guías de Práctica Clínica IMSS-380-10 e IMSS-054-08, Instituto Mexicano del Seguro Social; Guía ISSSTE-722-15.","Recomendaciones mexicanas para el diagnóstico y tratamiento de la insuficiencia cardiaca, Archivos de Cardiología de México, 2024."]},"endocrinologia-5":{"titulo":"Diabetes mellitus tipo 2 en la consulta","enfoque":"Enfoque de consulta de primer nivel: diagnóstico, metas, tratamiento escalonado y vigilancia de complicaciones en el adulto.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La diabetes tipo 2 es hiperglucemia crónica por **resistencia a la insulina** más una **falla progresiva de la célula beta**; casi siempre se asocia a sobrepeso, obesidad abdominal y sedentarismo.","El diagnóstico exige **dos resultados alterados** (la misma prueba repetida o dos pruebas distintas), salvo glucosa al azar de 200 mg/dL o más con síntomas, que basta sola.","Meta para la mayoría: **hemoglobina glucosilada menor de 7%**; más laxa en adultos mayores frágiles o con hipoglucemias.","Primer fármaco: **metformina** junto con cambios de estilo de vida. Si hay enfermedad cardiovascular, insuficiencia cardiaca o enfermedad renal, agregar un **inhibidor del cotransportador sodio-glucosa tipo 2** o un **agonista del receptor del péptido similar al glucagón tipo 1**, sin importar la cifra de hemoglobina glucosilada.","Revisar y ajustar el tratamiento **cada 3 meses** si no está en metas: evitar la inercia terapéutica."]},{"h":"Diagnóstico","li":["Glucosa plasmática en ayuno de **126 mg/dL o más** (ayuno de al menos 8 horas).","Glucosa a las 2 horas de la curva de tolerancia oral con 75 g de glucosa de **200 mg/dL o más**.","Hemoglobina glucosilada de **6.5% o más**, con método certificado.","Glucosa al azar de **200 mg/dL o más con síntomas clásicos** (poliuria, polidipsia, polifagia, pérdida de peso) o crisis hiperglucémica: no requiere confirmación.","Si dos pruebas distintas no coinciden, se repite la que salió alterada; con resultados limítrofes, repetir en 3 a 6 meses.","La hemoglobina glucosilada no sirve en anemia de células falciformes, embarazo (segundo y tercer trimestre), hemodiálisis, transfusión o tratamiento con eritropoyetina: usar solo criterios de glucosa."]},{"h":"Prediabetes","li":["Glucosa alterada en ayuno: **100 a 125 mg/dL**.","Intolerancia a la glucosa: **140 a 199 mg/dL** a las 2 horas de la curva.","Hemoglobina glucosilada de **5.7 a 6.4%**.","Se vigila **cada año** y se tratan los factores de riesgo cardiovascular.","El protocolo del Instituto Mexicano del Seguro Social indica metformina en prediabetes en menores de 60 años, con índice de masa corporal mayor de 35 o con antecedente de diabetes gestacional."]},{"h":"A quién hacer tamizaje","li":["Todo adulto desde los **35 años**; antes si tiene sobrepeso (índice de masa corporal de 25 o más) y al menos un factor de riesgo.","Factores de riesgo: familiar de primer grado con diabetes, origen latino, hipertensión, enfermedad cardiovascular, colesterol de alta densidad menor de 35 o triglicéridos mayores de 250 mg/dL, síndrome de ovario poliquístico, sedentarismo, acantosis nigricans, antecedente de diabetes gestacional o de recién nacido de más de 4 kg.","Si el resultado es normal, repetir **cada 3 años**; mujeres con diabetes gestacional previa, al menos cada 3 años de por vida."]},{"h":"Metas de control","li":["Hemoglobina glucosilada: **menor de 7%** para la mayoría; **menor de 6.5%** en jóvenes, con poca evolución y sin riesgo de hipoglucemia; **menor de 8%** (hasta 8.5%) en adultos mayores frágiles, con hipoglucemias graves, poca expectativa de vida o complicaciones avanzadas.","Glucosa en ayuno o antes de comer: **80 a 130 mg/dL**. Glucosa 2 horas después de comer: **menor de 180 mg/dL**.","Presión arterial: **menor de 130/80 mmHg**.","Colesterol de baja densidad: muy alto riesgo menor de 70 mg/dL; alto riesgo menor de 100 mg/dL (protocolo del Instituto Mexicano del Seguro Social).","Peso: reducir **5 a 10%** si hay sobrepeso u obesidad."]},{"h":"Tratamiento no farmacológico","li":["Plan de alimentación con nutrición: reducir azúcares simples y bebidas azucaradas, porciones con el plato del bien comer.","Actividad física: al menos **150 minutos por semana** de ejercicio aeróbico moderado, repartidos en 3 o más días, más ejercicios de fuerza 2 veces por semana.","Dejar de fumar; educación en diabetes y autocuidado de pies."]},{"h":"Metformina: el primer fármaco","li":["Inicio: **500 mg cada 12 horas** u 850 mg una vez al día **con alimentos**; subir 500 mg por semana. Máximo **2,550 mg al día**.","Efectos adversos: digestivos (náusea, diarrea, distensión) al inicio; con el uso prolongado, **deficiencia de vitamina B12**; acidosis láctica es rara.","Función renal: **contraindicada con filtración glomerular menor de 30**; con 30 a 45 no iniciar; suspender antes de estudios con contraste yodado.","Si no se tolera: presentación de liberación prolongada o cambiar a un inhibidor de la dipeptidil peptidasa 4."]},{"h":"Segundo fármaco: según el perfil del paciente","li":["Enfermedad cardiovascular aterosclerótica o alto riesgo cardiovascular: **agonista del receptor del péptido similar al glucagón tipo 1** (liraglutida, dulaglutida, semaglutida) o **inhibidor del cotransportador sodio-glucosa tipo 2** (empagliflozina, dapagliflozina, canagliflozina) con beneficio demostrado.","Insuficiencia cardiaca o enfermedad renal crónica con albuminuria: **inhibidor del cotransportador sodio-glucosa tipo 2** de preferencia.","Necesidad de bajar peso: agonista del péptido similar al glucagón tipo 1 o inhibidor del cotransportador sodio-glucosa tipo 2.","Riesgo de hipoglucemia o adulto mayor frágil: **inhibidor de la dipeptidil peptidasa 4** (sitagliptina, linagliptina; esta última sin ajuste renal).","Bajo costo: **sulfonilurea** (glibenclamida, glimepirida): causa hipoglucemia y aumento de peso; el protocolo mexicano la reserva para menores de 65 años, filtración mayor de 60 e índice de masa corporal menor de 30.","**No combinar** inhibidor de la dipeptidil peptidasa 4 con agonista del péptido similar al glucagón tipo 1.","Iniciar con **dos fármacos** si la hemoglobina glucosilada está 1.5 puntos o más por arriba de la meta."]},{"h":"Efectos adversos que más se preguntan","li":["Inhibidores del cotransportador sodio-glucosa tipo 2: **infecciones genitales**, infección urinaria, hipovolemia y **cetoacidosis euglucémica**.","Agonistas del péptido similar al glucagón tipo 1: náusea y vómito; suspender si hay pancreatitis; contraindicados con antecedente personal o familiar de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2.","Pioglitazona: retención de líquidos y **empeora la insuficiencia cardiaca**; aumenta peso y riesgo de fracturas.","Sulfonilureas: **hipoglucemia** (sobre todo en adultos mayores y con falla renal) y aumento de peso."]},{"h":"Cuándo iniciar insulina","li":["Síntomas de catabolismo (pérdida de peso, cetosis), **hemoglobina glucosilada mayor de 10%** o **glucosa de 300 mg/dL o más**: insulina desde el inicio.","Protocolo del Instituto Mexicano del Seguro Social: hemoglobina glucosilada de 9% o más o glucosa mayor de 260 mg/dL; falla a triple terapia oral; embarazo; cirugía o imposibilidad para la vía oral.","Inicio con insulina basal: **10 unidades al día o 0.1 a 0.2 unidades por kilo** (glargina en la noche, o NPH con dos tercios en la mañana y un tercio en la noche).","Ajuste de glargina según el promedio de glucosa en ayuno, cada 7 días: 130 a 150 mg/dL, más 1 unidad; 150 a 179, más 2; 180 o más, más 3; menor de 80, menos 2.","Al iniciar insulina se suspenden sulfonilureas y pioglitazona; la metformina se mantiene."]},{"h":"Hipoglucemia","li":["Glucosa **menor de 70 mg/dL**. Síntomas adrenérgicos (temblor, sudoración, palpitaciones) y neuroglucopénicos (confusión, convulsiones).","Paciente consciente: **regla 15-15**: 15 g de azúcar de absorción rápida (medio vaso de jugo o refresco normal), medir a los 15 minutos y repetir si sigue baja.","Inconsciente: glucagón intramuscular o glucosa intravenosa al 50%.","Los betabloqueadores pueden **ocultar** los síntomas adrenérgicos."]},{"h":"Complicaciones: qué revisar y cada cuándo","li":["**Pies en cada consulta**; exploración completa cada año con **monofilamento de 10 g** y diapasón de 128 Hz (más seguido si hay riesgo).","**Fondo de ojo cada año** desde el diagnóstico.","**Cociente albúmina/creatinina en orina y filtración glomerular cada año**; albuminuria de 30 mg/g o más, confirmada en 2 de 3 muestras en 3 a 6 meses.","Perfil de lípidos al menos cada año (el protocolo mexicano lo pide cada 6 meses).","Hemoglobina glucosilada cada 3 meses si no está en metas y cada 6 meses si está controlada.","Estatina de intensidad moderada en diabéticos de 40 a 75 años; de alta intensidad si ya hay enfermedad cardiovascular."]},{"h":"Cuándo referir","li":["**Urgencias**: cetoacidosis diabética o estado hiperglucémico hiperosmolar, hipoglucemia grave, pie diabético infectado o con isquemia.","Nefrología: albuminuria mayor de 300 mg/g o filtración que cae rápido.","Medicina interna o endocrinología: falla a triple terapia, necesidad de esquema intensivo de insulina, sospecha de diabetes autoinmune del adulto o monogénica.","Oftalmología: cualquier alteración en el fondo de ojo."]}],"perlas":["La glucosa al azar de 200 mg/dL o más con síntomas **no se confirma**; todo lo demás sí.","Metformina se **suspende** con filtración menor de 30 y antes de contraste yodado.","Diabetes con insuficiencia cardiaca o enfermedad renal: **inhibidor del cotransportador sodio-glucosa tipo 2** aunque la hemoglobina glucosilada esté en meta.","Pioglitazona **contraindicada** en insuficiencia cardiaca.","Glucosuria y prurito genital en paciente con dapagliflozina: es efecto del fármaco (candidosis), no descontrol.","El monofilamento de 10 g detecta pérdida de la sensibilidad protectora: es el estudio clave del pie en primer nivel."],"mexico":["El Manual CTO sigue a la Asociación Americana de Diabetes. En México rigen la Guía de Práctica Clínica GPC-IMSS-718-18 (actualización 2018) y el Protocolo de Atención Integral de diabetes del Instituto Mexicano del Seguro Social (2022).","El protocolo mexicano define metas por grupos: menor de 7% en menores de 65 años sin daño renal; menor de 7.5% en mayores de 65 independientes o enfermedad renal 3; menor de 8% en frágiles o enfermedad renal 4; menor de 8.5% en enfermedad renal 5 o enfermedad terminal.","En el Instituto Mexicano del Seguro Social, los agonistas del péptido similar al glucagón tipo 1 se reservan a casos selectos con índice de masa corporal mayor de 35 y los prescribe endocrinología.","Los datos de epidemiología del CTO son de España; en México la diabetes es una de las primeras causas de muerte."],"preguntas":[{"c":"Hombre de 45 años, asintomático, con índice de masa corporal de 31. Glucosa en ayuno de 132 mg/dL en un estudio de rutina.","p":"¿Cuál es la conducta correcta?","o":["Diagnosticar diabetes e iniciar metformina","Repetir la glucosa en ayuno u otra prueba diagnóstica para confirmar","Solicitar curva de tolerancia con 100 g de glucosa","Diagnosticar prediabetes y citar en un año"],"r":1,"e":"En un paciente asintomático, un solo valor alterado no basta: se confirma con una segunda prueba (la misma repetida o una distinta). Solo la glucosa al azar de 200 mg/dL o más con síntomas no requiere confirmación. La curva de 100 g es para diabetes gestacional.","f":"Manual CTO, Endocrinología, capítulo 5, criterios diagnósticos (tabla 5.1)."},{"c":"Mujer de 38 años con poliuria, polidipsia y pérdida de 5 kg en dos meses. Glucosa capilar al azar de 286 mg/dL, confirmada en sangre venosa.","p":"¿Qué se concluye?","o":["Requiere una segunda glucosa en ayuno para el diagnóstico","Tiene diabetes; no requiere más pruebas para el diagnóstico","Requiere hemoglobina glucosilada antes de diagnosticar","Requiere curva de tolerancia oral a la glucosa"],"r":1,"e":"Glucosa plasmática al azar de 200 mg/dL o más con síntomas clásicos de hiperglucemia establece el diagnóstico sin confirmación. La pérdida de peso sugiere catabolismo: valorar insulina desde el inicio.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente de 50 años con glucosa en ayuno de 112 mg/dL y hemoglobina glucosilada de 6.0%.","p":"¿Cuál es su diagnóstico?","o":["Diabetes tipo 2","Normoglucemia","Prediabetes","Intolerancia a la glucosa confirmada"],"r":2,"e":"Glucosa en ayuno de 100 a 125 mg/dL y hemoglobina glucosilada de 5.7 a 6.4% corresponden a prediabetes. La intolerancia a la glucosa solo se define con la curva a las 2 horas (140 a 199 mg/dL).","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.1."},{"c":"Mujer de 29 años con anemia de células falciformes. Su hemoglobina glucosilada es de 5.2% pero tiene glucosas en ayuno de 140 y 138 mg/dL en días distintos.","p":"¿Qué se concluye?","o":["No tiene diabetes porque la hemoglobina glucosilada es normal","Tiene diabetes; la hemoglobina glucosilada no es confiable en su caso","Debe repetirse la hemoglobina glucosilada en 3 meses","Debe hacerse curva con 100 g"],"r":1,"e":"En anemia de células falciformes, embarazo, hemodiálisis o uso de eritropoyetina la hemoglobina glucosilada no es válida; se usan solo criterios de glucosa. Dos glucosas en ayuno de 126 o más confirman diabetes.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Hombre de 55 años recién diagnosticado con diabetes tipo 2. Hemoglobina glucosilada de 7.8%, filtración glomerular de 85, sin enfermedad cardiovascular.","p":"¿Cuál es el tratamiento farmacológico inicial de elección?","o":["Glibenclamida","Metformina con cambios en el estilo de vida","Insulina NPH","Pioglitazona"],"r":1,"e":"La metformina, junto con dieta y ejercicio, es la primera línea en ausencia de contraindicaciones. Las sulfonilureas causan hipoglucemia y aumento de peso; la insulina se reserva para hiperglucemia grave o catabolismo.","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.11; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Paciente diabético con metformina 850 mg cada 12 horas. Su filtración glomerular bajó a 24 mL/min.","p":"¿Qué haces con la metformina?","o":["Mantener la dosis","Reducir a 500 mg al día","Suspenderla","Cambiar a liberación prolongada"],"r":2,"e":"La metformina está contraindicada con filtración glomerular menor de 30 por el riesgo de acidosis láctica. Con 30 a 45 no se inicia y, si ya la toma, se valora reducir la dosis. Alternativas: inhibidor de la dipeptidil peptidasa 4 o insulina.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.18; ficha de metformina de GCHE2."},{"c":"Hombre de 62 años con diabetes tipo 2 e infarto de miocardio hace un año. Toma metformina y su hemoglobina glucosilada es de 6.8%.","p":"¿Qué conducta es la más adecuada?","o":["Continuar igual porque está en meta","Agregar un inhibidor del cotransportador sodio-glucosa tipo 2 o un agonista del péptido similar al glucagón tipo 1 con beneficio cardiovascular","Agregar glibenclamida","Agregar pioglitazona"],"r":1,"e":"Con enfermedad cardiovascular aterosclerótica establecida se recomienda un fármaco con beneficio cardiovascular demostrado independientemente de la hemoglobina glucosilada.","f":"Manual CTO, Endocrinología, capítulo 5, algoritmo de la Asociación Americana de Diabetes."},{"c":"Mujer de 68 años con diabetes tipo 2 e insuficiencia cardiaca con fracción de expulsión de 35%. Toma metformina.","p":"¿Qué segundo fármaco prefieres?","o":["Pioglitazona","Dapagliflozina","Glimepirida","Acarbosa"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 reducen hospitalizaciones por insuficiencia cardiaca. La pioglitazona está contraindicada en insuficiencia cardiaca porque causa retención de líquidos.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente con diabetes tipo 2 que inició empagliflozina hace 3 semanas. Acude por prurito y flujo vaginal blanco grumoso.","p":"¿Cuál es la explicación más probable?","o":["Descontrol glucémico grave","Candidosis vulvovaginal favorecida por la glucosuria del fármaco","Reacción alérgica al fármaco","Infección por Trichomonas por contacto sexual"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 producen glucosuria, lo que favorece infecciones genitales micóticas e infecciones urinarias.","f":"Manual CTO, Endocrinología, capítulo 5, efectos adversos de inhibidores del cotransportador sodio-glucosa tipo 2."},{"c":"Paciente de 50 años con diabetes tipo 2, tratado con dapagliflozina. Llega con náusea, dolor abdominal y respiración profunda. Glucosa de 210 mg/dL, pH de 7.18 y cetonas positivas.","p":"¿Qué complicación presenta?","o":["Estado hiperglucémico hiperosmolar","Cetoacidosis diabética euglucémica asociada al fármaco","Acidosis láctica por metformina","Gastroenteritis aguda"],"r":1,"e":"Los inhibidores del cotransportador sodio-glucosa tipo 2 pueden causar cetoacidosis con glucosa casi normal. Se suspende el fármaco y se refiere a urgencias.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Hombre de 48 años con diabetes de 6 años de evolución, con metformina y sitagliptina. Su médico quiere agregar liraglutida.","p":"¿Qué error hay en este plan?","o":["Ninguno, es una combinación recomendada","No se debe combinar un inhibidor de la dipeptidil peptidasa 4 con un agonista del péptido similar al glucagón tipo 1","La liraglutida está contraindicada con metformina","La liraglutida produce hipoglucemia grave"],"r":1,"e":"Ambos actúan sobre la misma vía de las incretinas; combinarlos no agrega beneficio. Si se inicia el agonista del péptido similar al glucagón tipo 1, se suspende el inhibidor de la dipeptidil peptidasa 4.","f":"Manual CTO, Endocrinología, capítulo 5, figura 5.11; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Mujer de 44 años con diabetes tipo 2 y antecedente familiar de carcinoma medular de tiroides.","p":"¿Qué fármaco está contraindicado?","o":["Metformina","Semaglutida","Linagliptina","Empagliflozina"],"r":1,"e":"Los agonistas del péptido similar al glucagón tipo 1 están contraindicados con antecedente personal o familiar de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2.","f":"Harrison, 21.ª edición, capítulo 404; etiquetas oficiales de los agonistas del péptido similar al glucagón tipo 1."},{"c":"Paciente de 58 años con diabetes tipo 2, con metformina y glimepirida. Hemoglobina glucosilada de 11.2% y glucosa en ayuno de 310 mg/dL, con pérdida de peso.","p":"¿Cuál es la conducta más adecuada?","o":["Agregar sitagliptina","Iniciar insulina basal","Aumentar la glimepirida al doble","Agregar acarbosa"],"r":1,"e":"Hemoglobina glucosilada mayor de 10%, glucosa de 300 mg/dL o más o datos de catabolismo son indicación de insulina.","f":"Manual CTO, Endocrinología, capítulo 5; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Hombre de 70 kg inicia insulina glargina.","p":"¿Cuál es una dosis inicial adecuada?","o":["0.5 unidades por kilo (35 unidades)","10 unidades al día o 0.1 a 0.2 unidades por kilo","1 unidad por kilo (70 unidades)","2 unidades al día"],"r":1,"e":"La insulina basal se inicia con 10 unidades al día o 0.1 a 0.2 unidades por kilo y se ajusta según la glucosa en ayuno cada semana.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Paciente con insulina glargina 14 unidades. El promedio de sus glucosas en ayuno de la última semana es de 165 mg/dL.","p":"¿Cómo ajustas la dosis?","o":["Bajar 2 unidades","Subir 2 unidades","Subir 6 unidades","Dejar igual"],"r":1,"e":"Según el protocolo mexicano: glucosa en ayuno de 150 a 179 mg/dL, subir 2 unidades; 130 a 150, subir 1; 180 o más, subir 3; menor de 80, bajar 2.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social, 2022."},{"c":"Mujer de 82 años, frágil, con caídas recientes y diabetes tipo 2 de larga evolución. Hemoglobina glucosilada de 7.7%.","p":"¿Qué meta de hemoglobina glucosilada es apropiada?","o":["Menor de 6.5%","Menor de 7%","Menor de 8 a 8.5%, evitando hipoglucemias","No importa la meta en adultos mayores"],"r":2,"e":"En adultos mayores frágiles, con poca expectativa de vida o riesgo de hipoglucemia, se aceptan metas más laxas; su 7.7% ya es aceptable y no se debe intensificar.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.20; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente diabético en consulta de control.","p":"¿Cuál es la meta de glucosa en ayuno para la mayoría de los adultos?","o":["70 a 100 mg/dL","80 a 130 mg/dL","130 a 180 mg/dL","Menor de 200 mg/dL"],"r":1,"e":"Meta en ayuno o antes de comer: 80 a 130 mg/dL; después de comer, menor de 180 mg/dL.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.20."},{"c":"Paciente con diabetes tipo 2 e hipertensión.","p":"¿Cuál es la meta de presión arterial que se recomienda?","o":["Menor de 150/90 mmHg","Menor de 140/90 mmHg en todos los casos","Menor de 130/80 mmHg","Menor de 110/70 mmHg"],"r":2,"e":"En diabéticos se recomienda presión menor de 130/80 mmHg si se tolera.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Cardiología, capítulo 14."},{"c":"Hombre de 60 años con diabetes de 10 años de evolución. Refiere ardor en ambos pies de predominio nocturno.","p":"¿Qué estudio es clave en primer nivel para identificar riesgo de úlcera?","o":["Radiografía de pies","Exploración con monofilamento de 10 g","Electromiografía","Resonancia magnética"],"r":1,"e":"El monofilamento de Semmes-Weinstein de 10 g detecta la pérdida de sensibilidad protectora, principal factor de riesgo de úlcera. Se complementa con diapasón de 128 Hz y revisión de pulsos.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente diabético con cociente albúmina/creatinina de 85 mg/g en una muestra.","p":"¿Qué haces?","o":["Diagnosticar nefropatía diabética de inmediato","Confirmar con otras muestras: debe salir alterado en 2 de 3 en 3 a 6 meses","Suspender la metformina","Referir a nefrología de inmediato"],"r":1,"e":"La albuminuria se confirma en 2 de 3 determinaciones en 3 a 6 meses, porque el ejercicio, la fiebre o la infección urinaria la elevan transitoriamente. La referencia a nefrología es con más de 300 mg/g o caída rápida de la filtración.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente diabético con albuminuria persistente e hipertensión.","p":"¿Qué grupo de antihipertensivos prefieres?","o":["Betabloqueadores","Inhibidores de la enzima convertidora de angiotensina o antagonistas del receptor de angiotensina II","Diuréticos de asa","Alfabloqueadores"],"r":1,"e":"Los inhibidores de la enzima convertidora de angiotensina y los antagonistas del receptor de angiotensina II reducen la albuminuria y retrasan la progresión de la nefropatía diabética. No se combinan entre sí.","f":"Manual CTO, Cardiología, capítulo 14, tabla 14.5."},{"c":"Paciente con diabetes tipo 2 recién diagnosticada.","p":"¿Cuándo debe hacerse el primer fondo de ojo?","o":["A los 5 años del diagnóstico","Al momento del diagnóstico y después cada año","Solo si tiene visión borrosa","Solo si la hemoglobina glucosilada es mayor de 9%"],"r":1,"e":"En diabetes tipo 2 la retinopatía puede existir desde el diagnóstico porque la enfermedad lleva años sin detectarse. Se revisa al diagnóstico y cada año.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."},{"c":"Paciente con glibenclamida que llega con sudoración, temblor y confusión leve, pero puede tragar. Glucosa capilar de 52 mg/dL.","p":"¿Cuál es el tratamiento inmediato?","o":["Insulina rápida","15 g de azúcar de absorción rápida y repetir glucosa en 15 minutos","Glucagón intravenoso","Observar sin tratamiento"],"r":1,"e":"En el paciente consciente se aplica la regla 15-15. Las hipoglucemias por sulfonilurea pueden ser prolongadas: vigilar varias horas y revalorar el fármaco.","f":"Manual CTO, Endocrinología, capítulo 5, hipoglucemia."},{"c":"Paciente diabético con metformina desde hace 8 años refiere parestesias en pies y tiene anemia macrocítica.","p":"¿Qué debes descartar?","o":["Deficiencia de hierro","Deficiencia de vitamina B12 por uso prolongado de metformina","Hipotiroidismo por metformina","Intoxicación por metformina"],"r":1,"e":"El uso prolongado de metformina reduce la absorción de vitamina B12, lo que causa anemia megaloblástica y neuropatía, que puede confundirse con neuropatía diabética.","f":"Harrison, 21.ª edición, capítulo 404."},{"c":"Mujer de 34 años con índice de masa corporal de 28 y diabetes gestacional en su embarazo previo. Su curva posparto fue normal.","p":"¿Cada cuánto se debe repetir el tamizaje de diabetes?","o":["Nunca más","Al menos cada 3 años de por vida","Solo en un próximo embarazo","Cada 10 años"],"r":1,"e":"Las mujeres con antecedente de diabetes gestacional tienen alto riesgo de diabetes tipo 2 y deben tamizarse al menos cada 3 años de por vida.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.2."},{"c":"Hombre de 30 años, asintomático, con índice de masa corporal de 24 y sin factores de riesgo.","p":"¿A qué edad inicia el tamizaje de diabetes según la Asociación Americana de Diabetes?","o":["18 años","35 años","45 años","60 años"],"r":1,"e":"El tamizaje universal inicia a los 35 años; antes si hay sobrepeso con al menos un factor de riesgo. Con resultado normal, repetir cada 3 años.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.2."},{"c":"Paciente de 66 años, con diabetes y filtración glomerular de 40, con riesgo de hipoglucemia. Toma metformina a dosis reducida.","p":"¿Qué segundo fármaco es más seguro?","o":["Glibenclamida","Linagliptina","Glimepirida a dosis alta","Clorpropamida"],"r":1,"e":"Los inhibidores de la dipeptidil peptidasa 4 tienen bajo riesgo de hipoglucemia; la linagliptina no requiere ajuste renal. Las sulfonilureas se acumulan en falla renal y causan hipoglucemias graves.","f":"Manual CTO, Endocrinología, capítulo 5, tabla 5.18; Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social."},{"c":"Paciente con diabetes tipo 2 y obesidad (índice de masa corporal de 36), con metformina y hemoglobina glucosilada de 8.1%. Desea bajar de peso.","p":"¿Qué familia de fármacos favorece más la pérdida de peso?","o":["Sulfonilureas","Agonistas del receptor del péptido similar al glucagón tipo 1","Pioglitazona","Insulina"],"r":1,"e":"Los agonistas del péptido similar al glucagón tipo 1 producen la mayor pérdida de peso; los inhibidores del cotransportador sodio-glucosa tipo 2 también la favorecen. Sulfonilureas, pioglitazona e insulina aumentan el peso.","f":"Manual CTO, Endocrinología, capítulo 5."},{"c":"Diabético de 52 años sin enfermedad cardiovascular, con colesterol de baja densidad de 118 mg/dL.","p":"¿Qué recomiendas para su riesgo cardiovascular?","o":["Ningún tratamiento hasta que el colesterol pase de 190 mg/dL","Estatina de intensidad moderada","Aspirina diaria como prevención primaria de rutina","Fibrato como primera elección"],"r":1,"e":"En diabéticos de 40 a 75 años se recomienda estatina de intensidad moderada aunque no tengan enfermedad cardiovascular. La aspirina en prevención primaria no es de rutina por el riesgo de sangrado.","f":"Asociación Americana de Diabetes, estándares de atención; Manual CTO, Cardiología, capítulo 14."},{"c":"Paciente diabético con hemoglobina glucosilada de 9.5% a pesar de metformina a dosis máxima. Lleva 8 meses igual.","p":"¿Qué concepto describe esta situación?","o":["Diabetes resistente","Inercia terapéutica","Seudohipoglucemia","Fenómeno del alba"],"r":1,"e":"La inercia terapéutica es no intensificar el tratamiento pese a no alcanzar metas. El tratamiento debe revisarse y ajustarse cada 3 meses.","f":"Protocolo de Atención Integral de diabetes, Instituto Mexicano del Seguro Social; Manual CTO, Endocrinología, capítulo 5."}],"audio":[["¿Cuáles son los cuatro criterios diagnósticos de diabetes?","Glucosa en ayuno de 126 o más; curva de tolerancia a las 2 horas de 200 o más; hemoglobina glucosilada de 6.5% o más; y glucosa al azar de 200 o más con síntomas, que es la única que no se confirma."],["¿Qué cifras definen prediabetes?","Glucosa en ayuno de 100 a 125, curva a las 2 horas de 140 a 199, o hemoglobina glucosilada de 5.7 a 6.4%."],["¿Desde qué edad se hace tamizaje?","Desde los 35 años, o antes si hay sobrepeso con un factor de riesgo. Si es normal, cada 3 años."],["¿Cuál es la meta de hemoglobina glucosilada?","Menor de 7% para la mayoría; menor de 6.5% en jóvenes sin riesgo de hipoglucemia; menor de 8% en adultos mayores frágiles."],["¿Cuál es el primer fármaco y cómo se inicia?","Metformina, 500 miligramos cada 12 horas con alimentos, subiendo cada semana hasta un máximo de 2,550 miligramos al día."],["¿Cuándo se suspende la metformina?","Con filtración glomerular menor de 30 y antes de estudios con contraste yodado."],["¿Qué agrego si hay enfermedad cardiovascular, insuficiencia cardiaca o enfermedad renal?","Un inhibidor del cotransportador sodio-glucosa tipo 2, o un agonista del péptido similar al glucagón tipo 1 si hay enfermedad aterosclerótica, aunque la hemoglobina glucosilada esté en meta."],["¿Qué efecto adverso típico tienen las gliflozinas?","Infecciones genitales micóticas, infección urinaria y cetoacidosis euglucémica."],["¿Qué antidiabético está contraindicado en insuficiencia cardiaca?","La pioglitazona, porque retiene líquidos."],["¿Cuándo se inicia insulina?","Con catabolismo, hemoglobina glucosilada mayor de 10% o glucosa de 300 o más. Se inicia basal con 10 unidades o 0.1 a 0.2 unidades por kilo."],["¿Cómo se trata una hipoglucemia en el paciente consciente?","Regla 15-15: 15 gramos de azúcar rápida y medir de nuevo a los 15 minutos."],["¿Qué se revisa cada año?","Fondo de ojo, cociente albúmina-creatinina con filtración glomerular, pie completo con monofilamento de 10 gramos y perfil de lípidos."],["¿Qué dos familias no se combinan?","Inhibidores de la dipeptidil peptidasa 4 con agonistas del péptido similar al glucagón tipo 1."]],"profundizar":{"harrison":[[403,"Diabetes mellitus: diagnóstico, clasificación y fisiopatología"],[404,"Diabetes mellitus: tratamiento"],[405,"Diabetes mellitus: complicaciones"]],"guias":[["Diagnóstico y tratamiento farmacológico de la diabetes mellitus tipo 2 en el primer nivel de atención, GPC-IMSS-718-18, actualización 2018","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/718GER.pdf"],["Protocolo de Atención Integral: prevención, diagnóstico y tratamiento de diabetes mellitus 2, Instituto Mexicano del Seguro Social, 2022","https://revistamedica.imss.gob.mx/index.php/revista_medica/article/download/4200/4317/29125"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Endocrinología, capítulo 5, páginas 99 a 126 del archivo.","Guía de Práctica Clínica GPC-IMSS-718-18, actualización 2018.","Protocolo de Atención Integral de diabetes mellitus 2, Instituto Mexicano del Seguro Social, Revista Médica del IMSS 2022;60 Supl 1:S4-18.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 403 a 405.","Ficha verificada de metformina en GCHE2 (etiqueta oficial)."]},"endocrinologia-7":{"titulo":"Dislipidemia y obesidad en la consulta","enfoque":"Enfoque de consulta de primer nivel: tamizaje y riesgo cardiovascular, metas de colesterol, estatinas, hipertrigliceridemia, índice de masa corporal, síndrome metabólico y tratamiento de la obesidad.","resumen":[{"h":"Lo esencial en 30 segundos","li":["Ante cualquier dislipidemia, descarta primero las **causas secundarias**: diabetes mal controlada, **hipotiroidismo**, obesidad, alcohol, síndrome nefrótico y fármacos.","El tratamiento depende del **riesgo cardiovascular**; en México se estima con **Globorisk** desde los 40 años.","Metas de colesterol de baja densidad: **muy alto riesgo menor de 70 mg/dL**, alto riesgo menor de 100, riesgo moderado menor de 115 (guía mexicana).","El fármaco base son las **estatinas**; si no llega a la meta, agregar **ezetimiba**.","Triglicéridos de **500 o más** (sobre todo más de 1,000): riesgo de **pancreatitis**; se tratan primero con **fibrato**.","Obesidad: índice de masa corporal de **30 o más**. Fármacos con 30 o más, o 27 con comorbilidad; **cirugía bariátrica con 40 o más, o 35 con comorbilidad**."]},{"h":"Tamizaje y estudio","li":["Guía mexicana: colesterol total y triglicéridos en **mayores de 20 años**; si son normales, repetir **cada 5 años**.","Historia y exploración: enfermedad cardiovascular, muerte cardiovascular prematura en la familia, tabaco, presión, peso, cintura, **xantomas** y soplos carotídeos.","Colesterol de baja densidad calculado (fórmula de Friedewald): colesterol total menos colesterol de alta densidad menos triglicéridos entre 5; **no sirve con triglicéridos de 400 o más**.","Colesterol no de alta densidad = colesterol total menos colesterol de alta densidad; útil cuando los triglicéridos están altos."]},{"h":"Riesgo cardiovascular (guía mexicana)","li":["**Muy alto**: enfermedad cardiovascular establecida (infarto, revascularización, evento vascular cerebral isquémico), **diabetes con daño a órgano blanco**, filtración glomerular **menor de 60** o Globorisk **mayor de 10%** a 10 años.","**Alto**: Globorisk de 5 a 10%, presión de 180/110 o más, colesterol total mayor de 310 mg/dL o dislipidemia familiar.","**Moderado**: Globorisk de 1 a 5%. **Bajo**: menor de 1%."]},{"h":"Causas secundarias","li":["La más frecuente es la **diabetes tipo 2** (triglicéridos altos y colesterol de alta densidad bajo).","**Hipotiroidismo**: colesterol de baja densidad alto; se corrige con levotiroxina antes de dar estatina. Pide hormona estimulante de la tiroides.","Síndrome nefrótico, colestasis, alcohol, obesidad.","Fármacos: tiazidas, betabloqueadores, corticoides, estrógenos orales, retinoides, antirretrovirales."]},{"h":"Hipercolesterolemia familiar","li":["Sospechar con colesterol de baja densidad **mayor de 190 mg/dL** sin causa secundaria, **xantomas tendinosos**, **arco corneal antes de los 45 años** o cardiopatía coronaria prematura (hombre menor de 55, mujer menor de 65) en el paciente o en familiares de primer grado.","Herencia autosómica dominante, casi siempre por defecto del **receptor de lipoproteínas de baja densidad**.","Tratamiento desde el diagnóstico: dieta y **estatina de alta intensidad**; ezetimiba e inhibidores de PCSK9 si no se llega a la meta. Estudiar a la familia."]},{"h":"Estatinas","li":["**Alta intensidad** (bajan el colesterol de baja densidad 50% o más): atorvastatina 40 a 80 mg, rosuvastatina 20 a 40 mg.","**Intensidad moderada** (30 a 49%): atorvastatina 10 a 20 mg, rosuvastatina 5 a 10 mg, simvastatina 20 a 40 mg, pravastatina 40 a 80 mg.","Indicaciones clave: prevención secundaria (alta intensidad), colesterol de baja densidad de **190 o más**, diabéticos de 40 a 75 años (moderada; alta si hay factores de riesgo) y según el riesgo calculado.","Efectos adversos: **mialgias**, miopatía, **rabdomiólisis** (creatina fosfocinasa más de 10 veces lo normal) y elevación de transaminasas. Pide creatina fosfocinasa **solo si hay síntomas musculares** o riesgo.","Más riesgo de miopatía con **gemfibrozilo**, macrólidos, ciclosporina, hipotiroidismo y edad avanzada. **Contraindicadas en el embarazo**.","Seguimiento: perfil de lípidos a las **12 semanas** de iniciar o ajustar, luego cada 6 a 12 meses."]},{"h":"Otros fármacos","li":["**Ezetimiba**: inhibe la absorción intestinal de colesterol; se agrega a la estatina si no se llega a la meta.","**Inhibidores de PCSK9** (evolocumab, alirocumab): muy alto riesgo o hipercolesterolemia familiar sin meta pese a estatina y ezetimiba.","**Fibratos** (bezafibrato, fenofibrato): para triglicéridos altos; la guía mexicana los agrega con triglicéridos de 204 o más y colesterol de alta densidad menor de 35.","Ácidos grasos omega 3: coadyuvantes en hipertrigliceridemia."]},{"h":"Hipertrigliceridemia","li":["Busca causas: alcohol, diabetes descontrolada, obesidad, hipotiroidismo, embarazo, fármacos.","Con triglicéridos de **500 mg/dL o más**: dieta muy baja en grasa, **suspender el alcohol**, controlar la glucosa y **fibrato** para prevenir pancreatitis.","Con más de 1,000: **xantomas eruptivos**, lipemia retinalis, dolor abdominal y **pancreatitis aguda**.","Entre 150 y 499 con riesgo cardiovascular: primero estilo de vida y estatina según el riesgo."]},{"h":"Obesidad: clasificación","li":["Índice de masa corporal = peso en kilos entre talla en metros al cuadrado.","**Sobrepeso 25 a 29.9**; obesidad **grado 1: 30 a 34.9**, **grado 2: 35 a 39.9**, **grado 3: 40 o más**.","Mide la **cintura** con índice de 25 a 35: la grasa abdominal aumenta el riesgo cardiovascular. Riesgo con más de 102 cm en hombres y 88 en mujeres (criterio internacional); la norma mexicana usa 90 y 80 cm.","No uses el índice de masa corporal en embarazadas ni en lactancia."]},{"h":"Síndrome metabólico","li":["**Tres o más** de: cintura aumentada; triglicéridos de **150 o más**; colesterol de alta densidad **menor de 40 en hombres y 50 en mujeres**; presión de **130/85 o más**; glucosa en ayuno de **100 o más** (o tratamiento para cualquiera de ellos).","Duplica el riesgo cardiovascular y aumenta mucho el de diabetes: el tratamiento es **bajar de peso y ejercicio**."]},{"h":"Obesidad: tratamiento","li":["Meta inicial: bajar **5 a 10% del peso** en 6 meses; ya con 5% mejoran presión, glucosa y lípidos.","Dieta con déficit de **500 a 750 kilocalorías al día**; patrón mediterráneo o dieta para la hipertensión (DASH); ejercicio de **150 a 300 minutos por semana**; terapia conductual.","**Fármacos** con índice de **30 o más, o 27 o más con comorbilidad**: agonistas del péptido similar al glucagón tipo 1 (liraglutida 3 mg diaria, semaglutida 2.4 mg semanal), **orlistat 120 mg con cada comida**, fentermina con topiramato.","Si a las **12 semanas** no bajó al menos 5% del peso, cambiar o suspender el fármaco.","**Cirugía bariátrica**: índice de **40 o más, o 35 o más con comorbilidad grave**, tras fallar el tratamiento médico. Tras la cirugía, vigilar deficiencias de **vitamina B12, hierro, calcio y vitamina D**."]},{"h":"Complicaciones de la obesidad","li":["Diabetes tipo 2, hipertensión, dislipidemia, **apnea obstructiva del sueño**, hígado graso, reflujo gastroesofágico, colelitiasis, artrosis de rodillas, infertilidad y síndrome de ovario poliquístico, y algunos cánceres (endometrio, mama, colon).","Antes de tratar, descarta causas secundarias: **hipotiroidismo**, síndrome de Cushing y fármacos (antipsicóticos, corticoides, insulina, sulfonilureas, algunos antidepresivos)."]}],"perlas":["Dislipidemia: primero **descartar hipotiroidismo** y otras causas secundarias.","Xantomas tendinosos y arco corneal en un joven: **hipercolesterolemia familiar**.","Muy alto riesgo: colesterol de baja densidad **menor de 70**.","Triglicéridos mayores de 1,000 con dolor abdominal: **pancreatitis**; tratamiento con **fibrato**.","Estatina más gemfibrozilo: **riesgo de rabdomiólisis**.","Orlistat: **esteatorrea** y deficiencia de vitaminas liposolubles.","Cirugía bariátrica: índice de **40, o 35 con comorbilidad**."],"mexico":["La Guía de Práctica Clínica IMSS-233-09 (actualización 2016) recomienda **Globorisk**, validado en población mexicana, para estimar el riesgo en mayores de 40 años; el CTO usa la escala SCORE2 de Europa.","La guía mexicana fija la meta de **menor de 70** en muy alto riesgo; las guías europeas recientes, que sigue el CTO, piden **menor de 55** y una reducción de al menos 50%.","La Guía de Práctica Clínica IMSS-046-08 (actualización 2018) de obesidad propone **orlistat** como primer fármaco y aún menciona **lorcaserina**, que fue **retirada del mercado en 2020** por riesgo de cáncer: no la uses.","La norma mexicana usa cintura de riesgo de 90 cm en hombres y 80 cm en mujeres; los criterios internacionales del síndrome metabólico usan 102 y 88."],"preguntas":[{"c":"Mujer de 48 años con colesterol total de 290 mg/dL, aumento de peso, estreñimiento, piel seca y bradicardia.","p":"¿Qué estudio pides antes de iniciar estatina?","o":["Creatina fosfocinasa","Hormona estimulante de la tiroides","Ecocardiograma","Colesterol de lipoproteína a"],"r":1,"e":"El hipotiroidismo es causa secundaria de hipercolesterolemia; se trata primero y el colesterol suele mejorar.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Cuál es la causa más frecuente de dislipidemia secundaria?","p":"Elige la opción correcta.","o":["Hipotiroidismo","Diabetes tipo 2","Síndrome nefrótico","Colestasis"],"r":1,"e":"La dislipidemia secundaria más frecuente es la de la diabetes tipo 2: triglicéridos altos y colesterol de alta densidad bajo.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Hombre de 32 años con colesterol de baja densidad de 260 mg/dL, xantomas en tendones de Aquiles y padre con infarto a los 45 años.","p":"¿Cuál es el diagnóstico?","o":["Hiperlipidemia familiar combinada","Hipercolesterolemia familiar","Disbetalipoproteinemia","Hipertrigliceridemia familiar"],"r":1,"e":"Colesterol de baja densidad muy alto, xantomas tendinosos y cardiopatía prematura en la familia definen la hipercolesterolemia familiar.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"En el paciente anterior, ¿cuál es el tratamiento inicial?","p":"Elige la opción correcta.","o":["Dieta por 6 meses y revalorar","Estatina de alta intensidad desde el diagnóstico","Fibrato","Omega 3"],"r":1,"e":"En la hipercolesterolemia familiar se inicia estatina de alta intensidad junto con la dieta desde el diagnóstico.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Hombre de 58 años con infarto hace 6 meses.","p":"¿Cuál es su meta de colesterol de baja densidad según la guía mexicana?","o":["Menor de 130","Menor de 115","Menor de 100","Menor de 70"],"r":3,"e":"En prevención secundaria es muy alto riesgo: meta menor de 70 mg/dL y estatina de alta intensidad.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"¿Cuál de estas es una estatina de alta intensidad?","p":"Elige la opción correcta.","o":["Simvastatina 20 mg","Pravastatina 40 mg","Atorvastatina 80 mg","Rosuvastatina 5 mg"],"r":2,"e":"Alta intensidad: atorvastatina 40 a 80 mg o rosuvastatina 20 a 40 mg; reducen el colesterol de baja densidad 50% o más.","f":"Harrison, capítulo 407"},{"c":"Paciente con estatina que refiere dolor muscular intenso, orina oscura y creatina fosfocinasa 15 veces lo normal.","p":"¿Qué presenta y qué haces?","o":["Mialgia leve; seguir igual","Rabdomiólisis; suspender la estatina","Hipotiroidismo; agregar levotiroxina","Miositis viral; agregar fibrato"],"r":1,"e":"Creatina fosfocinasa mayor de 10 veces lo normal con síntomas es rabdomiólisis: se suspende la estatina y no se reinicia.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Qué combinación aumenta más el riesgo de miopatía?","p":"Elige la opción correcta.","o":["Estatina con ezetimiba","Estatina con gemfibrozilo","Estatina con metformina","Estatina con losartán"],"r":1,"e":"El gemfibrozilo eleva las concentraciones de estatina y el riesgo de miopatía y rabdomiólisis; si se requiere fibrato se prefiere fenofibrato.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Paciente asintomático que inicia atorvastatina.","p":"¿Cuándo pides creatina fosfocinasa?","o":["Cada mes","Solo si hay síntomas musculares o factores de riesgo","Antes de cada consulta","Nunca"],"r":1,"e":"La guía mexicana recomienda medir creatina fosfocinasa solo con síntomas musculares o riesgo aumentado de miopatía.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Paciente que inició estatina hace 3 semanas.","p":"¿Cuándo repites el perfil de lípidos?","o":["A la semana","A las 12 semanas","Al año","No es necesario"],"r":1,"e":"Se pide perfil de lípidos a las 12 semanas de iniciar o ajustar la estatina y luego cada 6 a 12 meses.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Paciente de muy alto riesgo con atorvastatina 80 mg; colesterol de baja densidad sigue en 98 mg/dL.","p":"¿Qué agregas?","o":["Fibrato","Ezetimiba","Omega 3","Niacina"],"r":1,"e":"Si no se alcanza la meta con la dosis máxima tolerada de estatina, se agrega ezetimiba.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Hombre de 45 años con alcoholismo, dolor abdominal y triglicéridos de 1,800 mg/dL. Lipasa elevada.","p":"¿Cuál es la causa del dolor?","o":["Colecistitis","Pancreatitis por hipertrigliceridemia","Úlcera péptica","Isquemia mesentérica"],"r":1,"e":"Triglicéridos mayores de 1,000 causan pancreatitis aguda; el alcohol es un desencadenante.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Paciente con triglicéridos de 780 mg/dL y colesterol de baja densidad normal.","p":"¿Cuál es el fármaco de elección para prevenir pancreatitis?","o":["Estatina","Fibrato","Ezetimiba","Colestiramina"],"r":1,"e":"Con triglicéridos de 500 o más el objetivo inmediato es prevenir pancreatitis: dieta, sin alcohol y fibrato.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Qué lesión cutánea aparece con triglicéridos muy altos?","p":"Elige la opción correcta.","o":["Xantomas tendinosos","Xantomas eruptivos","Xantelasmas aislados","Acantosis nigricans"],"r":1,"e":"Los xantomas eruptivos (pápulas amarillas en glúteos y extremidades) aparecen con hipertrigliceridemia grave y desaparecen al bajarla.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Perfil de lípidos con triglicéridos de 520 mg/dL.","p":"¿Por qué no usas la fórmula de Friedewald?","o":["Porque sobreestima el colesterol de alta densidad","Porque no es válida con triglicéridos de 400 o más","Porque solo sirve en niños","Porque requiere ayuno de 24 horas"],"r":1,"e":"La fórmula de Friedewald no es válida con triglicéridos de 400 o más; se usa el colesterol no de alta densidad o la medición directa.","f":"Harrison, capítulo 407"},{"c":"¿A partir de qué edad recomienda la guía mexicana el tamizaje de lípidos en adultos sin factores de riesgo?","p":"Elige la opción correcta.","o":["10 años","20 años","40 años","65 años"],"r":1,"e":"Tamizaje con colesterol total y triglicéridos en mayores de 20 años; repetir cada 5 años si es normal.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"¿Qué herramienta recomienda la guía mexicana para estimar el riesgo cardiovascular?","p":"Elige la opción correcta.","o":["Framingham original","Globorisk","Escala de Wells","CHA2DS2-VASc"],"r":1,"e":"Globorisk está validado en población mexicana y se usa desde los 40 años.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Diabético de 55 años sin otros factores de riesgo.","p":"¿Qué estatina le corresponde?","o":["Ninguna","Intensidad moderada","Alta intensidad siempre","Solo fibrato"],"r":1,"e":"Diabéticos de 40 a 75 años sin otros factores de riesgo: estatina de intensidad moderada; con factores de riesgo, de alta intensidad.","f":"Guía de Práctica Clínica IMSS-233-09"},{"c":"Mujer de 30 años que toma atorvastatina y planea embarazarse.","p":"¿Qué le indicas?","o":["Seguir la estatina","Suspender la estatina antes del embarazo","Cambiar a rosuvastatina","Duplicar la dosis"],"r":1,"e":"Las estatinas están contraindicadas en el embarazo y la lactancia.","f":"Harrison, capítulo 407"},{"c":"¿Cuál es el mecanismo de la ezetimiba?","p":"Elige la opción correcta.","o":["Inhibe la HMG-CoA reductasa","Inhibe la absorción intestinal de colesterol","Activa receptores PPAR alfa","Secuestra ácidos biliares"],"r":1,"e":"La ezetimiba bloquea la proteína transportadora de colesterol en el intestino (NPC1L1).","f":"Harrison, capítulo 407"},{"c":"Hombre de 40 años, 95 kg y 1.75 m.","p":"¿Cuál es su índice de masa corporal y clasificación?","o":["27, sobrepeso","31, obesidad grado 1","36, obesidad grado 2","41, obesidad grado 3"],"r":1,"e":"95 entre 1.75 al cuadrado (3.06) da 31: obesidad grado 1.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Mujer con índice de masa corporal de 37 y diabetes tipo 2.","p":"¿Cómo se clasifica su obesidad?","o":["Grado 1","Grado 2","Grado 3","Sobrepeso"],"r":1,"e":"Grado 2 es de 35 a 39.9.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"¿En qué rango de índice de masa corporal recomienda la guía mexicana medir además la cintura?","p":"Elige la opción correcta.","o":["Menor de 18.5","25 a 35","Mayor de 40","Solo en niños"],"r":1,"e":"Entre 25 y 35 la cintura detecta grasa abdominal que el índice no capta; con más de 35 ya no es necesaria.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Hombre con cintura de 106 cm, triglicéridos de 210, colesterol de alta densidad de 36, presión de 128/80 y glucosa de 92.","p":"¿Tiene síndrome metabólico?","o":["No, solo 2 criterios","Sí, tiene 3 criterios","No, la presión es normal","Sí, porque la glucosa es normal"],"r":1,"e":"Cintura mayor de 102, triglicéridos de 150 o más y colesterol de alta densidad menor de 40: son 3 criterios.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Cuál es el tratamiento principal del síndrome metabólico?","p":"Elige la opción correcta.","o":["Metformina a todos","Bajar de peso y aumentar la actividad física","Estatina a todos","Cirugía bariátrica"],"r":1,"e":"La base es el cambio de estilo de vida con pérdida de peso y ejercicio; los fármacos tratan cada componente según su meta.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Mujer con índice de 28, hipertensión y prediabetes, sin éxito tras 6 meses de dieta y ejercicio.","p":"¿Es candidata a fármaco para obesidad?","o":["No, el índice es menor de 30","Sí, índice de 27 o más con comorbilidad","No, solo cirugía","Sí, pero solo orlistat por 1 mes"],"r":1,"e":"Los fármacos se indican con índice de 30 o más, o de 27 o más con comorbilidad, junto con el estilo de vida.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Paciente que toma orlistat y refiere evacuaciones grasosas y urgencia.","p":"¿Qué explica el efecto?","o":["Inhibe la lipasa intestinal","Aumenta la saciedad central","Es un diurético","Retrasa el vaciamiento gástrico"],"r":0,"e":"El orlistat inhibe la lipasa pancreática e intestinal; las grasas no absorbidas causan esteatorrea y déficit de vitaminas liposolubles.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"¿Qué dosis de orlistat recomienda la guía mexicana?","p":"Elige la opción correcta.","o":["60 mg al día","120 mg tres veces al día con las comidas","360 mg una vez al día","120 mg a la semana"],"r":1,"e":"Orlistat 120 mg con cada comida principal, tres veces al día.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Paciente que inició un fármaco para obesidad hace 12 semanas y solo bajó 2% del peso.","p":"¿Qué haces?","o":["Seguir 1 año más","Cambiar o suspender el fármaco","Duplicar la dosis indefinidamente","Referir a cirugía de inmediato"],"r":1,"e":"Si a las 12 semanas no se pierde al menos 5% del peso, el fármaco no es útil para ese paciente.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Mujer de 35 años con índice de 42 sin comorbilidades, sin éxito con dieta, ejercicio y fármacos.","p":"¿Qué sigue?","o":["Más dieta","Valoración para cirugía bariátrica","Lorcaserina","Hormona tiroidea"],"r":1,"e":"Índice de 40 o más (o 35 con comorbilidad grave) tras fallar el manejo médico es indicación de valorar cirugía bariátrica.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Paciente operado de bypass gástrico hace 3 años con anemia macrocítica y parestesias.","p":"¿Qué deficiencia sospechas?","o":["Vitamina C","Vitamina B12","Vitamina K","Zinc"],"r":1,"e":"Tras el bypass se pierde la absorción de vitamina B12 (y de hierro, calcio y vitamina D): requieren suplementos de por vida.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Qué fármaco para obesidad mencionado en la guía mexicana fue retirado del mercado en 2020?","p":"Elige la opción correcta.","o":["Orlistat","Liraglutida","Lorcaserina","Fentermina con topiramato"],"r":2,"e":"La lorcaserina se retiró en 2020 por mayor riesgo de cáncer.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"¿Qué agonista del péptido similar al glucagón tipo 1 se usa en obesidad a 3 mg diarios?","p":"Elige la opción correcta.","o":["Exenatida","Liraglutida","Dulaglutida","Sitagliptina"],"r":1,"e":"La liraglutida para obesidad se escala desde 0.6 mg hasta 3 mg diarios subcutáneos.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Paciente con obesidad, ronquido intenso, pausas respiratorias nocturnas y somnolencia de día.","p":"¿Qué sospechas?","o":["Narcolepsia","Apnea obstructiva del sueño","Hipotiroidismo","Depresión"],"r":1,"e":"La apnea obstructiva del sueño es una complicación frecuente de la obesidad; se confirma con polisomnografía.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"Paciente con obesidad central, estrías violáceas anchas, cara redonda y debilidad proximal.","p":"¿Qué causa secundaria descartas?","o":["Hipotiroidismo","Síndrome de Cushing","Hiperparatiroidismo","Acromegalia"],"r":1,"e":"Las estrías violáceas, la debilidad proximal y la obesidad central sugieren síndrome de Cushing.","f":"Manual CTO, Endocrinología, capítulo 7"},{"c":"¿Cuál es la meta inicial de pérdida de peso en un adulto con obesidad?","p":"Elige la opción correcta.","o":["1% en un año","5 a 10% en 6 meses","30% en 3 meses","Llegar al peso ideal en 1 mes"],"r":1,"e":"Bajar 5 a 10% en 6 meses es realista y ya mejora presión, glucosa y lípidos.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"¿Qué déficit calórico diario se recomienda para bajar de peso?","p":"Elige la opción correcta.","o":["100 kilocalorías","500 a 750 kilocalorías","2,000 kilocalorías","No se cuenta"],"r":1,"e":"Un déficit de 500 a 750 kilocalorías al día permite bajar alrededor de medio kilo por semana.","f":"Harrison, capítulo 407"},{"c":"¿Qué dieta recomienda la guía mexicana en obesidad con factores de riesgo cardiovascular?","p":"Elige la opción correcta.","o":["Dieta cetogénica estricta","Dieta mediterránea","Ayuno prolongado","Dieta líquida"],"r":1,"e":"La guía recomienda patrones saludables como la dieta mediterránea o la dieta para detener la hipertensión.","f":"Guía de Práctica Clínica IMSS-046-08"},{"c":"Mujer con índice de 26, sin comorbilidades.","p":"¿Qué le recomiendas?","o":["Fármaco","Consejería para no ganar peso y estilo de vida","Cirugía","Ningún seguimiento"],"r":1,"e":"En sobrepeso sin comorbilidad se da consejería, estilo de vida y vigilancia anual del peso.","f":"Guía de Práctica Clínica IMSS-046-08"}],"audio":[["¿Qué descartas antes de tratar una dislipidemia?","Causas secundarias: diabetes, hipotiroidismo, obesidad, alcohol, síndrome nefrótico y fármacos."],["¿Meta de colesterol de baja densidad en muy alto riesgo?","Menor de 70, según la guía mexicana."],["¿Qué es una estatina de alta intensidad?","Atorvastatina 40 a 80 o rosuvastatina 20 a 40 miligramos."],["¿Cuándo pides creatina fosfocinasa con estatina?","Solo si hay síntomas musculares o riesgo de miopatía."],["¿Qué agregas si no llegas a la meta con estatina?","Ezetimiba."],["Xantomas tendinosos y arco corneal en un joven: ¿qué es?","Hipercolesterolemia familiar. Estatina de alta intensidad desde el diagnóstico."],["¿Con qué triglicéridos hay riesgo de pancreatitis?","Desde 500 y sobre todo con más de 1,000. Se da fibrato y se suspende el alcohol."],["¿Qué combinación da rabdomiólisis?","Estatina con gemfibrozilo."],["¿Cómo clasificas la obesidad?","Grado 1 de 30 a 34.9, grado 2 de 35 a 39.9 y grado 3 de 40 o más."],["¿Criterios del síndrome metabólico?","Tres de: cintura alta, triglicéridos de 150, colesterol de alta densidad bajo, presión de 130 sobre 85 y glucosa de 100."],["¿Cuándo das fármacos para obesidad?","Índice de 30 o más, o 27 o más con comorbilidad."],["¿Cuándo cirugía bariátrica?","Índice de 40 o más, o 35 o más con comorbilidad grave, tras fallar el tratamiento médico."],["¿Efecto adverso típico del orlistat?","Esteatorrea y déficit de vitaminas liposolubles."],["¿Qué vigilas tras un bypass gástrico?","Vitamina B12, hierro, calcio y vitamina D."]],"profundizar":{"harrison":[[407,"Trastornos del metabolismo de las lipoproteínas"],[401,"Biopatología de la obesidad"],[402,"Valoración y tratamiento de la obesidad"]],"guias":[["Diagnóstico y tratamiento de dislipidemias (hipercolesterolemia) en el adulto, IMSS-233-09, actualización 2016 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/233GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/233GRR.pdf"],["Diagnóstico y tratamiento del sobrepeso y obesidad exógena, IMSS-046-08, actualización 2018 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/046GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/046GRR.pdf"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Endocrinología, capítulo 7, páginas 133 a 156 del archivo.","Guía de Práctica Clínica IMSS-233-09: Diagnóstico y tratamiento de dislipidemias (hipercolesterolemia) en el adulto, actualización 2016.","Guía de Práctica Clínica IMSS-046-08: Diagnóstico y tratamiento del sobrepeso y obesidad exógena, actualización 2018.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 401, 402 y 407."]},"enfermedades-infecciosas-6":{"titulo":"Infecciones respiratorias agudas altas en la consulta","enfoque":"Enfoque de consulta de primer nivel en niños y adultos: resfriado común, faringoamigdalitis, otitis media aguda y rinosinusitis aguda. Cuándo sí y cuándo no dar antibiótico, y cuándo referir. La neumonía se estudia en su propio tema.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La mayoría son **virales**: el **rinovirus** es la causa más frecuente del resfriado a cualquier edad.","El antibiótico se reserva para: **faringoamigdalitis estreptocócica**, **otitis media aguda** que lo amerite y **rinosinusitis bacteriana** con criterios.","El moco verde o amarillo **no** indica infección bacteriana.","En **menores de 6 años no** se usan antitusivos ni antigripales.","Buscar siempre **datos de alarma** y signos de neumonía: respiración rápida, tiraje, saturación baja."]},{"h":"Resfriado común (rinofaringitis)","li":["Rinorrea, congestión, estornudos, dolor faríngeo leve, tos y febrícula; en niños, irritabilidad.","Dura de 5 a 10 días y hasta **14 días**; la tos puede durar más.","Tratamiento **sintomático**: paracetamol (niños 10 a 15 mg por kilo cada 4 a 6 horas; máximo 75 mg por kilo al día) o ibuprofeno; líquidos; lavados nasales con solución salina; **miel en mayores de 1 año** para la tos.","La Guía de Práctica Clínica mexicana de niños **no recomienda** antitusivos, descongestionantes, bromuro de ipratropio, vitamina C ni zinc.","**No dar antibiótico**: no acorta el cuadro ni previene complicaciones."]},{"h":"Faringoamigdalitis: ¿viral o estreptocócica?","li":["Viral en la mayoría: hasta dos terceras partes en niños y alrededor de **90% en adultos**.","Sugiere virus: **tos, rinorrea, conjuntivitis, disfonía, aftas**, diarrea.","Sugiere **estreptococo beta hemolítico del grupo A**: inicio brusco, fiebre alta, **exudado amigdalino**, **adenopatía cervical anterior dolorosa**, **ausencia de tos**, petequias en paladar; edad típica de 5 a 15 años.","Escarlatina: además exantema áspero en papel de lija y lengua de fresa."]},{"h":"Criterios de Centor modificados por McIsaac","li":["Un punto por cada uno: fiebre mayor de 38 °C, ausencia de tos, adenopatía cervical anterior dolorosa, exudado o crecimiento amigdalino.","Edad: **3 a 14 años, más 1**; 15 a 44 años, 0; **45 años o más, menos 1**.","**0 a 1 punto**: probablemente viral; sin prueba ni antibiótico.","**2 a 3 puntos**: prueba rápida de antígeno o cultivo; antibiótico si es positivo.","**4 a 5 puntos**: alta probabilidad; prueba rápida si existe, o tratamiento empírico donde no hay prueba.","La prueba rápida tiene sensibilidad cercana a 75% y especificidad de 95%: en niños, si sale negativa, se confirma con cultivo."]},{"h":"Tratamiento de la faringoamigdalitis estreptocócica","li":["**Penicilina G benzatínica** intramuscular en **dosis única**: 1,200,000 unidades si pesa 27 kg o más; **600,000 unidades si pesa menos de 27 kg**. Útil si se duda del apego.","**Penicilina V** oral por **10 días** (adulto: 500 mg cada 6 horas o 1,000 mg cada 12 horas, según el Harrison).","**Amoxicilina** por **10 días**: niños 50 mg por kilo al día en una o dos tomas (máximo 1,000 mg al día); adultos 500 mg cada 12 horas o 1,000 mg al día.","Alergia leve a penicilina: cefalexina 10 días. Alergia grave: clindamicina 10 días, o macrólido (azitromicina, en niños 12 mg por kilo al día por 5 días, máximo 500 mg).","Siempre analgésico y antipirético; mejora en 48 a 72 horas. Si no mejora, revalorar para descartar absceso.","Tratar dentro de los primeros **9 días** previene la **fiebre reumática**, pero **no** la glomerulonefritis posestreptocócica."]},{"h":"Complicaciones de la faringoamigdalitis","li":["**Absceso periamigdalino**: odinofagia intensa unilateral, **trismus**, voz apagada ('de papa caliente'), sialorrea, **úvula desviada al lado contrario**. Referir para drenaje.","No supurativas: fiebre reumática (2 a 4 semanas después) y glomerulonefritis posestreptocócica (1 a 3 semanas después).","Mononucleosis infecciosa: adolescente con faringitis exudativa, **adenopatía cervical posterior**, esplenomegalia y fatiga; con **amoxicilina aparece exantema**. Evitar deportes de contacto por riesgo de rotura de bazo.","Referencia urgente: estridor, sialorrea, dificultad para respirar o tragar, sospecha de epiglotitis o absceso."]},{"h":"Otitis media aguda","li":["Pico entre los **6 meses y 3 años**. Gérmenes: **neumococo**, Haemophilus influenzae no tipificable, Moraxella catarrhalis y estreptococo del grupo A.","Diagnóstico: inicio agudo con **membrana timpánica abombada**, que es el hallazgo clave, o **otorrea** de inicio reciente; otalgia, fiebre e irritabilidad. El tímpano solo enrojecido por llanto no basta.","**Antibiótico de inmediato**: otorrea, síntomas graves (otalgia de más de 48 horas o fiebre de 39 °C o más), **menores de 2 años con otitis bilateral** y menores de 6 meses.","Observación vigilada de 48 a 72 horas posible en niños de 6 a 23 meses con otitis unilateral no grave y en mayores de 2 años no graves, si se garantiza la revaloración.","Elección: **amoxicilina a dosis alta, 80 a 90 mg por kilo al día** en dos tomas (máximo 3 g al día).","Amoxicilina con ácido clavulánico si recibió amoxicilina en los últimos 30 días, si hay conjuntivitis purulenta (sugiere Haemophilus) o si no mejora en 48 a 72 horas; alternativa: ceftriaxona intramuscular por 3 días.","Duración: **10 días en menores de 2 años** o síntomas graves; 5 a 7 días de 2 a 5 años; 5 días en 6 años o más con cuadro leve o moderado.","Complicación a referir: **mastoiditis** (dolor, eritema y despegamiento del pabellón auricular)."]},{"h":"Rinosinusitis aguda","li":["Casi siempre viral. En adultos se afecta más el **seno maxilar**; en niños, el **etmoidal**.","Clínica: congestión, rinorrea purulenta, dolor facial que **empeora al agachar la cabeza**, dolor a la palpación de senos, hiposmia.","Sospechar bacteriana (cualquiera de tres): **síntomas por 10 días o más sin mejoría**; **inicio grave** (fiebre de 39 °C o más con rinorrea purulenta o dolor facial por 3 a 4 días); o **empeoramiento después de una mejoría inicial** (doble empeoramiento).","Gérmenes: neumococo, Haemophilus influenzae y Moraxella catarrhalis, igual que la otitis.","Adultos: **amoxicilina con ácido clavulánico 875/125 mg cada 12 horas por 5 a 7 días**; alternativa amoxicilina 875 mg cada 12 horas. Sintomático: lavados nasales salinos, analgésico, esteroide intranasal.","No se piden radiografías de rutina: el diagnóstico es clínico.","Referencia urgente: **edema o eritema periorbitario**, alteraciones visuales, cefalea intensa, signos meníngeos o alteración del estado de alerta."]},{"h":"Influenza","li":["Inicio brusco con fiebre alta, mialgias, cefalea y postración.","**Oseltamivir** en pacientes de alto riesgo (menores de 2 años, mayores de 65, embarazadas, enfermedades crónicas) o graves, de preferencia en las primeras 48 horas: adulto 75 mg cada 12 horas por 5 días; en niños, dosis por peso."]},{"h":"Datos de alarma y cuándo referir","li":["Respiración rápida para la edad (Organización Mundial de la Salud): **60 o más por minuto en menores de 2 meses, 50 o más de 2 a 11 meses, 40 o más de 1 a 4 años**; tiraje, quejido, cianosis o saturación baja: sospecha de neumonía.","Estridor en reposo, sialorrea, dificultad para tragar o respirar.","Alteraciones neurológicas, vómito persistente, disminución de la orina, exantema petequial o purpúrico.","Indicar a los padres regresar si: la fiebre dura más de 3 días, empeora o aparecen síntomas nuevos después de 3 a 5 días, o no mejora en 7 a 10 días.","Fiebre mayor de 39 °C, dolor torácico o síntomas por más de 14 días en adultos."]}],"perlas":["Resfriado y bronquitis aguda: **sin antibiótico**.","Centor de 0 a 1: **ni prueba ni antibiótico**.","Faringitis estreptocócica: **penicilina benzatínica dosis única** o penicilina V o amoxicilina por **10 días**.","Penicilina benzatínica: **600,000 unidades si pesa menos de 27 kg**; 1,200,000 si pesa más.","Exantema tras amoxicilina en adolescente con faringitis: **mononucleosis**.","Otitis media: el hallazgo clave es el **tímpano abombado**; amoxicilina a **80 a 90 mg por kilo al día**.","Sinusitis bacteriana: **10 días sin mejoría, inicio grave o doble empeoramiento**."],"mexico":["La Guía de Práctica Clínica IMSS-073-08 de faringoamigdalitis es de 2008 y propone penicilina compuesta seguida de penicilina procaínica, y un esquema de erradicación con penicilina benzatínica cada 21 días por 3 meses. El CTO y el Harrison recomiendan **penicilina benzatínica en dosis única o penicilina V o amoxicilina por 10 días**: usa estos esquemas, que son los actuales.","La misma guía mexicana propone eritromicina o trimetoprima con sulfametoxazol en alérgicos; el trimetoprima con sulfametoxazol **no** es adecuado para el estreptococo del grupo A. Usa cefalexina, clindamicina o un macrólido.","La Guía IMSS-062-08 (actualización 2016) de niños de 3 meses a 18 años recomienda paracetamol para la fiebre y **no usar** antitusivos, descongestionantes, bromuro de ipratropio, vitamina C ni zinc; antibiótico inmediato en otitis bilateral en menores de 2 años y en otitis con otorrea.","El CTO desaconseja macrólidos en España por resistencias del estreptococo; en México se usan como alternativa en alérgicos."],"preguntas":[{"c":"Niña de 4 años con 3 días de rinorrea hialina, estornudos, tos y temperatura de 37.8 °C. Come bien, frecuencia respiratoria de 28 por minuto, sin tiraje.","p":"¿Cuál es el manejo adecuado?","o":["Amoxicilina por 7 días","Paracetamol, líquidos y lavados nasales; sin antibiótico","Antitusivo con codeína","Antihistamínico con descongestionante"],"r":1,"e":"Es un resfriado común, de origen viral. El manejo es sintomático; en menores de 6 años no se usan antitusivos ni antigripales.","f":"Guía IMSS-062-08, actualización 2016; Harrison, 21.ª edición, capítulo 35."},{"c":"Madre de un niño de 3 años con resfriado de 5 días pide antibiótico porque el moco se volvió verde.","p":"¿Qué le explicas?","o":["El moco verde confirma infección bacteriana","El color del moco no distingue entre infección viral y bacteriana; no requiere antibiótico","Hay que iniciar amoxicilina con ácido clavulánico","Hay que tomar radiografía de senos"],"r":1,"e":"El moco purulento es parte de la evolución normal del resfriado viral. Se sospecha sinusitis bacteriana solo con más de 10 días sin mejoría, inicio grave o doble empeoramiento.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Lactante de 8 meses con resfriado.","p":"¿Qué remedio está contraindicado por su edad?","o":["Paracetamol","Miel para la tos","Lavados nasales con solución salina","Aspiración de secreciones con perilla"],"r":1,"e":"La miel no se da en menores de 1 año por riesgo de botulismo infantil; en mayores de 1 año puede aliviar la tos.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 9 años con fiebre de 39 °C, odinofagia de inicio brusco, amígdalas con exudado, adenopatías cervicales anteriores dolorosas y sin tos.","p":"¿Cuántos puntos de Centor modificados por McIsaac tiene y qué indica?","o":["2 puntos, probable virus","5 puntos, alta probabilidad de estreptococo","3 puntos, solo tratamiento sintomático","1 punto, sin estudios"],"r":1,"e":"Fiebre, exudado, adenopatía anterior dolorosa y ausencia de tos suman 4, más 1 por la edad de 3 a 14 años: 5 puntos, alta probabilidad de estreptococo del grupo A.","f":"Guía IMSS-062-08; Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 30 años con odinofagia, rinorrea, tos, disfonía y conjuntivitis. Faringe eritematosa sin exudado.","p":"¿Qué conducta es adecuada?","o":["Penicilina benzatínica","Tratamiento sintomático; probable faringitis viral","Amoxicilina por 10 días","Cultivo faríngeo obligatorio"],"r":1,"e":"Tos, rinorrea, conjuntivitis y disfonía orientan a etiología viral. Con Centor bajo no se requiere prueba ni antibiótico.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6, tabla 6.1."},{"c":"Niño de 7 años con faringoamigdalitis y prueba rápida de estreptococo negativa, pero con 4 criterios clínicos.","p":"¿Cuál es el siguiente paso?","o":["Descartar estreptococo","Tomar cultivo faríngeo","Repetir la prueba rápida en una semana","Iniciar azitromicina"],"r":1,"e":"La prueba rápida tiene sensibilidad cercana a 75%; en niños, un resultado negativo se confirma con cultivo, que es el estándar de oro.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 6 años y 20 kg con faringoamigdalitis estreptocócica confirmada. La madre teme que no le dé completo el tratamiento oral.","p":"¿Qué tratamiento eliges?","o":["Penicilina G benzatínica 1,200,000 unidades intramuscular, dosis única","Penicilina G benzatínica 600,000 unidades intramuscular, dosis única","Amoxicilina por 3 días","Ceftriaxona por 10 días"],"r":1,"e":"La penicilina benzatínica en dosis única asegura el tratamiento: 600,000 unidades si pesa menos de 27 kg y 1,200,000 si pesa 27 kg o más.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6; esquema de dosificación por peso de la Asociación Americana del Corazón."},{"c":"Adolescente de 16 años con faringoamigdalitis estreptocócica confirmada, sin alergias.","p":"¿Cuál es la duración del tratamiento con penicilina V oral?","o":["3 días","5 días","10 días","21 días"],"r":2,"e":"La faringitis estreptocócica requiere 10 días de penicilina V o amoxicilina; los esquemas cortos fallan más.","f":"Harrison, 21.ª edición, capítulo 35, cuadro 35-5."},{"c":"Niño de 5 años y 18 kg con faringitis estreptocócica. Se elige amoxicilina oral.","p":"¿Cuál es la dosis adecuada?","o":["50 mg por kilo al día por 10 días, máximo 1,000 mg al día","90 mg por kilo al día por 3 días","20 mg por kilo al día por 5 días","1 g cada 8 horas por 10 días"],"r":0,"e":"Para faringitis estreptocócica en niños: amoxicilina 50 mg por kilo al día en una o dos tomas por 10 días, máximo 1,000 mg al día. La dosis de 80 a 90 mg por kilo es para otitis media.","f":"Sociedad de Enfermedades Infecciosas de América, guía de faringitis estreptocócica; Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 25 años con faringitis estreptocócica y antecedente de anafilaxia con penicilina.","p":"¿Qué antibiótico es apropiado?","o":["Cefalexina","Clindamicina","Amoxicilina con ácido clavulánico","Trimetoprima con sulfametoxazol"],"r":1,"e":"Con alergia grave a penicilina se evitan los betalactámicos, incluidas las cefalosporinas. Opciones: clindamicina por 10 días o un macrólido. El trimetoprima con sulfametoxazol no erradica bien al estreptococo del grupo A.","f":"Harrison, 21.ª edición, capítulo 35, cuadro 35-5."},{"c":"Adolescente de 17 años con faringitis exudativa, fiebre, fatiga intensa, adenopatías cervicales posteriores y esplenomegalia. Le dieron amoxicilina y presentó exantema maculopapular.","p":"¿Cuál es el diagnóstico más probable?","o":["Alergia verdadera a la penicilina","Mononucleosis infecciosa por virus de Epstein-Barr","Escarlatina","Síndrome de Stevens-Johnson"],"r":1,"e":"La mononucleosis da faringitis con adenopatía posterior, esplenomegalia y fatiga; la amoxicilina desencadena un exantema característico que no indica alergia permanente.","f":"Manual CTO, Otorrinolaringología, capítulo 5; Harrison, 21.ª edición, capítulo 35."},{"c":"Paciente con mononucleosis infecciosa confirmada que juega fútbol americano.","p":"¿Qué recomendación es importante?","o":["Puede jugar en cuanto baje la fiebre","Evitar deportes de contacto por riesgo de rotura esplénica","Iniciar aciclovir","Tomar amoxicilina profiláctica"],"r":1,"e":"La esplenomegalia de la mononucleosis aumenta el riesgo de rotura de bazo con traumatismos; se evitan deportes de contacto por varias semanas.","f":"Harrison, 21.ª edición, capítulo 194."},{"c":"Hombre de 24 años con 5 días de faringitis que empeoró: odinofagia intensa del lado izquierdo, trismus, voz apagada y úvula desviada a la derecha.","p":"¿Cuál es el diagnóstico y la conducta?","o":["Faringitis viral; sintomáticos","Absceso periamigdalino; referir para drenaje y antibiótico","Mononucleosis; reposo","Epiglotitis; alta con antibiótico oral"],"r":1,"e":"Trismus, voz de papa caliente y desviación de la úvula al lado contrario son típicos del absceso periamigdalino, que requiere drenaje.","f":"Guía IMSS-073-08; Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 8 años con faringitis estreptocócica no tratada hace 3 semanas. Hoy presenta fiebre, artritis migratoria de rodillas y tobillos y un soplo nuevo.","p":"¿Qué complicación presenta?","o":["Glomerulonefritis posestreptocócica","Fiebre reumática","Artritis séptica","Púrpura de Henoch-Schönlein"],"r":1,"e":"La fiebre reumática aparece 2 a 4 semanas después de una faringitis estreptocócica; se previene si el antibiótico se da en los primeros 9 días.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Sobre la glomerulonefritis posestreptocócica.","p":"¿Qué afirmación es correcta?","o":["Se previene con el tratamiento antibiótico de la faringitis","No se previene con el tratamiento antibiótico de la faringitis","Solo ocurre después de infecciones de piel","Aparece en las primeras 24 horas"],"r":1,"e":"A diferencia de la fiebre reumática, la glomerulonefritis posestreptocócica no se previene con el tratamiento antibiótico de la faringitis.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 7 años con faringitis, fiebre, lengua de fresa y exantema áspero que inicia en cuello y pliegues.","p":"¿Cuál es el diagnóstico?","o":["Sarampión","Escarlatina","Exantema súbito","Enfermedad de Kawasaki confirmada"],"r":1,"e":"La escarlatina es una faringoamigdalitis por estreptococo del grupo A con exantema en papel de lija por toxinas; se trata igual que la faringitis estreptocócica.","f":"Manual CTO, Enfermedades Infecciosas, capítulo 6."},{"c":"Niño de 18 meses con fiebre de 38.5 °C e irritabilidad. En la otoscopia ambos tímpanos están abombados, opacos y eritematosos.","p":"¿Cuál es la conducta?","o":["Observación vigilada por 72 horas","Amoxicilina a dosis alta de inmediato","Gotas óticas con antibiótico","Referir a otorrinolaringología"],"r":1,"e":"En menores de 2 años con otitis media bilateral se indica antibiótico de inmediato; la primera elección es amoxicilina a 80 a 90 mg por kilo al día.","f":"Guía IMSS-062-08; Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 3 años con otitis media aguda unilateral, otalgia leve de 24 horas y temperatura de 38 °C. Los padres pueden regresar en 48 horas.","p":"¿Qué opción es válida?","o":["Observación vigilada de 48 a 72 horas con analgésico","Ceftriaxona intramuscular","Timpanocentesis","Amoxicilina con ácido clavulánico por 14 días"],"r":0,"e":"En mayores de 2 años con otitis no grave es válido observar 48 a 72 horas con analgesia, si se garantiza la revaloración; si no mejora, se inicia antibiótico.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niña de 2 años y 12 kg con otitis media aguda que amerita antibiótico; no recibió antibióticos el último mes.","p":"¿Qué dosis de amoxicilina indicas?","o":["Alrededor de 1,000 a 1,080 mg al día divididos cada 12 horas","250 mg al día","3,000 mg al día","500 mg una vez a la semana"],"r":0,"e":"Amoxicilina a dosis alta de 80 a 90 mg por kilo al día: con 12 kg son 960 a 1,080 mg al día, divididos cada 12 horas.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 4 años que tomó amoxicilina hace 3 semanas y hoy presenta otitis media aguda con conjuntivitis purulenta.","p":"¿Qué antibiótico eliges?","o":["Amoxicilina a dosis habitual","Amoxicilina con ácido clavulánico","Azitromicina por 1 día","Trimetoprima con sulfametoxazol"],"r":1,"e":"Si recibió amoxicilina en los últimos 30 días o hay conjuntivitis purulenta (sugiere Haemophilus influenzae productor de betalactamasa), se usa amoxicilina con ácido clavulánico.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño con otitis media aguda que tras 72 horas de amoxicilina persiste con fiebre y otalgia.","p":"¿Cuál es el siguiente paso?","o":["Continuar igual otros 7 días","Cambiar a amoxicilina con ácido clavulánico o ceftriaxona intramuscular por 3 días","Suspender antibiótico","Agregar descongestionante"],"r":1,"e":"La falta de mejoría en 48 a 72 horas obliga a cambiar a amoxicilina con clavulánico, cefalosporina de segunda o tercera generación o ceftriaxona intramuscular por 3 días.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 3 años con otitis media que ahora presenta fiebre, dolor y eritema retroauricular con pabellón auricular desplazado hacia adelante.","p":"¿Qué sospechas?","o":["Otitis externa","Mastoiditis aguda","Adenitis retroauricular por piojos","Celulitis facial"],"r":1,"e":"La mastoiditis es una complicación de la otitis media; da dolor, edema y eritema retroauricular con despegamiento del pabellón. Requiere referencia urgente.","f":"Manual CTO, Otorrinolaringología, capítulo 2."},{"c":"Sobre la otitis media aguda.","p":"¿Cuál es el germen más frecuente?","o":["Staphylococcus aureus","Streptococcus pneumoniae","Pseudomonas aeruginosa","Moraxella catarrhalis"],"r":1,"e":"El neumococo es el más frecuente, seguido de Haemophilus influenzae y Moraxella catarrhalis; los mismos de la sinusitis. Pseudomonas es típico de la otitis externa.","f":"Manual CTO, Otorrinolaringología, capítulo 2."},{"c":"Adulto de 35 años con rinorrea purulenta, congestión y dolor facial desde hace 4 días, sin fiebre, mejorando poco a poco.","p":"¿Qué indicas?","o":["Amoxicilina con ácido clavulánico por 10 días","Tratamiento sintomático: lavados salinos, analgésico y esteroide intranasal","Tomografía de senos","Levofloxacino"],"r":1,"e":"Es una rinosinusitis de pocos días, probablemente viral. El antibiótico se reserva para más de 10 días sin mejoría, inicio grave o doble empeoramiento.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Mujer de 40 años con resfriado que mejoraba, pero al día 7 empeora con fiebre de 38.8 °C, dolor maxilar y rinorrea purulenta.","p":"¿Qué conducta es adecuada?","o":["Sintomáticos y esperar 2 semanas más","Antibiótico: amoxicilina con ácido clavulánico 875/125 mg cada 12 horas","Radiografía de Waters antes de decidir","Referir a otorrinolaringología"],"r":1,"e":"El empeoramiento después de una mejoría inicial (doble empeoramiento) es criterio de sinusitis bacteriana; la elección es amoxicilina con ácido clavulánico por 5 a 7 días.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Niño de 6 años con sinusitis que ahora presenta edema y eritema del párpado, dolor al mover el ojo y visión doble.","p":"¿Cuál es la conducta?","o":["Antibiótico oral y cita en una semana","Referencia urgente por sospecha de complicación orbitaria","Compresas frías","Antihistamínico"],"r":1,"e":"Edema periorbitario, dolor con movimientos oculares o alteraciones visuales sugieren celulitis orbitaria, complicación grave que requiere referencia urgente.","f":"Harrison, 21.ª edición, capítulo 35."},{"c":"Sobre la rinosinusitis aguda.","p":"¿Qué seno se afecta con más frecuencia en niños pequeños?","o":["Frontal","Etmoidal","Esfenoidal","Maxilar"],"r":1,"e":"En niños el seno etmoidal es el más afectado porque es el primero en desarrollarse; en adultos, el maxilar.","f":"Manual CTO, Otorrinolaringología, capítulo 3."},{"c":"Lactante de 10 meses con tos, fiebre y frecuencia respiratoria de 56 por minuto con tiraje intercostal.","p":"¿Qué interpretas?","o":["Resfriado común","Datos de neumonía; requiere valoración urgente","Faringitis viral","Otitis media"],"r":1,"e":"De 2 a 11 meses, 50 o más respiraciones por minuto es taquipnea; con tiraje sugiere neumonía grave y requiere manejo urgente.","f":"Organización Mundial de la Salud, Atención Integrada a las Enfermedades Prevalentes de la Infancia; Guía IMSS-062-08."},{"c":"Mujer embarazada de 28 semanas con fiebre de 39 °C, mialgias y tos de 24 horas, en temporada de influenza.","p":"¿Qué indicas?","o":["Solo paracetamol","Oseltamivir 75 mg cada 12 horas por 5 días","Amoxicilina por 7 días","Esperar el resultado de la prueba antes de cualquier tratamiento"],"r":1,"e":"La embarazada es de alto riesgo para complicaciones de influenza; se indica oseltamivir lo antes posible, de preferencia en las primeras 48 horas, sin esperar la prueba.","f":"Ficha de oseltamivir de GCHE2 (etiqueta oficial y Centros para el Control y la Prevención de Enfermedades)."},{"c":"Padre de un niño de 2 años con resfriado pregunta cuándo regresar.","p":"¿Qué le indicas?","o":["Solo si la fiebre dura más de 10 días","Si la fiebre dura más de 3 días, empeora tras 3 a 5 días o no mejora en 7 a 10 días, o si aparece algún dato de alarma","Nunca, se cura solo","Cada 24 horas para revisión"],"r":1,"e":"La guía mexicana de niños indica revaloración con fiebre de más de 3 días, empeoramiento o síntomas nuevos a los 3 a 5 días, falta de mejoría a los 7 a 10 días, o cualquier dato de alarma.","f":"Guía IMSS-062-08, actualización 2016."}],"audio":[["¿Cuál es la causa más frecuente del resfriado común?","El rinovirus, a cualquier edad."],["¿Se da antibiótico en el resfriado?","No. Tratamiento sintomático; y en menores de 6 años, sin antitusivos ni antigripales."],["¿Cuáles son los criterios de Centor?","Fiebre, ausencia de tos, adenopatía cervical anterior dolorosa y exudado amigdalino. McIsaac suma 1 de 3 a 14 años y resta 1 de 45 en adelante."],["¿Qué hago con Centor de 0 a 1?","Nada de prueba ni antibiótico: probablemente viral."],["¿Cuál es el tratamiento de la faringitis estreptocócica?","Penicilina benzatínica dosis única, o penicilina V o amoxicilina por 10 días."],["¿Qué dosis de penicilina benzatínica?","600 mil unidades si pesa menos de 27 kilos; un millón 200 mil si pesa más."],["¿Qué previene el tratamiento antibiótico de la faringitis?","La fiebre reumática, si se inicia en los primeros 9 días; no previene la glomerulonefritis."],["¿Qué sospecho con exantema tras amoxicilina en un adolescente con faringitis?","Mononucleosis infecciosa por virus de Epstein-Barr."],["¿Cuál es el hallazgo clave de la otitis media aguda?","La membrana timpánica abombada."],["¿Cuál es el tratamiento de la otitis media?","Amoxicilina a dosis alta, 80 a 90 miligramos por kilo al día en dos tomas; con clavulánico si tomó amoxicilina el último mes o hay conjuntivitis purulenta."],["¿Cuándo es bacteriana la sinusitis?","Con 10 días o más sin mejoría, inicio grave con fiebre de 39 o más, o empeoramiento tras una mejoría inicial."],["¿Qué frecuencia respiratoria es taquipnea?","60 o más en menores de 2 meses, 50 o más de 2 a 11 meses y 40 o más de 1 a 4 años."]],"profundizar":{"harrison":[[35,"Síntomas de vías respiratorias altas: otalgia, síntomas de senos paranasales y faringodinia"]],"guias":[["Diagnóstico y manejo de la infección aguda de vías aéreas superiores en pacientes mayores de 3 meses hasta 18 años de edad, IMSS-062-08, actualización 2016","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/062GER.pdf"],["Diagnóstico y tratamiento de faringoamigdalitis aguda, IMSS-073-08, 2008 (sin enlace oficial por ahora; ver diferencias)",""]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Enfermedades Infecciosas, capítulo 6, páginas 50 a 52 del archivo.","Manual CTO, Otorrinolaringología, capítulos 2 (otitis media aguda), 3 (rinosinusitis) y 5 (faringe).","Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 35 y cuadro 35-5.","Guía de Práctica Clínica IMSS-062-08, actualización 2016.","Guía de Práctica Clínica IMSS-073-08 (2008).","Fichas verificadas de paracetamol, azitromicina y oseltamivir en GCHE2 (etiquetas oficiales)."]},"enfermedades-infecciosas-8":{"titulo":"Diarrea aguda en la consulta","enfoque":"Enfoque de consulta de primer nivel: hidratación en niños y adultos, cuándo dar antibiótico, intoxicación alimentaria, disentería, Clostridioides difficile y datos de alarma.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La mayoría es **viral y se cura sola** en 5 a 7 días. Lo que salva vidas es la **hidratación**.","Niños: **rotavirus** es la causa más frecuente. Adultos y brotes: **norovirus**. Diarrea del viajero: **Escherichia coli enterotoxigénica**.","Se usa **suero oral de baja osmolaridad**; en niños se agrega **zinc** por 10 a 14 días y se sigue alimentando.","**No** dar antibiótico de rutina. Sí en disentería con fiebre, cólera, amebiasis o giardiasis, sepsis, inmunosupresión y algunos casos de Salmonella.","**No** usar loperamida si hay fiebre o sangre en las evacuaciones, ni en niños."]},{"h":"Tipos de diarrea","li":["**Acuosa**: sin sangre ni moco; por virus o toxinas (cólera, Escherichia coli enterotoxigénica).","**Disentérica**: sangre, moco, fiebre, cólico y **tenesmo**; por invasión o citotoxinas (Shigella, Campylobacter, Salmonella, Escherichia coli enterohemorrágica, amiba).","**Persistente**: más de 14 días. **Crónica**: más de 4 semanas; se estudia como otro tema."]},{"h":"La pista del tiempo de incubación","li":["**Menos de 6 horas**, con **vómito** predominante: toxina preformada de **Staphylococcus aureus** (pasteles, cremas, mayonesa) o **Bacillus cereus** (arroz frito).","**8 a 16 horas**, diarrea acuosa y cólico: Clostridium perfringens o Bacillus cereus (carne, verduras).","**16 a 72 horas**, diarrea acuosa: norovirus, Escherichia coli enterotoxigénica, Vibrio cholerae (heces en **agua de arroz**).","**48 a 72 horas**, disentería: Escherichia coli enterohemorrágica o Shigella.","**3 a 5 días**, fiebre con o sin sangre: Campylobacter, Salmonella, Shigella, Escherichia coli enteroinvasiva."]},{"h":"Deshidratación en el niño","li":["**Sin deshidratación**: alerta, ojos normales, bebe normal, pliegue cutáneo regresa rápido.","**Con deshidratación**: inquieto o irritable, ojos hundidos, **bebe con avidez**, boca seca, pliegue que regresa lento, llenado capilar lento.","**Grave o choque**: letárgico o inconsciente, no puede beber, pulso débil, llenado capilar mayor de 2 segundos, pliegue muy lento.","Lo más fiable es el cambio de peso: el porcentaje perdido equivale al grado de deshidratación."]},{"h":"Planes de hidratación (México)","li":["**Plan A** (sin deshidratación, en casa): más líquidos, seguir la lactancia y la comida, y suero oral **después de cada evacuación**: menores de 1 año 75 mL (media taza), mayores 150 mL (una taza). Enseñar datos de alarma.","**Plan B** (deshidratación): suero oral **100 mL por kilo en 4 horas**, en tomas cada 30 minutos; si vomita, esperar 10 minutos y seguir más despacio. Revalorar y pasar a plan A.","**Plan C** (choque o deshidratación grave): **solución Hartmann o salina al 0.9% intravenosa: 50 mL por kilo la primera hora, 25 la segunda y 25 la tercera**, y referir.","Zinc: **10 mg al día en menores de 6 meses y 20 mg en mayores**, por 10 a 14 días."]},{"h":"Lo que no se da en niños","li":["**Loperamida**: contraindicada en niños.","Antibióticos de rutina, refrescos, jugos azucarados o bebidas deportivas (osmolaridad alta).","Metoclopramida de rutina. Si el vómito impide la hidratación oral, el ondansetrón puede ayudar."]},{"h":"Adulto: manejo","li":["Hidratación oral con suero; dieta normal según tolerancia.","**Loperamida** solo en diarrea acuosa sin fiebre ni sangre: 4 mg al inicio y 2 mg después de cada evacuación, máximo 16 mg al día.","Coprocultivo o estudios solo si hay fiebre alta, sangre, deshidratación grave, inmunosupresión, más de 7 días, brote o uso reciente de antibióticos."]},{"h":"Cuándo dar antibiótico","li":["Disentería con fiebre o afectación general, más de 6 a 8 evacuaciones al día, edades extremas, inmunosupresión o prótesis vasculares, diarrea del viajero moderada a grave.","Empírico en adultos: **azitromicina 500 mg al día por 3 días** (o 1 g dosis única) o ciprofloxacino 500 mg cada 12 horas por 3 días. Para **Campylobacter**, macrólido (alta resistencia a quinolonas).","**Salmonella** no tifoídica en sano: **no tratar** (prolonga el estado de portador). Sí en menores de 6 meses (guía mexicana), adultos mayores, inmunosuprimidos o prótesis vasculares.","**Escherichia coli enterohemorrágica**: **no dar antibiótico** porque aumenta el riesgo de síndrome hemolítico urémico.","**Amebiasis disentérica**: metronidazol 750 mg cada 8 horas por 7 a 10 días más un amebicida luminal. **Giardiasis**: metronidazol o tinidazol 2 g dosis única. **Cólera**: doxiciclina 300 mg o azitromicina 1 g dosis única."]},{"h":"Clostridioides difficile","li":["Pensarlo con diarrea **durante o después de antibióticos** (sobre todo clindamicina, cefalosporinas y quinolonas) o en hospitalizados; los inhibidores de la bomba de protones aumentan el riesgo.","Diagnóstico: glutamato deshidrogenasa como tamiz y **toxinas A y B** en heces. No repetir para comprobar curación.","Tratamiento de elección: **vancomicina oral 125 mg cada 6 horas por 10 días** (o fidaxomicina). Suspender el antibiótico causal. Lavado de manos con **agua y jabón** (el alcohol no mata las esporas)."]},{"h":"Complicaciones que se preguntan","li":["**Síndrome hemolítico urémico**: Escherichia coli O157:H7 y Shigella dysenteriae tipo 1 (anemia hemolítica, plaquetas bajas y falla renal).","**Guillain-Barré**: Campylobacter jejuni.","**Artritis reactiva**: Salmonella, Shigella, Yersinia y Campylobacter (sobre todo con HLA-B27)."]},{"h":"Datos de alarma y referencia","li":["Niño: no puede beber, vomita todo, letargia, convulsiones, sangre en evacuaciones, fiebre alta, más de 10 evacuaciones al día, deshidratación que persiste más de 24 horas o anuria de 12 horas.","Hospitalizar: choque, deshidratación grave (más de 9% del peso), lactantes menores de 6 meses con muchas evacuaciones o vómitos, alteraciones neurológicas.","Adulto: deshidratación grave, sangre con fiebre alta, adulto mayor o inmunosuprimido con mal estado general, dolor abdominal intenso."]}],"perlas":["Vómito a las pocas horas de comer pasteles o mayonesa: **Staphylococcus aureus**; con arroz frito: **Bacillus cereus**.","Causa más frecuente de diarrea del viajero: **Escherichia coli enterotoxigénica**.","Diarrea con sangre y luego anemia hemolítica, plaquetas bajas y falla renal: **síndrome hemolítico urémico** por Escherichia coli O157:H7.","Diarrea por Campylobacter y después parálisis ascendente: **Guillain-Barré**.","Clostridioides difficile: **vancomicina oral**; lavado con agua y jabón.","Plan C en México: **50, 25 y 25 mL por kilo** en 3 horas."],"mexico":["La Guía de Práctica Clínica IMSS-156-08 (niños de 2 meses a 5 años) recomienda suero oral de baja osmolaridad, zinc de 10 a 20 mg por 10 a 14 días, **no** usar loperamida ni antibióticos de rutina, y antibiótico en sepsis, shigelosis o amebiasis disentéricas, cólera, giardiasis, Clostridioides difficile y Salmonella en menores de 6 meses o inmunocomprometidos.","Los planes A, B y C mexicanos difieren un poco de los de la Organización Mundial de la Salud: el Plan C mexicano da 100 mL por kilo en 3 horas (50, 25 y 25), y la Organización Mundial de la Salud lo reparte en 30 y 70 mL por kilo en 3 a 6 horas según la edad.","Para adultos rige la Guía de Práctica Clínica GPC-SS-106-20 (prevención, diagnóstico y tratamiento de diarrea aguda en el adulto en primer nivel, 2020).","El CTO menciona fluoroquinolonas o trimetoprima con sulfametoxazol como empírico; por resistencias, Harrison prefiere azitromicina en disentería y diarrea del viajero."],"preguntas":[{"c":"Cuatro personas de una fiesta presentan vómito intenso y cólico 3 horas después de comer pasteles con crema. Sin fiebre.","p":"¿Cuál es el agente más probable?","o":["Salmonella","Staphylococcus aureus","Shigella","Vibrio cholerae"],"r":1,"e":"El vómito en menos de 6 horas indica toxina preformada; los pasteles y cremas son típicos de Staphylococcus aureus.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Paciente con vómito 2 horas después de comer arroz frito recalentado.","p":"¿Cuál es el agente?","o":["Bacillus cereus","Clostridium perfringens","Campylobacter jejuni","Norovirus"],"r":0,"e":"La forma emética de Bacillus cereus se asocia al arroz frito; su toxina es preformada.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Turista que viajó a una zona costera presenta diarrea acuosa sin sangre al tercer día de su viaje.","p":"¿Cuál es el agente más frecuente?","o":["Escherichia coli enterotoxigénica","Escherichia coli enterohemorrágica","Entamoeba histolytica","Clostridioides difficile"],"r":0,"e":"Escherichia coli enterotoxigénica es la causa más frecuente de diarrea del viajero.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Niño de 4 años con diarrea con sangre; 7 días después aparece palidez, petequias y oliguria. Hemoglobina 7 g/dL, plaquetas 40,000 y creatinina elevada.","p":"¿Qué complicación presenta y qué germen la causa?","o":["Púrpura de Henoch-Schönlein por estreptococo","Síndrome hemolítico urémico por Escherichia coli O157:H7","Coagulación intravascular por Salmonella","Glomerulonefritis por rotavirus"],"r":1,"e":"Anemia hemolítica, trombocitopenia y falla renal después de diarrea sanguinolenta son el síndrome hemolítico urémico, típico de Escherichia coli productora de toxina Shiga.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"En el caso anterior de diarrea por Escherichia coli O157:H7 sin complicaciones aún.","p":"¿Qué está contraindicado?","o":["Suero oral","Antibióticos","Vigilar la orina","Biometría hemática"],"r":1,"e":"Los antibióticos aumentan la liberación de toxina Shiga y el riesgo de síndrome hemolítico urémico.","f":"Harrison, capítulo 133"},{"c":"Hombre de 30 años con debilidad ascendente en piernas 2 semanas después de una diarrea con fiebre.","p":"¿Qué germen se asocia?","o":["Campylobacter jejuni","Vibrio cholerae","Rotavirus","Bacillus cereus"],"r":0,"e":"Campylobacter jejuni es el antecedente infeccioso clásico del síndrome de Guillain-Barré.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Mujer de 68 años hospitalizada que recibió clindamicina. Al octavo día presenta diarrea acuosa, fiebre y leucocitosis.","p":"¿Cuál es el tratamiento de elección?","o":["Metronidazol oral","Vancomicina oral","Loperamida","Ciprofloxacino"],"r":1,"e":"Hoy se prefiere vancomicina oral en el primer episodio de Clostridioides difficile, sin importar la gravedad; se suspende el antibiótico causal.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Para prevenir el contagio de Clostridioides difficile en el hospital.","p":"¿Qué medida es la correcta?","o":["Gel con alcohol","Lavado de manos con agua y jabón","Antibiótico profiláctico al personal","Inhibidor de la bomba de protones"],"r":1,"e":"Las esporas resisten el alcohol: se requiere lavado con agua y jabón y aislamiento de contacto.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Lactante de 10 meses con diarrea acuosa de 1 día. Alerta, ojos normales, bebe normal, pliegue cutáneo regresa rápido.","p":"¿Qué plan corresponde?","o":["Plan A","Plan B","Plan C","Hospitalizar"],"r":0,"e":"Sin signos de deshidratación se maneja en casa con plan A: más líquidos, alimentación y suero oral después de cada evacuación.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Niño de 2 años, 12 kg, con diarrea; irritable, ojos hundidos, bebe con avidez y el pliegue regresa lento. Sin choque.","p":"¿Cuánto suero oral le das con el plan B?","o":["300 mL en 24 horas","1,200 mL en 4 horas","50 mL después de cada evacuación","120 mL en 4 horas"],"r":1,"e":"Plan B: 100 mL por kilo en 4 horas (12 kg por 100 = 1,200 mL), en tomas cada 30 minutos.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Lactante de 8 meses, 8 kg, letárgico, no puede beber, pulso débil y llenado capilar de 4 segundos.","p":"¿Cuánto Hartmann le das en la primera hora (plan C mexicano)?","o":["80 mL","400 mL","800 mL","160 mL"],"r":1,"e":"Plan C: 50 mL por kilo la primera hora (400 mL), luego 25 y 25 mL por kilo; referir.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Niño de 3 años con diarrea aguda sin deshidratación.","p":"¿Qué dosis de zinc le das?","o":["10 mg al día por 3 días","20 mg al día por 10 a 14 días","50 mg dosis única","No se da zinc en mayores de 6 meses"],"r":1,"e":"Zinc: 20 mg al día en mayores de 6 meses (10 mg en menores) por 10 a 14 días.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Madre pregunta si puede darle a su hijo de 2 años loperamida para que se le corte la diarrea.","p":"¿Qué le respondes?","o":["Sí, 2 mg cada 8 horas","No: está contraindicada en niños","Sí, solo si hay sangre","Sí, con suero oral"],"r":1,"e":"La guía mexicana no recomienda loperamida en niños por riesgo de íleo y efectos neurológicos.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"¿Qué solución de rehidratación oral se recomienda?","p":"Elige la opción correcta.","o":["La de alta osmolaridad (311)","La de baja osmolaridad (245, con sodio de 75)","Refresco de cola desgasificado","Bebidas deportivas"],"r":1,"e":"El suero de baja osmolaridad reduce el gasto fecal, el vómito y la necesidad de líquidos intravenosos.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Niño de 4 años con diarrea con moco y sangre, fiebre de 39 °C y tenesmo.","p":"¿Qué haces además de hidratar?","o":["Nada, es viral","Antibiótico por probable shigelosis disentérica","Loperamida","Metoclopramida"],"r":1,"e":"La disentería con fiebre sugiere Shigella; la guía indica antibiótico en shigelosis disenteriforme.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Niño de 5 años con diarrea por Salmonella no tifoídica confirmada, sin otras enfermedades, con buen estado general.","p":"¿Cuál es la conducta?","o":["Ciprofloxacino 7 días","Solo hidratación, sin antibiótico","Ceftriaxona 10 días","Azitromicina 5 días"],"r":1,"e":"La gastroenteritis por Salmonella en un sano no se trata: el antibiótico prolonga el estado de portador.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"¿En quién SÍ tratarías una gastroenteritis por Salmonella no tifoídica?","p":"Elige la opción correcta.","o":["Adolescente sano","Lactante menor de 6 meses","Adulto joven sin comorbilidades","Embarazada sana con diarrea leve"],"r":1,"e":"Se trata en menores de 6 meses (guía mexicana), adultos mayores, inmunosuprimidos y portadores de prótesis vasculares.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Brote de diarrea acuosa y vómito en un crucero en invierno, coprocultivos negativos.","p":"¿Cuál es el agente más probable?","o":["Norovirus","Rotavirus","Shigella","Giardia"],"r":0,"e":"Norovirus causa la mayoría de los brotes de diarrea en adultos con coprocultivo negativo, sobre todo en invierno.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Paciente con diarrea muy abundante en agua de arroz y deshidratación rápida.","p":"¿Qué agente sospechas?","o":["Vibrio cholerae","Shigella","Entamoeba histolytica","Staphylococcus aureus"],"r":0,"e":"Las heces en agua de arroz son típicas del cólera, por enterotoxina; lo principal es la hidratación.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Adulto de 35 años con diarrea acuosa de 1 día, sin fiebre ni sangre, que necesita trabajar.","p":"¿Qué puedes indicar?","o":["Loperamida 4 mg y luego 2 mg tras cada evacuación","Ciprofloxacino 7 días","Metronidazol","Vancomicina oral"],"r":0,"e":"En la diarrea acuosa sin fiebre ni sangre la loperamida es segura en adultos; máximo 16 mg al día.","f":"Harrison, capítulo 133"},{"c":"Adulto con diarrea con sangre y fiebre de 39 °C.","p":"¿Qué fármaco evitas?","o":["Suero oral","Loperamida","Azitromicina","Paracetamol"],"r":1,"e":"Los antimotílicos se evitan en la diarrea invasiva o por citotoxinas porque prolongan la infección y pueden causar megacolon.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Adulto con diarrea por Campylobacter que requiere antibiótico.","p":"¿Cuál prefieres?","o":["Ciprofloxacino","Azitromicina","Trimetoprima con sulfametoxazol","Amoxicilina"],"r":1,"e":"Campylobacter tiene alta resistencia a quinolonas: el macrólido es de elección.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Paciente con diarrea con sangre y moco sin fiebre importante, de evolución de 2 semanas. En el examen se ven trofozoitos con eritrocitos fagocitados.","p":"¿Cuál es el tratamiento?","o":["Metronidazol y luego un amebicida luminal","Solo loperamida","Vancomicina oral","Ciprofloxacino 3 días"],"r":0,"e":"La amebiasis invasiva se trata con metronidazol seguido de un amebicida luminal para erradicar los quistes.","f":"Harrison, capítulo 133"},{"c":"Niño con diarrea crónica, distensión, flatulencia y heces grasosas después de ir a una guardería.","p":"¿Qué germen sospechas?","o":["Giardia lamblia","Shigella","Vibrio cholerae","Bacillus cereus"],"r":0,"e":"Giardia causa diarrea con malabsorción y es frecuente en guarderías; se trata con metronidazol o tinidazol.","f":"Harrison, capítulo 133"},{"c":"¿Cuál es la causa más frecuente de diarrea aguda grave en niños pequeños?","p":"Elige la opción correcta.","o":["Rotavirus","Norovirus","Shigella","Escherichia coli enterohemorrágica"],"r":0,"e":"Rotavirus es la causa más frecuente en niños; la vacuna ha reducido su frecuencia.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Niño en plan B que vomita la primera toma de suero.","p":"¿Qué haces?","o":["Pasar directo a plan C","Esperar 10 minutos y seguir con tomas más pequeñas y frecuentes","Suspender el suero 24 horas","Dar metoclopramida intramuscular"],"r":1,"e":"El vómito no contraindica la hidratación oral: se espera y se continúa más despacio; si fracasa, sonda nasogástrica o intravenosa.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"¿Cuál de estos niños con diarrea debe hospitalizarse?","p":"Elige la opción correcta.","o":["Niño de 3 años sin deshidratación","Lactante con deshidratación grave mayor de 9% o choque","Niño de 2 años con 3 evacuaciones al día","Escolar con diarrea leve de 1 día"],"r":1,"e":"La guía indica hospitalizar con choque o deshidratación grave, lactantes de alto riesgo y alteraciones neurológicas.","f":"Guía de Práctica Clínica IMSS-156-08"},{"c":"Adulto con diarrea leve de 2 días, sin fiebre, sin sangre, sin viaje ni antibióticos.","p":"¿Pides coprocultivo?","o":["Sí, siempre","No, no es necesario","Sí, y colonoscopia","Solo serología"],"r":1,"e":"La mayoría de las diarreas agudas son autolimitadas; el coprocultivo se reserva para fiebre, sangre, gravedad, inmunosupresión o duración mayor de 7 días.","f":"Harrison, capítulo 133"},{"c":"Paciente con artritis de rodillas, conjuntivitis y uretritis 3 semanas después de una diarrea por Shigella.","p":"¿Qué presenta?","o":["Artritis séptica","Artritis reactiva","Gota","Lupus"],"r":1,"e":"La artritis reactiva aparece tras infecciones por Salmonella, Shigella, Yersinia o Campylobacter, sobre todo con HLA-B27.","f":"Manual CTO, Enfermedades infecciosas, capítulo 8"},{"c":"Niña de 3 años con diarrea leve en plan A. ¿Cuánto suero después de cada evacuación (guía mexicana)?","p":"Elige la opción correcta.","o":["75 mL","150 mL","500 mL","No se da suero en plan A"],"r":1,"e":"Plan A: mayores de 1 año, una taza (150 mL) después de cada evacuación; menores de 1 año, media taza (75 mL).","f":"Guía de Práctica Clínica IMSS-156-08"}],"audio":[["¿Qué es lo más importante en la diarrea aguda?","La hidratación. La mayoría es viral y se cura sola."],["Vómito a las 2 horas de comer pastel con crema: ¿qué germen?","Staphylococcus aureus, por toxina preformada."],["¿Y si fue arroz frito?","Bacillus cereus."],["¿Causa más frecuente de diarrea del viajero?","Escherichia coli enterotoxigénica."],["Dime el plan A mexicano.","Más líquidos, seguir comiendo y suero oral después de cada evacuación: media taza en menores de 1 año y una taza en mayores."],["¿Plan B?","Suero oral 100 mililitros por kilo en 4 horas, cada 30 minutos."],["¿Plan C?","Hartmann intravenoso: 50 mililitros por kilo la primera hora, 25 la segunda y 25 la tercera."],["¿Dosis de zinc?","10 miligramos en menores de 6 meses y 20 en mayores, por 10 a 14 días."],["¿Cuándo no das loperamida?","En niños y si hay fiebre o sangre."],["¿Antibiótico en Salmonella no tifoídica?","No en sanos. Sí en menores de 6 meses, adultos mayores, inmunosuprimidos o prótesis vasculares."],["¿Por qué no antibiótico en Escherichia coli O157?","Porque aumenta el riesgo de síndrome hemolítico urémico."],["¿Tratamiento de Clostridioides difficile?","Vancomicina oral 125 miligramos cada 6 horas por 10 días y suspender el antibiótico causal."],["Diarrea por Campylobacter y luego parálisis: ¿qué es?","Síndrome de Guillain-Barré."],["¿Antibiótico para Campylobacter?","Azitromicina, por la resistencia a quinolonas."]],"profundizar":{"harrison":[[133,"Diarreas infecciosas agudas e intoxicación alimentaria por bacterias"],[46,"Diarrea y estreñimiento"]],"guias":[["Prevención, diagnóstico y tratamiento de la diarrea aguda en niños de dos meses a cinco años en el primero y segundo nivel de atención, IMSS-156-08 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/156GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/156GRR.pdf"],["Prevención, diagnóstico y tratamiento de diarrea aguda en el paciente adulto en primer nivel de atención, GPC-SS-106-20, 2020 (sin enlace oficial por ahora)",""]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Enfermedades infecciosas, capítulo 8, páginas 74 a 81 del archivo; Pediatría, capítulo 4.","Guía de Práctica Clínica IMSS-156-08: Prevención, diagnóstico y tratamiento de la diarrea aguda en niños de dos meses a cinco años, Instituto Mexicano del Seguro Social.","Guía de Práctica Clínica GPC-SS-106-20: diarrea aguda en el adulto en primer nivel, Secretaría de Salud, 2020.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 46 y 133."]},"gastroenterologia-y-hepatologia-digestivo-4":{"titulo":"Dispepsia y reflujo gastroesofágico en la consulta","enfoque":"Enfoque de consulta de primer nivel: datos de alarma, prueba con inhibidor de la bomba de protones, Helicobacter pylori, antiinflamatorios, úlcera péptica, esófago de Barrett y cuándo pedir endoscopia.","resumen":[{"h":"Lo esencial en 30 segundos","li":["Primero busca **datos de alarma**: si hay alguno, **endoscopia** pronto.","**Pirosis y regurgitación** sin alarma: es reflujo; se trata de forma empírica con **inhibidor de la bomba de protones por 8 semanas**, sin estudios.","**Dispepsia** (dolor o ardor epigástrico, llenura después de comer, saciedad temprana) sin alarma: **busca y trata Helicobacter pylori**, y si no hay, inhibidor de la bomba de protones.","La prueba de elección para Helicobacter pylori es la **prueba de aliento con urea**; también sirve el antígeno en heces. La serología no sirve para comprobar curación.","Tratamiento de Helicobacter pylori por **14 días**; en México se prefiere la **cuádruple con bismuto** por la resistencia a claritromicina. Comprueba la erradicación 4 semanas después."]},{"h":"Datos de alarma: endoscopia","li":["**Disfagia** u odinofagia, **pérdida de peso** no intencionada, **anemia** por deficiencia de hierro, **hematemesis o melena**, **vómito persistente**, masa abdominal.","Inicio de síntomas **después de los 50 años** (guía mexicana) o familiar con **cáncer gástrico**.","Uso de antiinflamatorios no esteroideos con cualquiera de los anteriores.","También pide endoscopia si no responde al tratamiento empírico."]},{"h":"Reflujo: cómo se presenta","li":["Típicos: **pirosis** (ardor retroesternal que sube) y **regurgitación**, peor después de comer, al acostarse o al agacharse.","Extraesofágicos: **tos crónica**, ronquera o laringitis, asma de difícil control, erosiones dentales, dolor torácico no cardiaco (descarta primero el corazón).","Factores: obesidad, hernia hiatal, embarazo, tabaco, comidas abundantes o grasosas, alcohol, café, chocolate y fármacos que relajan el esfínter (calcioantagonistas, nitratos, anticolinérgicos)."]},{"h":"Reflujo: tratamiento","li":["Estilo de vida: **bajar de peso**, **elevar la cabecera**, no cenar 2 a 3 horas antes de acostarse, dejar el tabaco y evitar lo que a cada quien le cause síntomas.","**Inhibidor de la bomba de protones** a dosis estándar (omeprazol 20 mg, pantoprazol 40 mg, esomeprazol 40 mg) **30 a 60 minutos antes del desayuno**, por **8 semanas**.","Respuesta parcial: duplicar la dosis (una antes del desayuno y otra antes de la cena) y revisar el apego y la toma.","Mantenimiento: la dosis mínima que controle los síntomas o a demanda; continuo en esofagitis grave (Los Ángeles C o D) o esófago de Barrett.","Cirugía: **funduplicatura de Nissen laparoscópica** si hay buena respuesta pero no quiere o no tolera el fármaco, o hay regurgitación importante."]},{"h":"Reflujo: estudios","li":["La **endoscopia** se pide con datos de alarma, falla al tratamiento o para buscar complicaciones. Clasifica la esofagitis de **Los Ángeles A a D** según la extensión de las erosiones.","La **pH-metría de 24 horas** (con impedancia) es la prueba más exacta: síntomas atípicos sin respuesta, endoscopia normal con síntomas que persisten y antes de la cirugía.","No se necesita ningún estudio con pirosis típica sin alarma."]},{"h":"Complicaciones del reflujo","li":["Esofagitis erosiva, úlcera y **sangrado**.","**Estenosis péptica**: disfagia progresiva a sólidos; se dilata por endoscopia y se mantiene el inhibidor.","**Esófago de Barrett**: el epitelio escamoso cambia a **metaplasia intestinal** (diagnóstico por biopsia). Riesgo de **adenocarcinoma** (alrededor de 0.5% al año): inhibidor de la bomba de protones y vigilancia endoscópica con biopsias."]},{"h":"Dispepsia","li":["Síntomas en el epigastrio: dolor o ardor, **llenura después de comer** y **saciedad temprana**.","Causas orgánicas: **úlcera péptica**, reflujo, antiinflamatorios, cáncer gástrico, litiasis biliar (dolor tipo cólico, no dispepsia).","**Dispepsia funcional**: síntomas sin lesión en la endoscopia; dos tipos, de dolor epigástrico y de malestar después de comer.","Si predomina la pirosis, trátala como reflujo."]},{"h":"Dispepsia sin alarma: qué hacer","li":["Revisa y suspende **antiinflamatorios no esteroideos** si es posible (o cambia a paracetamol).","**Prueba y trata Helicobacter pylori** con aliento con urea o antígeno en heces.","Si es negativo o persiste tras erradicar: **inhibidor de la bomba de protones por 4 a 8 semanas**.","Si persiste: procinético o un antidepresivo tricíclico a dosis baja; si no responde, endoscopia.","Con antiinflamatorio indispensable: agregar inhibidor de la bomba de protones o usar celecoxib si no hay contraindicación."]},{"h":"Helicobacter pylori","li":["Bacilo gramnegativo espiral productor de **ureasa**; vive en el antro gástrico.","Causa gastritis crónica, **úlcera duodenal** (la mayoría) y gástrica, **adenocarcinoma gástrico** y **linfoma MALT**.","Pruebas sin endoscopia: **aliento con urea** (de elección) y antígeno en heces. Con endoscopia: prueba rápida de ureasa e histología.","Antes de la prueba: suspender el inhibidor de la bomba de protones **2 semanas** y antibióticos o bismuto **4 semanas** (dan falsos negativos).","**Cuádruple con bismuto 14 días**: inhibidor de la bomba de protones, bismuto, tetraciclina y metronidazol. **Triple clásica 14 días** (inhibidor, amoxicilina 1 g y claritromicina 500 mg cada 12 horas) solo donde la resistencia a claritromicina es baja. Alergia a la penicilina: cuádruple con bismuto.","Comprueba la erradicación con aliento o antígeno **al menos 4 semanas después** del tratamiento."]},{"h":"Úlcera péptica","li":["Causas principales: **Helicobacter pylori** y **antiinflamatorios no esteroideos**.","Duodenal: dolor que **mejora al comer** y despierta en la noche. Gástrica: dolor que empeora con la comida.","La úlcera gástrica se **biopsia** y se revisa con endoscopia de control hasta su cicatrización (descartar cáncer).","Complicaciones: **hemorragia** (la más frecuente), perforación (dolor súbito, aire libre subdiafragmático) y obstrucción."]},{"h":"Inhibidores de la bomba de protones a largo plazo","li":["Úsalos a la dosis mínima eficaz y retíralos si ya no hay indicación.","Uso prolongado se asocia a **hipomagnesemia**, **déficit de vitamina B12**, fracturas, neumonía e infección por **Clostridioides difficile**."]},{"h":"Cuándo referir","li":["Endoscopia pronto: cualquier dato de alarma o inicio después de los 50 años.","Gastroenterología: síntomas que persisten tras tratamiento empírico y dos intentos de erradicación, esófago de Barrett, estenosis.","**Urgencias**: hematemesis o melena con inestabilidad, dolor abdominal súbito e intenso (perforación) o vómito con imposibilidad para comer."]}],"perlas":["Pirosis típica sin alarma: **inhibidor de la bomba de protones 8 semanas, sin estudios**.","Prueba más exacta para reflujo: **pH-metría de 24 horas**.","Esófago de Barrett: **metaplasia intestinal**; riesgo de **adenocarcinoma**.","Helicobacter pylori: prueba de elección **aliento con urea**; la serología **no** sirve para control.","Suspender el inhibidor **2 semanas** antes de la prueba de aliento.","Úlcera gástrica: siempre **biopsia** y control endoscópico."],"mexico":["La Guía de Práctica Clínica IMSS-071-08 de dispepsia funcional es de 2009 y propone tratamiento empírico en orden con metoclopramida, **ranitidina** y omeprazol. La **ranitidina se retiró del mercado en 2020** y hoy se prefiere buscar Helicobacter pylori y usar un inhibidor de la bomba de protones.","La misma guía considera dato de alarma el inicio de síntomas **después de los 50 años** y pide biometría hemática, velocidad de sedimentación y química sanguínea en la primera consulta.","Por la resistencia a claritromicina en México, las recomendaciones mexicanas de gastroenterología prefieren la **terapia cuádruple con bismuto por 14 días** como primera línea.","Para reflujo se usan las recomendaciones de la Asociación Mexicana de Gastroenterología (2024), que coinciden con el CTO en la prueba empírica con inhibidor de la bomba de protones por 8 semanas."],"preguntas":[{"c":"Hombre de 34 años con pirosis y regurgitación después de comer, 3 veces por semana, sin pérdida de peso, disfagia ni sangrado.","p":"¿Cuál es la conducta?","o":["Endoscopia","Inhibidor de la bomba de protones por 8 semanas sin estudios","pH-metría de 24 horas","Serie esofagogastroduodenal"],"r":1,"e":"La pirosis típica sin datos de alarma permite el tratamiento empírico con inhibidor de la bomba de protones.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"¿Cuál es la prueba más exacta para confirmar reflujo gastroesofágico?","p":"Elige la opción correcta.","o":["Endoscopia","pH-metría de 24 horas","Manometría","Serie esofagogastroduodenal"],"r":1,"e":"La pH-metría (con impedancia) mide la exposición ácida y es la prueba de certeza; la endoscopia es normal en muchos pacientes.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Mujer de 62 años con pirosis de inicio reciente, disfagia a sólidos y pérdida de 6 kg.","p":"¿Qué haces?","o":["Omeprazol 8 semanas y revalorar","Endoscopia pronto","Bajar de peso y elevar la cabecera","Ranitidina"],"r":1,"e":"Disfagia y pérdida de peso son datos de alarma: endoscopia sin demora para descartar cáncer o estenosis.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Paciente con reflujo que toma omeprazol 20 mg en la noche al acostarse y refiere poca mejoría.","p":"¿Qué corriges primero?","o":["Cambiar a cirugía","Tomarlo 30 a 60 minutos antes del desayuno","Agregar procinético","Suspenderlo"],"r":1,"e":"Los inhibidores de la bomba de protones actúan sobre bombas activas: se toman antes de la primera comida.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Paciente con reflujo de larga evolución. La biopsia del esófago distal muestra metaplasia intestinal con células caliciformes.","p":"¿Qué diagnóstico tiene?","o":["Esofagitis eosinofílica","Esófago de Barrett","Acalasia","Carcinoma epidermoide"],"r":1,"e":"El esófago de Barrett es la sustitución del epitelio escamoso por metaplasia intestinal.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"¿Qué cáncer se asocia al esófago de Barrett?","p":"Elige la opción correcta.","o":["Carcinoma epidermoide","Adenocarcinoma","Linfoma","Tumor del estroma gastrointestinal"],"r":1,"e":"El Barrett es la lesión precursora del adenocarcinoma de esófago.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Paciente con tos crónica, ronquera matutina y carraspeo, radiografía de tórax normal, sin tabaquismo ni inhibidores de la enzima convertidora.","p":"¿Qué causa consideras?","o":["Reflujo gastroesofágico","Tuberculosis","Cáncer de pulmón","Insuficiencia cardiaca"],"r":0,"e":"El reflujo es causa frecuente de tos crónica y laringitis (manifestaciones extraesofágicas).","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Paciente con reflujo que responde muy bien al omeprazol pero no quiere tomarlo de por vida.","p":"¿Qué opción quirúrgica existe?","o":["Gastrectomía","Funduplicatura de Nissen laparoscópica","Miotomía de Heller","Vagotomía troncular"],"r":1,"e":"La funduplicatura de Nissen laparoscópica es la cirugía antirreflujo de elección.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Paciente con reflujo y disfagia progresiva a sólidos. La endoscopia muestra un estrechamiento liso en el esófago distal, biopsia benigna.","p":"¿Qué presenta?","o":["Acalasia","Estenosis péptica","Anillo de Schatzki congénito","Cáncer"],"r":1,"e":"La estenosis péptica es complicación del reflujo: se trata con dilatación y mantenimiento con inhibidor de la bomba de protones.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"¿Qué consejo de estilo de vida tiene mejor evidencia en el reflujo?","p":"Elige la opción correcta.","o":["Dejar todos los irritantes","Bajar de peso y elevar la cabecera de la cama","Tomar leche antes de dormir","Dormir boca abajo"],"r":1,"e":"Bajar de peso y elevar la cabecera (más no cenar tarde) tienen la mejor evidencia.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Mujer de 28 años con dolor epigástrico y llenura después de comer de 3 meses, sin datos de alarma, sin antiinflamatorios.","p":"¿Cuál es la estrategia recomendada?","o":["Endoscopia a todos","Buscar y tratar Helicobacter pylori","Ranitidina","Tomografía de abdomen"],"r":1,"e":"En dispepsia sin alarma la estrategia de probar y tratar Helicobacter pylori es eficaz y evita endoscopias.","f":"Harrison, capítulos 163 y 324"},{"c":"¿Cuál es la prueba no invasiva de elección para Helicobacter pylori?","p":"Elige la opción correcta.","o":["Serología","Prueba de aliento con urea","Biometría hemática","Coprocultivo"],"r":1,"e":"La prueba de aliento con urea marcada es la de elección para diagnóstico y para comprobar la erradicación.","f":"Guía de Práctica Clínica IMSS-071-08"},{"c":"Paciente que toma omeprazol diario y necesita prueba de aliento para Helicobacter pylori.","p":"¿Qué le indicas?","o":["Seguir tomándolo","Suspenderlo 2 semanas antes","Duplicar la dosis","Tomarlo el mismo día"],"r":1,"e":"Los inhibidores de la bomba de protones dan falsos negativos: se suspenden 2 semanas antes (antibióticos y bismuto 4 semanas).","f":"Harrison, capítulos 163 y 324"},{"c":"Paciente tratado para Helicobacter pylori hace 6 semanas.","p":"¿Cómo compruebas la erradicación?","o":["Serología","Prueba de aliento o antígeno en heces","No es necesario","Biometría"],"r":1,"e":"La serología puede seguir positiva por meses; se usa aliento o antígeno en heces, al menos 4 semanas después del tratamiento.","f":"Harrison, capítulos 163 y 324"},{"c":"Paciente con Helicobacter pylori en México, sin alergias.","p":"¿Qué esquema se prefiere como primera línea?","o":["Triple con claritromicina 7 días","Cuádruple con bismuto por 14 días","Solo omeprazol","Amoxicilina sola"],"r":1,"e":"Por la resistencia a claritromicina en México se prefiere la terapia cuádruple con bismuto por 14 días.","f":"Harrison, capítulos 163 y 324"},{"c":"Paciente alérgico a la penicilina con Helicobacter pylori.","p":"¿Qué esquema usas?","o":["Triple con amoxicilina","Cuádruple con bismuto, tetraciclina y metronidazol","Solo claritromicina","Levofloxacino solo"],"r":1,"e":"La cuádruple con bismuto no incluye amoxicilina y es la opción en alergia.","f":"Harrison, capítulos 163 y 324"},{"c":"¿Qué enfermedad NO se relaciona con Helicobacter pylori?","p":"Elige la opción correcta.","o":["Úlcera duodenal","Linfoma MALT gástrico","Adenocarcinoma gástrico","Esófago de Barrett"],"r":3,"e":"Helicobacter pylori causa úlcera, adenocarcinoma gástrico y linfoma MALT; el Barrett se debe al reflujo ácido.","f":"Manual CTO, Digestivo, capítulos 7 y 10"},{"c":"Hombre de 45 años con dolor epigástrico que mejora al comer y lo despierta en la madrugada.","p":"¿Qué sospechas?","o":["Úlcera duodenal","Úlcera gástrica","Pancreatitis","Colecistitis"],"r":0,"e":"El dolor que mejora con la comida y despierta en la noche es típico de la úlcera duodenal.","f":"Manual CTO, Digestivo, capítulos 7 y 10"},{"c":"Endoscopia con úlcera gástrica de 1.5 cm.","p":"¿Qué es obligatorio?","o":["Solo tratar con omeprazol","Tomar biopsias y repetir la endoscopia hasta la cicatrización","Cirugía","Tomografía"],"r":1,"e":"Toda úlcera gástrica se biopsia y se controla con endoscopia para descartar cáncer.","f":"Manual CTO, Digestivo, capítulos 7 y 10"},{"c":"¿Cuál es la complicación más frecuente de la úlcera péptica?","p":"Elige la opción correcta.","o":["Perforación","Hemorragia","Obstrucción","Penetración"],"r":1,"e":"La hemorragia es la complicación más frecuente; la perforación da dolor súbito y aire libre.","f":"Manual CTO, Digestivo, capítulos 7 y 10"},{"c":"Paciente con úlcera que súbitamente presenta dolor abdominal intenso y abdomen en tabla.","p":"¿Qué estudio inicial pides y qué buscas?","o":["Ultrasonido; cálculos","Radiografía de tórax de pie; aire libre bajo el diafragma","Endoscopia; sangrado","Colonoscopia"],"r":1,"e":"La perforación se sospecha con abdomen en tabla; la radiografía de pie muestra neumoperitoneo. Es una urgencia quirúrgica.","f":"Manual CTO, Digestivo, capítulos 7 y 10"},{"c":"Paciente con artritis que necesita naproxeno y tiene dispepsia.","p":"¿Qué haces?","o":["Seguir igual","Agregar inhibidor de la bomba de protones o cambiar a paracetamol o celecoxib","Agregar ranitidina","Suspender todo y dar esteroides"],"r":1,"e":"Si el antiinflamatorio no se puede suspender, la guía indica omeprazol o cambiarlo por paracetamol o celecoxib.","f":"Guía de Práctica Clínica IMSS-071-08"},{"c":"Según la guía mexicana de dispepsia, ¿cuál es un dato de alarma?","p":"Elige la opción correcta.","o":["Inicio de síntomas después de los 50 años","Distensión después de comer","Eructos","Síntomas de 2 meses"],"r":0,"e":"La guía considera alarma el inicio después de los 50 años, historia familiar de cáncer gástrico, masa, disfagia, anemia, pérdida de peso, sangrado y vómito persistente.","f":"Guía de Práctica Clínica IMSS-071-08"},{"c":"Paciente con dispepsia funcional y pirosis predominante.","p":"¿Cómo la tratas?","o":["Como reflujo","Solo procinético","Cirugía","Endoscopia urgente"],"r":0,"e":"Si predomina la pirosis, la guía indica tratar de primera instancia como reflujo.","f":"Guía de Práctica Clínica IMSS-071-08"},{"c":"¿Qué fármaco de la guía mexicana de dispepsia ya no está disponible?","p":"Elige la opción correcta.","o":["Omeprazol","Ranitidina","Metoclopramida","Pantoprazol"],"r":1,"e":"La ranitidina se retiró en 2020 por contaminación con nitrosaminas.","f":"Guía de Práctica Clínica IMSS-071-08"},{"c":"Paciente con omeprazol diario desde hace 8 años sin indicación clara, con calambres y arritmia.","p":"¿Qué alteración buscas?","o":["Hipermagnesemia","Hipomagnesemia","Hipercalcemia","Hiperpotasemia"],"r":1,"e":"El uso prolongado de inhibidores de la bomba de protones se asocia a hipomagnesemia.","f":"Harrison, capítulos 163 y 324"},{"c":"Embarazada de 30 semanas con pirosis.","p":"¿Qué haces primero?","o":["Endoscopia","Medidas de estilo de vida y antiácidos; inhibidor si persiste","Funduplicatura","Nada, es normal"],"r":1,"e":"En el embarazo se empieza con medidas generales y antiácidos o sucralfato; los inhibidores de la bomba de protones se usan si es necesario.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"Dispepsia funcional sin respuesta a inhibidor de la bomba de protones y sin Helicobacter pylori.","p":"¿Qué puedes agregar?","o":["Antidepresivo tricíclico a dosis baja o procinético","Opioides","Antibiótico de amplio espectro","Corticoide"],"r":0,"e":"En la dispepsia funcional refractaria se usan neuromoduladores como tricíclicos a dosis baja o procinéticos.","f":"Harrison, capítulos 163 y 324"},{"c":"Paciente con reflujo y endoscopia con erosiones confluentes en más de 75% de la circunferencia del esófago.","p":"¿Qué grado de Los Ángeles es y qué implica?","o":["A; tratamiento a demanda","D; tratamiento de mantenimiento continuo","B; sin tratamiento","Barrett"],"r":1,"e":"El grado D (erosiones que abarcan más de 75% de la circunferencia) es esofagitis grave: requiere inhibidor continuo.","f":"Manual CTO, Digestivo, capítulo 4"},{"c":"¿Qué fármaco relaja el esfínter esofágico inferior y empeora el reflujo?","p":"Elige la opción correcta.","o":["Metoclopramida","Calcioantagonistas","Domperidona","Betanecol"],"r":1,"e":"Calcioantagonistas, nitratos y anticolinérgicos disminuyen la presión del esfínter esofágico inferior.","f":"Manual CTO, Digestivo, capítulo 4"}],"audio":[["¿Qué haces con pirosis típica sin alarma?","Inhibidor de la bomba de protones 8 semanas, antes del desayuno, sin estudios."],["Dime los datos de alarma.","Disfagia, pérdida de peso, anemia, sangrado, vómito persistente, masa, inicio después de los 50 años o familiar con cáncer gástrico."],["¿Prueba más exacta para reflujo?","pH-metría de 24 horas."],["¿Qué es el esófago de Barrett?","Metaplasia intestinal del esófago distal por reflujo; riesgo de adenocarcinoma."],["¿Cirugía antirreflujo de elección?","Funduplicatura de Nissen laparoscópica."],["¿Qué haces con dispepsia sin alarma?","Buscar y tratar Helicobacter pylori; si no hay, inhibidor de la bomba de protones 4 a 8 semanas."],["¿Prueba de elección para Helicobacter pylori?","Prueba de aliento con urea. La serología no sirve para control."],["¿Cuánto suspendes el inhibidor antes de la prueba?","Dos semanas; antibióticos y bismuto, cuatro semanas."],["¿Esquema de erradicación preferido en México?","Cuádruple con bismuto por 14 días."],["¿Cuándo compruebas la erradicación?","Al menos 4 semanas después, con aliento o antígeno en heces."],["Dolor epigástrico que mejora al comer: ¿qué úlcera?","Duodenal."],["¿Qué haces siempre con una úlcera gástrica?","Biopsia y endoscopia de control."],["¿Complicación más frecuente de la úlcera?","Hemorragia."],["¿Efectos del uso prolongado de inhibidores de la bomba de protones?","Hipomagnesemia, déficit de vitamina B12, fracturas y Clostridioides difficile."]],"profundizar":{"harrison":[[45,"Náusea, vómito y dispepsia"],[323,"Enfermedades del esófago"],[324,"Enfermedad ulcerosa péptica y trastornos relacionados"],[163,"Infecciones por Helicobacter pylori"]],"guias":[["Diagnóstico y tratamiento de la dispepsia funcional, IMSS-071-08 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/071GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/071GRR.pdf"],["Recomendaciones de buena práctica clínica en el diagnóstico y tratamiento de la enfermedad por reflujo gastroesofágico, Asociación Mexicana de Gastroenterología, Revista de Gastroenterología de México 2024 (no es sitio de gobierno)",""]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Digestivo, capítulos 4, 7 y 10.","Guía de Práctica Clínica IMSS-071-08: Diagnóstico y tratamiento de la dispepsia funcional, Instituto Mexicano del Seguro Social.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulos 45, 163, 323 y 324."]},"urologia-2":{"titulo":"Infección de vías urinarias en la consulta","enfoque":"Enfoque de consulta de primer nivel: cistitis en la mujer, pielonefritis, embarazo, varón, bacteriuria asintomática, recurrencias y sonda vesical.","resumen":[{"h":"Lo esencial en 30 segundos","li":["La causa más frecuente es **Escherichia coli** (alrededor de 85% en la comunidad). La segunda en mujeres jóvenes sexualmente activas es **Staphylococcus saprophyticus**.","Cistitis no complicada en la mujer: el diagnóstico es **clínico**. Con dos o más síntomas clásicos y sin flujo vaginal, se trata **sin estudios**.","Tratamientos cortos: **fosfomicina 3 g dosis única**, **nitrofurantoína 100 mg cada 12 horas por 5 a 7 días** o trimetoprima con sulfametoxazol 160/800 mg cada 12 horas por 3 días.","La infección urinaria del **varón** se considera **complicada** desde el inicio.","La **bacteriuria asintomática no se trata**, salvo en el **embarazo** y antes de un procedimiento urológico invasivo.","Pielonefritis: **urocultivo antes** del antibiótico; ciprofloxacino 500 mg cada 12 horas por 7 días si no hay criterios de hospitalización."]},{"h":"No complicada o complicada","li":["**No complicada**: mujer sana, no embarazada, con vías urinarias normales.","**Complicada**: varón, embarazo, sonda, obstrucción o litiasis, reflujo vesicoureteral, anomalías anatómicas, insuficiencia renal, trasplante renal o inmunosupresión.","**Recurrente** (guía mexicana): 3 o más episodios en 12 meses o 2 en 6 meses. **Reinfección**: germen distinto y lapsos largos (lo más frecuente). **Recaída**: mismo germen, poco después de terminar el tratamiento."]},{"h":"Diagnóstico","li":["Síntomas clásicos: **disuria, polaquiuria y urgencia**; puede haber hematuria terminal y dolor suprapúbico.","Si además hay **prurito o flujo vaginal**, pensar en vaginitis o infección de transmisión sexual y explorar.","**Tira reactiva**: nitritos (las enterobacterias reducen nitratos a nitritos) y esterasa leucocitaria (piuria). Útil cuando hay un solo síntoma; una tira negativa no descarta.","Piuria: más de 10 leucocitos por mm³.","Urocultivo significativo: clásicamente **100,000 unidades formadoras de colonias por mL**; 1,000 en mujer sintomática; 10,000 en pielonefritis o varón; 100 por cateterismo; **cualquier recuento por punción suprapúbica**.","Pide urocultivo en pielonefritis, infección complicada, embarazo, varón, recurrencia o falla al tratamiento."]},{"h":"Cistitis no complicada: tratamiento","li":["**Fosfomicina trometamol 3 g** en una sola dosis.","**Nitrofurantoína 100 mg cada 12 horas** por 5 a 7 días. No sirve en pielonefritis (concentraciones bajas en sangre) y **Proteus es resistente**.","**Trimetoprima con sulfametoxazol 160/800 mg cada 12 horas por 3 días**, solo si la resistencia local es baja.","**No** usar quinolonas de forma empírica en la cistitis: se reservan por resistencias y efectos adversos.","Fenazopiridina 100 mg cada 8 horas por 48 horas si la disuria es intensa.","Los síntomas deben ceder en 2 a 3 días; si no, urocultivo con antibiograma y verificar el apego."]},{"h":"Embarazo","li":["Se **busca y se trata** la bacteriuria asintomática: sin tratamiento aumenta el riesgo de **pielonefritis** y de parto pretérmino.","Opciones: **fosfomicina**, **cefalexina**, amoxicilina con ácido clavulánico o nitrofurantoína (evitarla cerca del término).","**Evitar quinolonas** (daño al cartílago fetal) y **sulfonamidas en el tercer trimestre** (kernícterus).","Pedir urocultivo de control después del tratamiento. Pielonefritis en el embarazo: hospitalizar."]},{"h":"Pielonefritis aguda","li":["Síntomas de cistitis más **fiebre mayor de 38 °C**, **dolor en fosa renal** (puñopercusión positiva), escalofríos, náusea o vómito.","Tomar **urocultivo antes** de iniciar el antibiótico y ajustar con el resultado.","Ambulatoria si no hay datos de sepsis y tolera la vía oral: **ciprofloxacino 500 mg cada 12 horas por 7 días** (puede iniciarse con una dosis de ceftriaxona 1 g).","Hospitalizar: sepsis, vómito que impide la vía oral, embarazo, obstrucción, comorbilidad importante o falta de mejoría en 48 a 72 horas.","No se necesitan estudios de imagen en la pielonefritis no complicada; sí si no mejora en 72 horas (buscar obstrucción o absceso)."]},{"h":"Bacteriuria asintomática","li":["Bacteriuria significativa **sin síntomas**: en la mujer, dos urocultivos con el mismo germen; en el varón y la embarazada basta uno.","**Tratar solo**: embarazo, antes de cirugía o procedimiento urológico invasivo (la guía mexicana agrega trasplante renal y niños).","**No tratar**: adultos mayores, diabéticos, pacientes con sonda permanente ni mujeres sanas no embarazadas."]},{"h":"Infección recurrente","li":["Las reinfecciones no requieren estudios de imagen; corregir factores de riesgo (líquidos, micción después del coito, evitar espermicidas).","**Profilaxis**: nitrofurantoína o trimetoprima con sulfametoxazol en dosis baja diaria o **después del coito** si se relaciona con él.","Posmenopáusicas: **estrógenos vaginales tópicos** disminuyen las recurrencias.","Imagen o referencia solo si hay hematuria persistente, sospecha de litiasis o mala respuesta al tratamiento."]},{"h":"Varón, próstata y epidídimo","li":["Toda infección urinaria en el varón es complicada: urocultivo y tratamiento de **7 días** (trimetoprima con sulfametoxazol o quinolona según antibiograma).","**Prostatitis aguda**: fiebre, dolor perineal, síntomas obstructivos; próstata dolorosa. **No dar masaje prostático**. Quinolonas por 2 a 4 semanas (las que mejor penetran a la próstata).","**Orquiepididimitis**: en menores de 35 años, **Chlamydia trachomatis y gonococo** (ceftriaxona más doxiciclina); en mayores de 35, **enterobacterias** (quinolona).","La uretritis más frecuente es por **Chlamydia trachomatis**."]},{"h":"Paciente con sonda vesical","li":["Con sonda permanente casi todos tienen bacteriuria: **no se cultiva ni se trata** si no hay síntomas.","Sí tratar si hay síntomas o bacteriuria que persiste 3 a 5 días después de retirar la sonda.","Prevención: sonda solo si es indispensable, retirarla pronto, **sistema de drenaje cerrado** y técnica aséptica. El riesgo sube alrededor de 5% por cada día de sonda."]},{"h":"Cuándo referir u hospitalizar","li":["**Urgencias**: pielonefritis con sepsis, vómito persistente, embarazo, sospecha de obstrucción o absceso renal.","**Urología**: recurrencias con hematuria, litiasis, anomalías anatómicas, prostatitis que no mejora o infecciones en el varón de repetición.","**Segundo nivel**: cistitis que persiste después de un segundo esquema guiado por cultivo, con buen apego."]}],"perlas":["Germen más frecuente: **Escherichia coli**; en mujer joven sexualmente activa, después **Staphylococcus saprophyticus**.","Cistitis típica en mujer sana: **tratar sin estudios**.","**Proteus** es resistente a la nitrofurantoína y alcaliniza la orina (litiasis de estruvita).","Bacteriuria asintomática: **solo se trata en el embarazo** y antes de procedimiento urológico.","Punción suprapúbica: **cualquier recuento** es significativo.","Prostatitis aguda: **no hacer masaje prostático**; quinolona 2 a 4 semanas."],"mexico":["La Guía de Práctica Clínica IMSS-077-08 (infección aguda no complicada en la mujer) propone **trimetoprima con sulfametoxazol por 3 días** como primera elección y nitrofurantoína por 7 días como segunda; en regiones con alta resistencia, **fosfomicina 3 g dosis única**. Harrison y las guías actuales prefieren nitrofurantoína 5 días o fosfomicina, porque la resistencia de Escherichia coli a trimetoprima con sulfametoxazol suele ser alta en México.","La misma guía define recurrencia como **3 episodios en 12 meses o 2 en 6 meses**; el CTO usa 4 o más al año.","Para la pielonefritis la guía mexicana indica ciprofloxacino y menciona 7 o 14 días; Harrison recomienda **7 días** de ciprofloxacino en la no complicada.","La guía mexicana desaconseja quinolonas en menores de 21 años; la recomendación general actual es evitarlas en menores de 18 años y reservarlas en cistitis."],"preguntas":[{"c":"Mujer de 26 años con disuria, polaquiuria y urgencia de 2 días. Sin fiebre, sin flujo vaginal, no embarazada.","p":"¿Cuál es la conducta inicial?","o":["Urocultivo y esperar el resultado","Tratamiento antibiótico empírico sin estudios","Ultrasonido renal","Examen general de orina y cita en una semana"],"r":1,"e":"Con dos o más síntomas clásicos y sin datos vaginales, la probabilidad de infección es alta: se trata de forma empírica sin estudios.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Mujer de 22 años, sexualmente activa, con cistitis. El cultivo reporta un coco grampositivo coagulasa negativo resistente a novobiocina.","p":"¿Cuál es el germen?","o":["Staphylococcus epidermidis","Staphylococcus saprophyticus","Enterococcus faecalis","Streptococcus agalactiae"],"r":1,"e":"Staphylococcus saprophyticus es la segunda causa de cistitis en mujeres jóvenes sexualmente activas (10 a 15%).","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer de 30 años con cistitis no complicada. Vive en una zona con resistencia alta a trimetoprima con sulfametoxazol.","p":"¿Qué esquema es adecuado?","o":["Ciprofloxacino 500 mg cada 12 horas por 14 días","Fosfomicina 3 g en dosis única","Amoxicilina 500 mg cada 8 horas por 10 días","Ceftriaxona intramuscular por 5 días"],"r":1,"e":"La fosfomicina 3 g dosis única es de primera línea en la cistitis no complicada y la guía mexicana la propone donde hay resistencia a trimetoprima con sulfametoxazol.","f":"Harrison, capítulo 135"},{"c":"Mujer con pielonefritis aguda no complicada, tolera la vía oral y no tiene datos de sepsis.","p":"¿Qué antibiótico NO es adecuado?","o":["Ciprofloxacino","Nitrofurantoína","Ceftriaxona seguida de vía oral","Trimetoprima con sulfametoxazol según antibiograma"],"r":1,"e":"La nitrofurantoína alcanza concentraciones muy bajas en sangre y en el parénquima renal: no sirve para la pielonefritis.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Urocultivo con Proteus mirabilis en una mujer con cistitis y orina alcalina.","p":"¿Qué fármaco evitarías?","o":["Fosfomicina","Nitrofurantoína","Trimetoprima con sulfametoxazol","Cefalexina"],"r":1,"e":"Proteus es intrínsecamente resistente a la nitrofurantoína, que además solo actúa en orina ácida; Proteus alcaliniza la orina por su ureasa.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer de 78 años, diabética, asintomática. En un examen de rutina el urocultivo reporta 100,000 colonias de Escherichia coli.","p":"¿Qué haces?","o":["Nitrofurantoína 7 días","No dar antibiótico","Ciprofloxacino 3 días","Repetir cada mes hasta negativizar"],"r":1,"e":"La bacteriuria asintomática en adultos mayores y diabéticos no se trata: no mejora desenlaces y aumenta efectos adversos y resistencias.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Embarazada de 14 semanas, asintomática, con urocultivo de 100,000 colonias de Escherichia coli.","p":"¿Cuál es la conducta?","o":["No tratar porque está asintomática","Tratar y pedir urocultivo de control","Esperar al tercer trimestre","Tratar solo si aparece fiebre"],"r":1,"e":"En el embarazo la bacteriuria asintomática se trata porque aumenta el riesgo de pielonefritis y parto pretérmino; después se confirma la erradicación.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Embarazada de 34 semanas con cistitis.","p":"¿Qué antibiótico evitarías?","o":["Fosfomicina","Cefalexina","Trimetoprima con sulfametoxazol","Amoxicilina con ácido clavulánico"],"r":2,"e":"Las sulfonamidas se evitan al final del embarazo por riesgo de kernícterus; las quinolonas, en todo el embarazo.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Hombre de 45 años con disuria y urgencia, sin fiebre.","p":"¿Cómo se clasifica y maneja?","o":["Cistitis no complicada; fosfomicina dosis única","Infección complicada; urocultivo y tratamiento de 7 días","Uretritis; no requiere antibiótico","Prostatitis crónica; 6 semanas de quinolona"],"r":1,"e":"Toda infección urinaria en el varón se considera complicada: se toma urocultivo y se trata 7 días.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Hombre de 60 años con fiebre, dolor perineal, disuria y retención urinaria. Próstata muy dolorosa al tacto.","p":"¿Qué está contraindicado?","o":["Urocultivo","Hemocultivos","Masaje prostático","Quinolona"],"r":2,"e":"En la prostatitis aguda el masaje prostático está contraindicado por riesgo de bacteriemia.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Hombre de 24 años con dolor e inflamación testicular derecha de 3 días, disuria y secreción uretral.","p":"¿Cuál es la causa más probable?","o":["Enterobacterias","Chlamydia trachomatis o gonococo","Torsión testicular","Paperas"],"r":1,"e":"En menores de 35 años la orquiepididimitis suele deberse a Chlamydia y gonococo; en mayores, a enterobacterias.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Hombre de 70 años con sonda vesical permanente, sin fiebre ni síntomas. El urocultivo reporta Klebsiella.","p":"¿Qué haces?","o":["Tratar 14 días","No tratar","Cambiar la sonda y tratar 7 días","Profilaxis continua"],"r":1,"e":"En pacientes con sonda permanente la bacteriuria es casi universal: no se cultiva ni se trata si no hay síntomas.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Muestra obtenida por punción suprapúbica en un lactante con fiebre. Crecen 500 colonias de Escherichia coli.","p":"¿Cómo se interpreta?","o":["Contaminación","Infección: cualquier recuento es significativo","Se repite con bolsa recolectora","Solo es significativo con más de 100,000"],"r":1,"e":"Por punción suprapúbica cualquier número de bacterias es significativo porque la vejiga es estéril.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer con 1 solo síntoma urinario (disuria leve) y sin datos vaginales.","p":"¿Qué estudio es útil?","o":["Urografía excretora","Tira reactiva con nitritos y esterasa leucocitaria","Cistoscopia","Tomografía"],"r":1,"e":"Con un solo síntoma la probabilidad es cercana a 50%: la tira reactiva ayuda; si es positiva se trata.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"En la tira reactiva, ¿qué indica un nitrito positivo?","p":"Elige la opción correcta.","o":["Presencia de leucocitos","Bacterias que reducen nitratos, como las enterobacterias","Hematuria","Proteinuria"],"r":1,"e":"Los nitritos aparecen cuando bacterias gramnegativas reducen los nitratos de la orina; la esterasa leucocitaria indica piuria.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Mujer de 32 años con fiebre de 39 °C, escalofríos, dolor lumbar derecho y puñopercusión positiva; tolera la vía oral.","p":"¿Qué haces antes del antibiótico?","o":["Ultrasonido urgente","Urocultivo","Tomografía","Nada, iniciar y no cultivar"],"r":1,"e":"En la pielonefritis siempre se toma urocultivo antes de iniciar el antibiótico para ajustar el tratamiento.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Misma paciente con pielonefritis no complicada, sin datos de sepsis.","p":"¿Cuál es un tratamiento ambulatorio adecuado?","o":["Fosfomicina dosis única","Ciprofloxacino 500 mg cada 12 horas por 7 días","Nitrofurantoína 5 días","Amoxicilina 3 días"],"r":1,"e":"Ciprofloxacino por 7 días es de elección en la pielonefritis no complicada si la resistencia local lo permite.","f":"Harrison, capítulo 135"},{"c":"Pielonefritis tratada de forma ambulatoria. A las 72 horas sigue con fiebre alta y dolor.","p":"¿Qué sigue?","o":["Agregar paracetamol y esperar","Hospitalizar y buscar obstrucción o absceso con imagen","Cambiar a nitrofurantoína","Suspender el antibiótico"],"r":1,"e":"La falta de respuesta en 48 a 72 horas obliga a hospitalizar y descartar obstrucción, absceso o resistencia.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Mujer de 28 años con 4 cistitis en el último año, todas relacionadas con el coito y con gérmenes distintos.","p":"¿Qué recomiendas?","o":["Urografía excretora","Profilaxis poscoital con una dosis de antibiótico","Cistoscopia","Tratamiento de 6 semanas"],"r":1,"e":"Las reinfecciones relacionadas con el coito se previenen con una dosis de antibiótico después de la relación; no se necesitan estudios de imagen.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer posmenopáusica con cistitis recurrentes.","p":"¿Qué medida reduce las recurrencias?","o":["Estrógenos vaginales tópicos","Espermicidas","Duchas vaginales","Antibiótico de amplio espectro continuo por 2 años"],"r":0,"e":"Los estrógenos vaginales restauran la flora con lactobacilos y disminuyen las recurrencias en posmenopáusicas.","f":"Manual CTO, Urología, capítulo 2"},{"c":"¿Qué define a una recaída?","p":"Elige la opción correcta.","o":["Germen distinto, meses después","Mismo germen, poco después de terminar el tratamiento","Infección por hongos","Bacteriuria con sonda"],"r":1,"e":"Recaída: el mismo germen persiste (por ejemplo, litiasis o prostatitis). La reinfección, más frecuente, es por un germen distinto.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Mujer con cistitis a quien das nitrofurantoína.","p":"¿Qué le recomiendas?","o":["Tomar bicarbonato para la disuria","Evitar alcalinizantes de la orina","Tomarla con antiácidos","Suspenderla al segundo día"],"r":1,"e":"La nitrofurantoína funciona en orina ácida; la guía mexicana aconseja evitar alcalinizantes y antiácidos.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Mujer con cistitis y disuria muy intensa.","p":"¿Qué puedes agregar por 48 horas?","o":["Fenazopiridina","Prednisona","Ketorolaco intramuscular diario por 7 días","Oxibutinina por 1 mes"],"r":0,"e":"La fenazopiridina 100 mg cada 8 horas por 48 horas alivia la disuria; tiñe la orina de naranja.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Hombre de 52 años con urocultivos repetidos positivos al mismo germen y molestias perineales de meses.","p":"¿Qué sospechas?","o":["Cistitis aguda simple","Prostatitis bacteriana crónica","Pielonefritis aguda","Uretritis por Chlamydia"],"r":1,"e":"La prostatitis bacteriana crónica es causa clásica de recaídas por el mismo germen; requiere quinolona por varias semanas.","f":"Manual CTO, Urología, capítulo 2"},{"c":"¿Cuál es la vía más frecuente por la que las bacterias llegan a la vía urinaria?","p":"Elige la opción correcta.","o":["Hematógena","Linfática","Ascendente desde la uretra","Por contigüidad intestinal"],"r":2,"e":"La vía ascendente es la más común; por eso es más frecuente en la mujer, cuya uretra es corta.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Paciente hospitalizado con sonda vesical.","p":"¿Qué medida reduce más la infección?","o":["Irrigación vesical diaria","Retirar la sonda lo antes posible y usar sistema cerrado","Antibiótico profiláctico continuo","Cambiar la sonda cada 24 horas"],"r":1,"e":"El riesgo sube con cada día de sonda; la medida más eficaz es retirarla pronto y usar drenaje cerrado.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer con síntomas urinarios y además flujo vaginal con prurito.","p":"¿Qué haces?","o":["Tratar como cistitis sin explorar","Explorar en busca de vaginitis o infección de transmisión sexual","Pedir tomografía","Dar quinolona de amplio espectro"],"r":1,"e":"Los síntomas vaginales disminuyen la probabilidad de cistitis y obligan a buscar otro diagnóstico con exploración pélvica.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"En cistitis no complicada, ¿qué grupo de antibióticos NO se recomienda de forma empírica?","p":"Elige la opción correcta.","o":["Fosfomicina","Nitrofurantoína","Quinolonas","Betalactámicos orales como alternativa"],"r":2,"e":"Las quinolonas se reservan para infecciones más graves por resistencias y efectos adversos; la guía mexicana también lo indica.","f":"Guía de Práctica Clínica IMSS-077-08"},{"c":"Urocultivo en mujer sintomática con piuria: 10,000 colonias de Escherichia coli.","p":"¿Cómo se interpreta?","o":["Contaminación segura","Puede corresponder a infección activa en mujer sintomática","Solo es válido con 1,000,000","Indica tuberculosis"],"r":1,"e":"En mujeres sintomáticas con piuria recuentos menores (desde 1,000) pueden ser significativos.","f":"Manual CTO, Urología, capítulo 2"},{"c":"Mujer de 25 años con cistitis tratada; los síntomas ceden por completo.","p":"¿Necesita urocultivo de control?","o":["Sí, siempre","No, si respondió bien","Sí, cada mes por 6 meses","Solo ultrasonido"],"r":1,"e":"La cistitis no complicada que responde no requiere seguimiento con cultivo.","f":"Guía de Práctica Clínica IMSS-077-08"}],"audio":[["¿Cuál es el germen más frecuente de infección urinaria?","Escherichia coli. En mujeres jóvenes sexualmente activas, después sigue Staphylococcus saprophyticus."],["¿Cuándo tratas una cistitis sin estudios?","Mujer sana, no embarazada, con dos o más síntomas clásicos y sin flujo vaginal."],["Dime tres esquemas para la cistitis no complicada.","Fosfomicina 3 gramos dosis única; nitrofurantoína 100 miligramos cada 12 horas por 5 a 7 días; o trimetoprima con sulfametoxazol cada 12 horas por 3 días si la resistencia es baja."],["¿Por qué no usar nitrofurantoína en la pielonefritis?","Porque casi no alcanza concentraciones en sangre ni en el riñón."],["¿Qué germen es resistente a la nitrofurantoína?","Proteus, que además alcaliniza la orina."],["¿A quién le tratas la bacteriuria asintomática?","A la embarazada y antes de un procedimiento urológico invasivo."],["¿Qué antibióticos evitas en el embarazo?","Quinolonas en todo el embarazo y sulfonamidas en el tercer trimestre."],["¿Cómo tratas una pielonefritis no complicada ambulatoria?","Urocultivo antes y ciprofloxacino 500 miligramos cada 12 horas por 7 días."],["¿Cuándo hospitalizas una pielonefritis?","Sepsis, vómito, embarazo, obstrucción, comorbilidad o falta de mejoría en 48 a 72 horas."],["¿Cómo se considera la infección urinaria en el varón?","Complicada: urocultivo y 7 días de tratamiento."],["¿Qué no se hace en la prostatitis aguda?","Masaje prostático."],["¿Causa de orquiepididimitis según la edad?","Menores de 35: Chlamydia y gonococo. Mayores de 35: enterobacterias."],["¿Qué recuento es significativo por punción suprapúbica?","Cualquier recuento."],["¿Se trata la bacteriuria en un paciente con sonda permanente?","No, si no tiene síntomas."]],"profundizar":{"harrison":[[135,"Infecciones de vías urinarias, pielonefritis y prostatitis"]],"guias":[["Diagnóstico y tratamiento de la infección aguda, no complicada del tracto urinario en la mujer, IMSS-077-08 (versión extensa)","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/077GER.pdf"],["Misma guía, referencia rápida","https://www.imss.gob.mx/sites/all/statics/guiasclinicas/077GRR.pdf"]]},"fuentes":["Manual CTO de Medicina y Cirugía, 14.ª edición, Urología, capítulo 2, páginas 6 a 13 del archivo.","Guía de Práctica Clínica IMSS-077-08: Diagnóstico y tratamiento de la infección aguda, no complicada del tracto urinario en la mujer, Instituto Mexicano del Seguro Social.","Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 135."]}};
